    chapter_number integer NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    pdf_url text,
    markdown_content text DEFAULT ''::text NOT NULL,
    pages_json jsonb DEFAULT '[]'::jsonb NOT NULL,
    key_analogies jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    title_i18n jsonb,
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: courses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.courses (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    teacher_id uuid,
    code text NOT NULL,
    title text NOT NULL,
    description text,
    content_language text DEFAULT 'fr'::text NOT NULL,
    tutor_language text DEFAULT 'en'::text NOT NULL,
    file_extensions text[] DEFAULT ARRAY['.java'::text] NOT NULL,
    stuck_threshold_turns integer DEFAULT 2 NOT NULL,
    competency_matrix jsonb DEFAULT '[]'::jsonb NOT NULL,
    compiled_tutor_prompt text DEFAULT ''::text NOT NULL,
    compiled_knowledge_base text DEFAULT ''::text NOT NULL,
    is_published boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);


--
-- Name: labs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.labs (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    course_id uuid NOT NULL,
    lab_number integer NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    description text,
    pdf_url text,
    activities jsonb DEFAULT '[]'::jsonb NOT NULL,
    covered_micro_concepts text[] DEFAULT ARRAY[]::text[] NOT NULL,
    demo_presets jsonb DEFAULT '[]'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    pages_json jsonb DEFAULT '[]'::jsonb NOT NULL,
    title_i18n jsonb,
    description_i18n jsonb,
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    email text,
    role text DEFAULT 'student'::text NOT NULL,
    display_name text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    is_guest boolean DEFAULT false NOT NULL,
    CONSTRAINT profiles_role_check CHECK ((role = ANY (ARRAY['student'::text, 'teacher'::text])))
);


--
-- Name: student_lab_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.student_lab_sessions (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    course_id uuid NOT NULL,
    lab_id uuid NOT NULL,
    student_id uuid NOT NULL,
    seat_label character varying(60) DEFAULT 'Room A0-10 - PC 12'::character varying NOT NULL,
    status text DEFAULT 'NOT_STARTED'::text NOT NULL,
    current_activity_id text,
    current_milestone_id text,
    completed_milestone_ids text[] DEFAULT ARRAY[]::text[] NOT NULL,
    activities_progress jsonb DEFAULT '{}'::jsonb NOT NULL,
    progress_percent integer DEFAULT 0 NOT NULL,
    consecutive_errors integer DEFAULT 0 NOT NULL,
    micro_competencies_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_diagnostic_note text,
    completion_report jsonb,
    started_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    last_stuck_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT student_lab_sessions_progress_percent_check CHECK (((progress_percent >= 0) AND (progress_percent <= 100))),
    CONSTRAINT student_lab_sessions_status_check CHECK ((status = ANY (ARRAY['NOT_STARTED'::text, 'IN_PROGRESS'::text, 'BLOCKED'::text, 'COMPLETED'::text])))
);


