flerie soufflerie;\\n}\\n```"}}	[{"name": "Article.java", "content": "public class Article {\\n  private String designation;\\n  private double prixHT;\\n  private String codeBarre;\\n\\n  public Article(String designation, double prixHT, String codeBarre) {\\n    this.designation = designation;\\n    this.codeBarre = codeBarre;\\n    this.setPrixHT(prixHT);\\n  }\\n\\n  public Article(String designation, double prixHT) {\\n    this(designation, prixHT, \\"000000\\");\\n  }\\n\\n  public String getDesignation() {\\n    return this.designation;\\n  }\\n\\n  public double getPrixHT() {\\n    return this.prixHT;\\n  }\\n\\n  public String getCodeBarre() {\\n    return this.codeBarre;\\n  }\\n\\n  public void setPrixHT(double prixHT) {\\n    if (prixHT < 0) {\\n      System.out.println(\\"Erreur : Le prix ne peut pas être négatif !\\");\\n      return;\\n    }\\n    this.prixHT = prixHT;\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article[] panier = new Article[2];\\n    panier[0] = new Article(\\"Lait\\", 2.5, \\"123456\\");\\n    panier[1] = new Article(\\"Pommes\\", 3.0);\\n    System.out.println(panier[0].getPrixHT());\\n    System.out.println(panier[1].getCodeBarre());\\n    panier[0].setPrixHT(-100.0);\\n    System.out.println(panier[0].getPrixHT());\\n  }\\n}"}]	13564	2026-11-01 21:41:33.555349+00	act_2
