sse contient au moins une méthode abstraite, alors la classe doit, elle aussi, être définie ainsi"}}	[{"name": "Felin.java", "content": "public abstract class Felin {\\n  abstract void parler();\\n}\\n"}, {"name": "Tigre.java", "content": "public class Tigre extends Felin {\\n  @Override\\n  void parler() {\\n    System.out.println(\\"Rugissement du tigre !\\");\\n  }\\n}\\n"}, {"name": "Chat.java", "content": "public class Chat extends Felin {\\n  private String race;\\n\\n  public Chat(String race) {\\n    this.race = race;\\n  }\\n\\n  @Override\\n  void parler() {\\n    System.out.println(\\"Miaou !\\");\\n  }\\n\\n  public String getRace() {\\n    return race;\\n  }\\n}\\n"}, {"name": "Zoo.java", "content": "public class Zoo {\\n  Felin[] liste = new Felin[10];\\n  int nb = 0;\\n  public void addFelin(Felin newFelin) {\\n    if (nb < liste.length) liste[nb++] = newFelin;\\n  }\\n  public void appeler() {\\n    for (int i = 0; i < nb; i++) {\\n      liste[i].parler();\\n    }\\n  }\\n  public static void main(String[] args) {\\n    Zoo z = new Zoo();\\n    z.addFelin(new Tigre());\\n    z.addFelin(new Chat(\\"Siamois\\"));\\n    z.appeler();\\n  }\\n}\\n"}]	13778	2026-11-01 22:03:16.15599+00	act_1
