COPY public.labs (id, course_id, lab_number, code, title, description, pdf_url, activities, covered_micro_concepts, demo_presets, is_active, created_at, pages_json, title_i18n, description_i18n, updated_at) FROM stdin;
c8b4723b-041b-419f-8c54-50018898cd25	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	8	TP8	TP 8 — Lab 8: Polymorphism, Abstract Classes and the instanceof Operator	This lab teaches abstract classes and runtime polymorphism with a feline zoo, then applies instanceof and downcasting to secure the Yalla POS model.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp8.pdf	[{"id": "act_1", "order": 1, "title": "Activity No.1 (Independent): The Polymorphic and Abstract Zoo", "milestones": [{"id": "m1_1", "order": 1, "title": "Abstract Felin and abstract parler", "title_i18n": {"en": "Abstract Felin and abstract parler", "fr": "Felin abstraite et parler abstraite"}, "validation_criteria": "`Felin` is declared `abstract class Felin`, `parler()` is declared `abstract void parler();` without body, and `new Felin()` is rejected by the compiler.", "validation_criteria_i18n": {"en": "`Felin` is declared `abstract class Felin`, `parler()` is declared `abstract void parler();` without body, and `new Felin()` is rejected by the compiler.", "fr": "`Felin` est déclarée `abstract class Felin`, `parler()` est déclarée `abstract void parler();` sans corps, et `new Felin()` est refusé par le compilateur."}}, {"id": "m1_2", "order": 2, "title": "Zoo storage with Felin array", "title_i18n": {"en": "Zoo storage with Felin array", "fr": "Stockage Zoo avec tableau de Felin"}, "validation_criteria": "`Zoo` holds `Felin[] liste = new Felin[10];` and `addFelin(Felin newFelin)` stores Tigre and Chat instances in the array.", "validation_criteria_i18n": {"en": "`Zoo` holds `Felin[] liste = new Felin[10];` and `addFelin(Felin newFelin)` stores Tigre and Chat instances in the array.", "fr": "`Zoo` contient `Felin[] liste = new Felin[10];` et `addFelin(Felin newFelin)` stocke des instances `Tigre` et `Chat` dans le tableau."}}, {"id": "m1_3", "order": 3, "title": "Polymorphic appeler dispatch", "title_i18n": {"en": "Polymorphic appeler dispatch", "fr": "Répartition polymorphe de appeler"}, "validation_criteria": "`appeler()` iterates the array and calls `liste[i].parler();`, each object executing its own overridden version at runtime.", "validation_criteria_i18n": {"en": "`appeler()` iterates the array and calls `liste[i].parler();`, each object executing its own overridden version at runtime.", "fr": "`appeler()` parcourt le tableau et appelle `liste[i].parler();`, chaque objet exécutant sa propre version redéfinie à l'exécution."}}], "title_i18n": {"en": "Activity No.1 (Independent): The Polymorphic and Abstract Zoo", "fr": "Activité N°1 (Indépendante) : Le Zoo Polymorphe et Abstrait"}, "target_files": ["Felin.java", "Tigre.java", "Chat.java", "Zoo.java"], "instructions_i18n": {"en": "Scenario: Explore abstraction and polymorphism with a zoo of felines.\\n\\n**Implementation Steps:**\\n1. Make abstraction explicit:\\n   * Add `abstract` to `Felin` to get `abstract class Felin`.\\n   * Transform `parler()` into `abstract void parler();` without implementation.\\n   * Verify that `Felin f = new Felin();` in `main` fails to compile.\\n2. Build polymorphic storage in `Zoo`:\\n   * Declare `Felin[] liste = new Felin[10];`.\\n   * Add `addFelin(Felin newFelin)` to fill the array.\\n3. Demonstrate dynamic dispatch:\\n   * In `main`, instantiate a `Zoo` and add `Tigre` and `Chat` objects that override `parler()`.\\n   * Create `appeler()` in `Zoo` that loops and calls `liste[i].parler();` so each feline answers with its own cry.", "fr": "Scénario : Manipuler l'abstraction et le polymorphisme avec un zoo de félins.\\n\\n**Étapes de réalisation :**\\n1. Rendre l'abstraction explicite :\\n   * Ajouter `abstract` à `Felin` pour obtenir `abstract class Felin`.\\n   * Transformer `parler()` en `abstract void parler();` sans implémentation.\\n   * Vérifier que `Felin f = new Felin();` dans `main` provoque une erreur de compilation.\\n2. Construire le stockage polymorphe dans `Zoo` :\\n   * Déclarer `Felin[] liste = new Felin[10];`.\\n   * Ajouter `addFelin(Felin newFelin)` pour remplir le tableau.\\n3. Démontrer la liaison dynamique :\\n   * Dans `main`, instancier un `Zoo` et y ajouter des objets `Tigre` et `Chat` qui redéfinissent obligatoirement `parler()`.\\n   * Créer `appeler()` dans `Zoo` qui parcourt le tableau et invoque `liste[i].parler();` pour que chaque félin réponde avec son propre cri."}, "instructions_markdown": "Scenario: Explore abstraction and polymorphism with a zoo of felines.\\n\\n**Implementation Steps:**\\n1. Make abstraction explicit:\\n   * Add `abstract` to `Felin` to get `abstract class Felin`.\\n   * Transform `parler()` into `abstract void parler();` without implementation.\\n   * Verify that `Felin f = new Felin();` in `main` fails to compile.\\n2. Build polymorphic storage in `Zoo`:\\n   * Declare `Felin[] liste = new Felin[10];`.\\n   * Add `addFelin(Felin newFelin)` to fill the array.\\n3. Demonstrate dynamic dispatch:\\n   * In `main`, instantiate a `Zoo` and add `Tigre` and `Chat` objects that override `parler()`.\\n   * Create `appeler()` in `Zoo` that loops and calls `liste[i].parler();` so each feline answers with its own cry."}, {"id": "act_2", "order": 2, "title": "Activity No.2 (Red Thread Project): Banning Generic Items in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Abstract Article model", "title_i18n": {"en": "Abstract Article model", "fr": "Modèle Article abstrait"}, "validation_criteria": "`Article` is declared abstract and declares `public abstract boolean estGarantieValide();`, preventing direct instantiation.", "validation_criteria_i18n": {"en": "`Article` is declared abstract and declares `public abstract boolean estGarantieValide();`, preventing direct instantiation.", "fr": "`Article` est déclarée abstract et déclare `public abstract boolean estGarantieValide();`, empêchant l'instanciation directe."}}, {"id": "m2_2", "order": 2, "title": "Warranty implementations in daughters", "title_i18n": {"en": "Warranty implementations in daughters", "fr": "Implémentations de garantie dans les filles"}, "validation_criteria": "`ArticlePerissable` implements `estGarantieValide()` returning false and `ArticleElectronique` implements `estGarantieValide()` returning true only if warranty months > 0.", "validation_criteria_i18n": {"en": "`ArticlePerissable` implements `estGarantieValide()` returning false and `ArticleElectronique` implements `estGarantieValide()` returning true only if warranty months > 0.", "fr": "`ArticlePerissable` implémente `estGarantieValide()` retournant false et `ArticleElectronique` implémente `estGarantieValide()` retournant true seulement si mois de garantie > 0."}}, {"id": "m2_3", "order": 3, "title": "instanceof check and downcast at checkout", "title_i18n": {"en": "instanceof check and downcast at checkout", "fr": "Test instanceof et downcast en caisse"}, "validation_criteria": "`YallaPOS` loop over `panier` uses `instanceof ArticlePerissable`, casts with `(ArticlePerissable) panier[i]` to `ap`, then calls `ap.getDateExpiration()` to display the peremption alert.", "validation_criteria_i18n": {"en": "`YallaPOS` loop over `panier` uses `instanceof ArticlePerissable`, casts with `(ArticlePerissable) panier[i]` to `ap`, then calls `ap.getDateExpiration()` to display the peremption alert.", "fr": "La boucle `YallaPOS` sur `panier` utilise `instanceof ArticlePerissable`, caste avec `(ArticlePerissable) panier[i]` vers `ap`, puis appelle `ap.getDateExpiration()` pour afficher l'alerte de péremption."}}], "title_i18n": {"en": "Activity No.2 (Red Thread Project): Banning Generic Items in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : Interdiction des articles génériques dans Yalla POS"}, "target_files": ["Article.java", "ArticlePerissable.java", "ArticleElectronique.java", "YallaPOS.java"], "instructions_i18n": {"en": "Scenario: Forbid generic items in Yalla POS by making the model abstract and handling perishables specifically at checkout.\\n\\n**Implementation Steps:**\\n1. Secure the model with `abstract`:\\n   * Declare `Article` as `abstract`.\\n   * Declare `public abstract boolean estGarantieValide();` in `Article`.\\n2. Implement in subclasses:\\n   * In `ArticlePerissable`, implement `estGarantieValide()` to always return `false`.\\n   * In `ArticleElectronique`, implement `estGarantieValide()` to return `true` if warranty duration in months is greater than 0.\\n3. Specific checkout processing with `instanceof` and cast:\\n   * In `YallaPOS`, when printing the ticket by looping over `panier`, use `instanceof` to test if the current `Article` is an `ArticlePerissable`.\\n   * Perform explicit cast `ArticlePerissable ap = (ArticlePerissable) panier[i];`.\\n   * Via the cast, call `getDateExpiration()` and display `*** ATTENTION : Vérifier la date de péremption ( + ap.getDateExpiration() + ) ***`.", "fr": "Scénario : Interdire les articles génériques dans Yalla POS en rendant le modèle abstrait et en traitant les périssables spécifiquement en caisse.\\n\\n**Étapes de réalisation :**\\n1. Sécuriser le modèle avec `abstract` :\\n   * Déclarer `Article` comme `abstract`.\\n   * Déclarer `public abstract boolean estGarantieValide();` dans `Article`.\\n2. Implémenter dans les classes filles :\\n   * Dans `ArticlePerissable`, implémenter `estGarantieValide()` qui retourne toujours `false`.\\n   * Dans `ArticleElectronique`, implémenter `estGarantieValide()` qui retourne `true` si la durée de garantie en mois est supérieure à 0.\\n3. Traitement spécifique en caisse avec `instanceof` et cast :\\n   * Dans `YallaPOS`, lors de l'impression du ticket en parcourant `panier`, utiliser `instanceof` pour vérifier si l'article courant est un `ArticlePerissable`.\\n   * Effectuer le transtypage explicite `ArticlePerissable ap = (ArticlePerissable) panier[i];`.\\n   * Grâce au cast, appeler `getDateExpiration()` et afficher `*** ATTENTION : Vérifier la date de péremption ( + ap.getDateExpiration() + ) ***`."}, "instructions_markdown": "Scenario: Forbid generic items in Yalla POS by making the model abstract and handling perishables specifically at checkout.\\n\\n**Implementation Steps:**\\n1. Secure the model with `abstract`:\\n   * Declare `Article` as `abstract`.\\n   * Declare `public abstract boolean estGarantieValide();` in `Article`.\\n2. Implement in subclasses:\\n   * In `ArticlePerissable`, implement `estGarantieValide()` to always return `false`.\\n   * In `ArticleElectronique`, implement `estGarantieValide()` to return `true` if warranty duration in months is greater than 0.\\n3. Specific checkout processing with `instanceof` and cast:\\n   * In `YallaPOS`, when printing the ticket by looping over `panier`, use `instanceof` to test if the current `Article` is an `ArticlePerissable`.\\n   * Perform explicit cast `ArticlePerissable ap = (ArticlePerissable) panier[i];`.\\n   * Via the cast, call `getDateExpiration()` and display `*** ATTENTION : Vérifier la date de péremption ( + ap.getDateExpiration() + ) ***`."}]	{ABSTRACT_POLYMORPHISM,EXTENDS_SINGLE_INHERITANCE,DOWNCAST_COMPATIBILITY}	[{"key": "act_1_buggy", "files": [{"name": "Felin.java", "content": "public class Felin {\\n  void parler() {\\n    System.out.println(\\"Felin generique\\");\\n  }\\n}"}, {"name": "Tigre.java", "content": "public class Tigre extends Felin {\\n  public void crier() {\\n    System.out.println(\\"Grrr !\\");\\n  }\\n}"}, {"name": "Chat.java", "content": "public class Chat extends Felin {\\n  public void crier() {\\n    System.out.println(\\"Miaou !\\");\\n  }\\n}"}, {"name": "Zoo.java", "content": "public class Zoo {\\n  Felin[] liste = new Felin[10];\\n  int nb = 0;\\n  public void addFelin(Felin newFelin) {\\n    liste[nb++] = newFelin;\\n  }\\n  public void appeler() {\\n    for (int i = 0; i < nb; i++) {\\n      liste[i].parler();\\n    }\\n  }\\n  public static void main(String[] args) {\\n    Felin f = new Felin();\\n    Zoo z = new Zoo();\\n    z.addFelin(new Tigre());\\n    z.addFelin(new Chat());\\n    z.appeler();\\n  }\\n}"}], "label": "1. Buggy Zoo (No Abstract, No Override)", "activity_id": "act_1", "description": "Forgets abstract and overrides wrong method, so polymorphism fails and Felin can be instantiated.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Felin.java", "content": "public abstract class Felin {\\n  abstract void parler();\\n}"}, {"name": "Tigre.java", "content": "public class Tigre extends Felin {\\n  @Override\\n  void parler() {\\n    System.out.println(\\"Grrr ! Je suis un tigre\\");\\n  }\\n}"}, {"name": "Chat.java", "content": "public class Chat extends Felin {\\n  @Override\\n  void parler() {\\n    System.out.println(\\"Miaou ! Je suis un chat\\");\\n  }\\n}"}, {"name": "Zoo.java", "content": "public class Zoo {\\n  Felin[] liste = new Felin[10];\\n  int nb = 0;\\n  public void addFelin(Felin newFelin) {\\n    if (nb < liste.length) {\\n      liste[nb++] = newFelin;\\n    }\\n  }\\n  public void appeler() {\\n    for (int i = 0; i < nb; i++) {\\n      liste[i].parler();\\n    }\\n  }\\n  public static void main(String[] args) {\\n    Zoo z = new Zoo();\\n    z.addFelin(new Tigre());\\n    z.addFelin(new Chat());\\n    z.appeler();\\n  }\\n}"}], "label": "2. Validated Solution (Abstract Polymorphic Zoo)", "activity_id": "act_1", "description": "Abstract Felin with polymorphic Zoo dispatching Tigre and Chat cries.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Article.java", "content": "public class Article {\\n  protected String nom;\\n  protected double prix;\\n  public Article(String nom, double prix) {\\n    this.nom = nom;\\n    this.prix = prix;\\n  }\\n  public String getNom() { return nom; }\\n}"}, {"name": "ArticlePerissable.java", "content": "public class ArticlePerissable extends Article {\\n  private String dateExpiration;\\n  public ArticlePerissable(String nom, double prix, String dateExpiration) {\\n    super(nom, prix);\\n    this.dateExpiration = dateExpiration;\\n  }\\n  public String getDateExpiration() { return dateExpiration; }\\n}"}, {"name": "ArticleElectronique.java", "content": "public class ArticleElectronique extends Article {\\n  private int garantieMois;\\n  public ArticleElectronique(String nom, double prix, int garantieMois) {\\n    super(nom, prix);\\n    this.garantieMois = garantieMois;\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article[] panier = new Article[2];\\n    panier[0] = new ArticlePerissable(\\"Lait\\", 2.5, \\"12/12/2026\\");\\n    panier[1] = new ArticleElectronique(\\"TV\\", 500.0, 12);\\n    for (int i = 0; i < panier.length; i++) {\\n      System.out.println(panier[i].getNom());\\n      System.out.println(panier[i].getDateExpiration());\\n    }\\n  }\\n}"}], "label": "1. Buggy YallaPOS (No Abstract, No instanceof)", "activity_id": "act_2", "description": "Article stays concrete and checkout calls getDateExpiration without instanceof and cast.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Article.java", "content": "public abstract class Article {\\n  protected String nom;\\n  protected double prix;\\n  public Article(String nom, double prix) {\\n    this.nom = nom;\\n    this.prix = prix;\\n  }\\n  public abstract boolean estGarantieValide();\\n  public String getNom() { return nom; }\\n}"}, {"name": "ArticlePerissable.java", "content": "public class ArticlePerissable extends Article {\\n  private String dateExpiration;\\n  public ArticlePerissable(String nom, double prix, String dateExpiration) {\\n    super(nom, prix);\\n    this.dateExpiration = dateExpiration;\\n  }\\n  @Override\\n  public boolean estGarantieValide() { return false; }\\n  public String getDateExpiration() { return dateExpiration; }\\n}"}, {"name": "ArticleElectronique.java", "content": "public class ArticleElectronique extends Article {\\n  private int garantieMois;\\n  public ArticleElectronique(String nom, double prix, int garantieMois) {\\n    super(nom, prix);\\n    this.garantieMois = garantieMois;\\n  }\\n  @Override\\n  public boolean estGarantieValide() { return garantieMois > 0; }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article[] panier = new Article[2];\\n    panier[0] = new ArticlePerissable(\\"Lait\\", 2.5, \\"12/12/2026\\");\\n    panier[1] = new ArticleElectronique(\\"TV\\", 500.0, 12);\\n    for (int i = 0; i < panier.length; i++) {\\n      System.out.println(panier[i].getNom() + \\" garantie: \\" + panier[i].estGarantieValide());\\n      if (panier[i] instanceof ArticlePerissable) {\\n        ArticlePerissable ap = (ArticlePerissable) panier[i];\\n        System.out.println(\\"*** ATTENTION : Verifier la date de peremption (\\" + ap.getDateExpiration() + \\") ***\\");\\n      }\\n    }\\n  }\\n}"}], "label": "2. Validated Solution (Abstract + instanceof Cast)", "activity_id": "act_2", "description": "Abstract Article with warranty contract and instanceof plus cast to show expiration alert.", "preset_type": "solution"}]	t	2026-11-01 22:19:16.426+00	[{"page": 1, "text": "TP 8 : Polymorphisme, Classes Abstraites et l'opérateur instanceof\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Comprendre et exploiter le polymorphisme, où la version de la méthode exécutée\\ndépend du type réel de l'objet contenu dans la référence.\\n Déclarer des classes et des méthodes abstraites en utilisant le mot-clé abstract .\\n Utiliser l'opérateur instanceof pour tester si un objet référencé est une instance\\nd'une classe donnée ou de l'une de ses sous-classes.\\n Appréhender la classe cosmique Object , ancêtre de toutes les classes, et maîtriser la\\nconversion explicite (cast).\\nActivité N°1 (Indépendante) : Le Zoo Polymorphe et Abstrait\\nDans cette activité, nous allons manipuler les concepts d'abstraction et de polymorphisme\\nen utilisant le scénario d'un zoo contenant divers félins.\\n1. L'Abstraction :\\no Reprenez votre classe Felin du TP précédent et ajoutez-lui le mot-clé\\nabstract avant class .\\no Transformez la méthode parler() en une méthode abstraite : abstract\\nvoid parler(); (remarquez qu'on donne le prototype sans décrire\\nl'implémentation).\\no Dans votre main , essayez d'écrire Felin f = new Felin(); . Le compilateur\\ndoit afficher une erreur, car une classe abstraite ne peut pas être instanciée\\ndirectement avec new .\\n2. Le Polymorphisme en action :\\no Créez une classe Zoo qui contient un tableau de références de type Felin\\n( Felin[] liste = new Felin[10]; ).\\no Ajoutez une méthode addFelin(Felin newFelin) pour remplir ce tableau.\\no Dans votre main , instanciez un Zoo et ajoutez-y des objets de type Tigre et\\nChat (qui héritent de Felin et redéfinissent obligatoirement parler() ).\\no Créez une méthode appeler() dans Zoo qui parcourt le tableau et invoque\\nliste[i].parler(); . Observez le résultat : chaque félin répond avec son\\npropre cri grâce au polymorphisme !\\nActivité N°2 (Projet Fil Rouge) : Interdiction des articles génériques dans Yalla POS\\nDans un vrai commerce, un \\"Article\\" générique n'existe pas : on vend un produit frais, un\\nappareil électronique, un vêtement, etc. La classe Article est en réalité un simple\\n\\"concept\\" qui sert de moule. Nous allons donc la rendre abstraite et exploiter l'opérateur\\ninstanceof pour déclencher des actions spécifiques en caisse.\\nTravail demandé :\\n1. Sécurisation du Modèle (abstract) :"}, {"page": 2, "text": "TP 8 : Polymorphisme, Classes Abstraites et l'opérateur instanceof Mohamed Belhassen\\no Ouvrez la classe Article et déclarez-la comme abstract .\\no Déclarez une méthode abstraite public abstract boolean\\nestGarantieValide(); dans la classe Article . (Seules les classes filles non\\nabstraites pourront désormais être instanciées et devront obligatoirement\\nfournir le code de cette méthode).\\n2. Implémentation dans les classes filles :\\no Dans ArticlePerissable , implémentez la méthode : elle retournera\\ntoujours false (un produit frais n'a pas de garantie matérielle).\\no Dans ArticleElectronique , implémentez la méthode : elle retournera true\\nsi la durée de garantie (en mois) est supérieure à 0.\\n3. Traitement spécifique en Caisse (instanceof & Cast) :\\no Dans YallaPOS , lors de l'impression du ticket (boucle qui parcourt le tableau\\npanier ), utilisez l'opérateur instanceof pour vérifier si l'article courant est\\nun ArticlePerissable .\\no Si c'est le cas, effectuez un transtypage (cast) explicite de la référence\\ngénérique Article vers le type spécifique ArticlePerissable . Exemple :\\nArticlePerissable ap = (ArticlePerissable) panier[i];\\no Grâce à ce cast, appelez la méthode getDateExpiration() (qui n'existe pas\\ndans Article ) et affichez une alerte en caisse : *** ATTENTION : Vérifier\\nla date de péremption ( + ap.getDateExpiration() + ) *** .\\nBilan du TP 8 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Classe Abstraite : Vous avez compris qu'une classe abstract sert uniquement de\\nmodèle de base et empêche la création d'objets incomplets ou trop génériques.\\n [ ] Méthode Abstraite : Vous savez forcer toutes les classes filles à développer leur\\npropre version d'une méthode.\\n [ ] Polymorphisme : Vous constatez que Java détermine automatiquement, au\\nmoment de l'exécution, quelle version de la méthode appeler en fonction du\\nvéritable type de l'objet.\\n [ ] Transtypage (Downcasting) : Vous maîtrisez l'utilisation de instanceof couplée\\nau cast pour retrouver l'accès aux méthodes spécifiques d'une sous-classe.\\nLa suite : L'héritage ( extends ) est très puissant, mais en Java, une classe ne peut avoir\\nqu'une seule classe mère. Imaginons que dans Yalla POS, nous souhaitions vendre des\\n\\"Services\\" (ex: Livraison, Installation). Un Service n'est pas un Article (il n'a pas de stock),\\nmais il a un prix et doit pouvoir être facturé sur le même ticket de caisse. Comment\\nregrouper des objets totalement différents sous un même type pour les manipuler ensemble\\n? La réponse se trouve dans les Interfaces (mot-clé implements ), que nous allons découvrir\\nlors du prochain TP !"}]	{"en": "TP 8 — Lab 8: Polymorphism, Abstract Classes and the instanceof Operator", "fr": "TP 8 : Polymorphisme, Classes Abstraites et l'opérateur instanceof"}	{"en": "This lab teaches abstract classes and runtime polymorphism with a feline zoo, then applies instanceof and downcasting to secure the Yalla POS model.", "fr": "Ce TP enseigne les classes abstraites et le polymorphisme à l'exécution via un zoo de félins, puis applique instanceof et le downcasting pour sécuriser le modèle Yalla POS."}	2026-11-02 20:07:42.438083+00
4fa52314-0df0-41ad-aba8-a92d195695d2	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	9	TP9	TP 9 — Lab 9: Definition and Implementation of Interfaces	This lab teaches interfaces as contracts decoupled from inheritance, first via a polymorphic download manager then by generalizing the Yalla POS basket to cash both articles and services.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp9.pdf	[{"id": "act_1", "order": 1, "title": "Activity No.1 (Independent): The Download Manager", "milestones": [{"id": "m1_1", "order": 1, "title": "Downloadable interface with baseURL constant", "title_i18n": {"en": "Downloadable interface with baseURL constant", "fr": "Interface Downloadable avec constante baseURL"}, "validation_criteria": "The `Downloadable` interface declares `String baseURL = \\"http://monsite.tn/\\"` (implicitly public static final) and the signature `void printDownloadURL();`.", "validation_criteria_i18n": {"en": "The `Downloadable` interface declares `String baseURL = \\"http://monsite.tn/\\"` (implicitly public static final) and the signature `void printDownloadURL();`.", "fr": "L'interface `Downloadable` déclare `String baseURL = \\"http://monsite.tn/\\"` (implicitement public static final) et la signature `void printDownloadURL();`."}}, {"id": "m1_2", "order": 2, "title": "Document and Program implementations", "title_i18n": {"en": "Document and Program implementations", "fr": "Implémentations Document et Program"}, "validation_criteria": "Classes `Document` (with `titre`, `fileName`) and `Program` (with `nomProgramme`, `programFileName`) declare `implements Downloadable` and each implements `printDownloadURL()` displaying `baseURL + fileName`.", "validation_criteria_i18n": {"en": "Classes `Document` (with `titre`, `fileName`) and `Program` (with `nomProgramme`, `programFileName`) declare `implements Downloadable` and each implements `printDownloadURL()` displaying `baseURL + fileName`.", "fr": "Les classes `Document` (avec `titre`, `fileName`) et `Program` (avec `nomProgramme`, `programFileName`) déclarent `implements Downloadable` et implémentent chacune `printDownloadURL()` affichant `baseURL + fileName`."}}, {"id": "m1_3", "order": 3, "title": "Polymorphism via DownloadManager", "title_i18n": {"en": "Polymorphism via DownloadManager", "fr": "Polymorphisme via DownloadManager"}, "validation_criteria": "Class `DownloadManager` holds `Downloadable[] downloadList = new Downloadable[100];`, provides `addDownload(Downloadable d)` and `showDownloads()` calling `printDownloadURL()`, and `main` adds `Document` and `Program` then displays.", "validation_criteria_i18n": {"en": "Class `DownloadManager` holds `Downloadable[] downloadList = new Downloadable[100];`, provides `addDownload(Downloadable d)` and `showDownloads()` calling `printDownloadURL()`, and `main` adds `Document` and `Program` then displays.", "fr": "La classe `DownloadManager` contient `Downloadable[] downloadList = new Downloadable[100];`, fournit `addDownload(Downloadable d)` et `showDownloads()` appelant `printDownloadURL()`, et le `main` ajoute des `Document` et `Program` puis affiche."}}], "title_i18n": {"en": "Activity No.1 (Independent): The Download Manager", "fr": "Activité N°1 (Indépendante) : Le gestionnaire de téléchargements"}, "target_files": ["Downloadable.java", "Document.java", "Program.java", "DownloadManager.java"], "instructions_i18n": {"en": "Scenario: reproduce the downloadable file manager seen in class to treat completely different objects the same way when they respect the same contract.\\n\\nImplementation Steps:\\n1. Create the `Downloadable` interface:\\n   - Declare constant `String baseURL = \\"http://monsite.tn/\\"` (implicitly `public static final`).\\n   - Declare abstract method signature `void printDownloadURL();`.\\n2. Create the implementations:\\n   - Create class `Document` (with `titre` and `fileName`) that specifies `implements Downloadable` and implements `printDownloadURL()` to display `baseURL + fileName`.\\n   - Create class `Program` (with `nomProgramme` and `programFileName`) that also implements `Downloadable` with its own version of `printDownloadURL()`.\\n3. Implement polymorphism with `DownloadManager`:\\n   - Create class `DownloadManager` with array `Downloadable[] downloadList = new Downloadable[100];`.\\n   - Add method `addDownload(Downloadable d)` to fill the array and method `showDownloads()` that iterates and calls `printDownloadURL()` on each element.\\n   - In `main`, instantiate the manager, add some `Document` and `Program` instances, then display.", "fr": "Objectif : manipuler les interfaces en reproduisant l'exemple du gestionnaire de fichiers téléchargeables vu en cours pour traiter des objets différents de la même manière via un même contrat.\\n\\nÉtapes de réalisation :\\n1. Créer l'interface `Downloadable` :\\n   - Ajouter l'attribut constant `String baseURL = \\"http://monsite.tn/\\"` (implicitement `public static final`).\\n   - Déclarer la signature de la méthode abstraite `void printDownloadURL();`.\\n2. Créer les implémentations :\\n   - Créer la classe `Document` (avec `titre` et `fileName`) qui spécifie `implements Downloadable` et implémente `printDownloadURL()` pour afficher `baseURL + fileName`.\\n   - Créer la classe `Program` (avec `nomProgramme` et `programFileName`) qui implémente également `Downloadable` avec sa propre version de `printDownloadURL()`.\\n3. Mettre en place le polymorphisme (`DownloadManager`) :\\n   - Créer la classe `DownloadManager` avec un tableau `Downloadable[] downloadList = new Downloadable[100];`.\\n   - Ajouter la méthode `addDownload(Downloadable d)` pour remplir le tableau et la méthode `showDownloads()` qui parcourt le tableau en appelant `printDownloadURL()` sur chaque élément.\\n   - Dans le `main`, instancier le manager, y ajouter quelques `Document` et `Program`, puis lancer l'affichage."}, "instructions_markdown": "Scenario: reproduce the downloadable file manager seen in class to treat completely different objects the same way when they respect the same contract.\\n\\nImplementation Steps:\\n1. Create the `Downloadable` interface:\\n   - Declare constant `String baseURL = \\"http://monsite.tn/\\"` (implicitly `public static final`).\\n   - Declare abstract method signature `void printDownloadURL();`.\\n2. Create the implementations:\\n   - Create class `Document` (with `titre` and `fileName`) that specifies `implements Downloadable` and implements `printDownloadURL()` to display `baseURL + fileName`.\\n   - Create class `Program` (with `nomProgramme` and `programFileName`) that also implements `Downloadable` with its own version of `printDownloadURL()`.\\n3. Implement polymorphism with `DownloadManager`:\\n   - Create class `DownloadManager` with array `Downloadable[] downloadList = new Downloadable[100];`.\\n   - Add method `addDownload(Downloadable d)` to fill the array and method `showDownloads()` that iterates and calls `printDownloadURL()` on each element.\\n   - In `main`, instantiate the manager, add some `Document` and `Program` instances, then display."}, {"id": "act_2", "order": 2, "title": "Activity No.2 (Red Thread Project): The Facturable Interface in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Facturable contract creation", "title_i18n": {"en": "Facturable contract creation", "fr": "Création du contrat Facturable"}, "validation_criteria": "Interface `Facturable` exists and declares abstract method `double getMontantTTC();` required for everything sold.", "validation_criteria_i18n": {"en": "Interface `Facturable` exists and declares abstract method `double getMontantTTC();` required for everything sold.", "fr": "L'interface `Facturable` existe et déclare la méthode abstraite `double getMontantTTC();` obligatoire pour tout ce qui est vendu."}}, {"id": "m2_2", "order": 2, "title": "Adapted Article and new Service type", "title_i18n": {"en": "Adapted Article and new Service type", "fr": "Article adapté et nouveau type Service"}, "validation_criteria": "`Article` is declared `abstract class Article implements Facturable` with `getMontantTTC()` (HT + TVA), and `Service` declares `implements Facturable` with `nomService`, `tarifHoraire`, `nombreHeures` and `getMontantTTC()` returning `tarifHoraire * nombreHeures`.", "validation_criteria_i18n": {"en": "`Article` is declared `abstract class Article implements Facturable` with `getMontantTTC()` (HT + TVA), and `Service` declares `implements Facturable` with `nomService`, `tarifHoraire`, `nombreHeures` and `getMontantTTC()` returning `tarifHoraire * nombreHeures`.", "fr": "`Article` est déclarée `abstract class Article implements Facturable` avec `getMontantTTC()` (HT + TVA), et `Service` déclare `implements Facturable` avec `nomService`, `tarifHoraire`, `nombreHeures` et `getMontantTTC()` retournant `tarifHoraire * nombreHeures`."}}, {"id": "m2_3", "order": 3, "title": "YallaPOS generalized to Facturable basket", "title_i18n": {"en": "YallaPOS generalized to Facturable basket", "fr": "Caisse YallaPOS généralisée au panier Facturable"}, "validation_criteria": "`YallaPOS` declares `Facturable[] panier = new Facturable[MAX];`, stores `ArticlePerissable`, `ArticleElectronique` and `Service` together, and computes total by looping with `panier[i].getMontantTTC()`.", "validation_criteria_i18n": {"en": "`YallaPOS` declares `Facturable[] panier = new Facturable[MAX];`, stores `ArticlePerissable`, `ArticleElectronique` and `Service` together, and computes total by looping with `panier[i].getMontantTTC()`.", "fr": "`YallaPOS` déclare `Facturable[] panier = new Facturable[MAX];`, stocke ensemble `ArticlePerissable`, `ArticleElectronique` et `Service`, et calcule le total en bouclant avec `panier[i].getMontantTTC()`."}}], "title_i18n": {"en": "Activity No.2 (Red Thread Project): The Facturable Interface in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : L'interface Facturable dans Yalla POS"}, "target_files": ["Facturable.java", "Article.java", "Service.java", "YallaPOS.java"], "instructions_i18n": {"en": "Scenario: evolve the Yalla POS cash register to cash both `Article` items and immaterial `Service` prestations through a common contract without inheritance.\\n\\nImplementation Steps:\\n1. Create the contract:\\n   - Create interface `Facturable` with abstract method `double getMontantTTC();`.\\n2. Adapt the existing hierarchy and create the new product type:\\n   - Modify abstract class `Article` to declare `abstract class Article implements Facturable` and implement `getMontantTTC()` (HT price + TVA).\\n   - Create new class `Service` that specifies `implements Facturable` (inherits from nothing) with attributes `nomService`, `tarifHoraire` and `nombreHeures`, and implements `getMontantTTC()` as `tarifHoraire * nombreHeures`.\\n3. Revolutionize the cash register (`YallaPOS`):\\n   - In `YallaPOS`, replace `Article[]` basket with interface array `Facturable[] panier = new Facturable[MAX];`.\\n   - Add instances of `ArticlePerissable`, `ArticleElectronique` AND `Service` to this basket.\\n   - Loop to compute the grand total by calling `panier[i].getMontantTTC()` on each element.", "fr": "Objectif : permettre à la même caisse Yalla POS d'encaisser à la fois des Articles et des Services immatériels grâce à l'interface Facturable sans héritage.\\n\\nÉtapes de réalisation :\\n1. Créer le contrat :\\n   - Créer une interface `Facturable` avec la méthode abstraite `double getMontantTTC();`.\\n2. Adapter l'existant et créer le nouveau type de produit :\\n   - Modifier la classe abstraite `Article` pour déclarer `abstract class Article implements Facturable` et développer `getMontantTTC()` à l'intérieur de `Article` (prix HT + TVA).\\n   - Créer la classe `Service` qui n'hérite de rien mais spécifie `implements Facturable`, avec les attributs `nomService`, `tarifHoraire` et `nombreHeures`, et implémenter `getMontantTTC()` (calcul `tarifHoraire * nombreHeures`).\\n3. Révolutionner la caisse (`YallaPOS`) :\\n   - Dans `YallaPOS`, changer le panier : au lieu d'un tableau `Article[]`, déclarer `Facturable[] panier = new Facturable[MAX];`.\\n   - Ajouter dans ce panier des instances de `ArticlePerissable`, de `ArticleElectronique` ET des instances de `Service`.\\n   - Faire une boucle pour calculer le Grand Total en appelant `panier[i].getMontantTTC()`."}, "instructions_markdown": "Scenario: evolve the Yalla POS cash register to cash both `Article` items and immaterial `Service` prestations through a common contract without inheritance.\\n\\nImplementation Steps:\\n1. Create the contract:\\n   - Create interface `Facturable` with abstract method `double getMontantTTC();`.\\n2. Adapt the existing hierarchy and create the new product type:\\n   - Modify abstract class `Article` to declare `abstract class Article implements Facturable` and implement `getMontantTTC()` (HT price + TVA).\\n   - Create new class `Service` that specifies `implements Facturable` (inherits from nothing) with attributes `nomService`, `tarifHoraire` and `nombreHeures`, and implements `getMontantTTC()` as `tarifHoraire * nombreHeures`.\\n3. Revolutionize the cash register (`YallaPOS`):\\n   - In `YallaPOS`, replace `Article[]` basket with interface array `Facturable[] panier = new Facturable[MAX];`.\\n   - Add instances of `ArticlePerissable`, `ArticleElectronique` AND `Service` to this basket.\\n   - Loop to compute the grand total by calling `panier[i].getMontantTTC()` on each element."}]	{INTERFACE_CONTRACT,INTERFACE_CONSTANTS_STATIC,INTERFACE_POLYMORPHISM}	[{"key": "act_1_buggy", "files": [{"name": "Downloadable.java", "content": "public interface Downloadable {\\n  String baseURL = \\"http://monsite.tn/\\";\\n  void printDownloadURL();\\n}"}, {"name": "Document.java", "content": "public class Document {\\n  private String titre;\\n  private String fileName;\\n  public Document(String titre, String fileName) {\\n    this.titre = titre;\\n    this.fileName = fileName;\\n  }\\n  public void printDownloadURL() {\\n    System.out.println(fileName);\\n  }\\n}"}, {"name": "Program.java", "content": "public class Program {\\n  private String nomProgramme;\\n  private String programFileName;\\n  public Program(String nomProgramme, String programFileName) {\\n    this.nomProgramme = nomProgramme;\\n    this.programFileName = programFileName;\\n  }\\n  public void printDownloadURL() {\\n    System.out.println(programFileName);\\n  }\\n}"}, {"name": "DownloadManager.java", "content": "public class DownloadManager {\\n  Document[] downloadList = new Document[100];\\n  int count = 0;\\n  public void addDownload(Document d) {\\n    downloadList[count++] = d;\\n  }\\n  public void showDownloads() {\\n    for (int i = 0; i < count; i++) {\\n      downloadList[i].printDownloadURL();\\n    }\\n  }\\n  public static void main(String[] args) {\\n    DownloadManager m = new DownloadManager();\\n    m.addDownload(new Document(\\"Cours\\", \\"cours.pdf\\"));\\n    // m.addDownload(new Program(\\"VLC\\", \\"vlc.exe\\")); // does not compile: Program is not Document\\n    m.showDownloads();\\n  }\\n}"}], "label": "1. Buggy Download Manager (No implements)", "activity_id": "act_1", "description": "Student forgets implements and uses concrete Document[] array, breaking polymorphism for Program.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Downloadable.java", "content": "public interface Downloadable {\\n  String baseURL = \\"http://monsite.tn/\\";\\n  void printDownloadURL();\\n}"}, {"name": "Document.java", "content": "public class Document implements Downloadable {\\n  private String titre;\\n  private String fileName;\\n  public Document(String titre, String fileName) {\\n    this.titre = titre;\\n    this.fileName = fileName;\\n  }\\n  @Override\\n  public void printDownloadURL() {\\n    System.out.println(baseURL + fileName);\\n  }\\n}"}, {"name": "Program.java", "content": "public class Program implements Downloadable {\\n  private String nomProgramme;\\n  private String programFileName;\\n  public Program(String nomProgramme, String programFileName) {\\n    this.nomProgramme = nomProgramme;\\n    this.programFileName = programFileName;\\n  }\\n  @Override\\n  public void printDownloadURL() {\\n    System.out.println(baseURL + programFileName);\\n  }\\n}"}, {"name": "DownloadManager.java", "content": "public class DownloadManager {\\n  Downloadable[] downloadList = new Downloadable[100];\\n  int count = 0;\\n  public void addDownload(Downloadable d) {\\n    if (count < downloadList.length) downloadList[count++] = d;\\n  }\\n  public void showDownloads() {\\n    for (int i = 0; i < count; i++) {\\n      downloadList[i].printDownloadURL();\\n    }\\n  }\\n  public static void main(String[] args) {\\n    DownloadManager m = new DownloadManager();\\n    m.addDownload(new Document(\\"Cours POO\\", \\"cours.pdf\\"));\\n    m.addDownload(new Program(\\"VLC\\", \\"vlc.exe\\"));\\n    m.showDownloads();\\n  }\\n}"}], "label": "2. Validated Solution (Downloadable Polymorphism)", "activity_id": "act_1", "description": "Clean reference with Downloadable contract, both implementations and polymorphic manager.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Facturable.java", "content": "public interface Facturable {\\n  double getMontantTTC();\\n}"}, {"name": "Article.java", "content": "public abstract class Article {\\n  protected String nom;\\n  protected double prixHT;\\n  protected double tva = 19.0;\\n  public Article(String nom, double prixHT) {\\n    this.nom = nom;\\n    this.prixHT = prixHT;\\n  }\\n  public double getMontantTTC() {\\n    return prixHT * (1 + tva / 100.0);\\n  }\\n}"}, {"name": "Service.java", "content": "public class Service extends Article {\\n  private String nomService;\\n  private double tarifHoraire;\\n  private int nombreHeures;\\n  public Service(String nomService, double tarifHoraire, int nombreHeures) {\\n    super(nomService, tarifHoraire * nombreHeures);\\n    this.nomService = nomService;\\n    this.tarifHoraire = tarifHoraire;\\n    this.nombreHeures = nombreHeures;\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  static final int MAX = 100;\\n  Article[] panier = new Article[MAX];\\n  int count = 0;\\n  public void ajouter(Article a) {\\n    if (count < MAX) panier[count++] = a;\\n  }\\n  public double total() {\\n    double s = 0;\\n    for (int i = 0; i < count; i++) s += panier[i].getMontantTTC();\\n    return s;\\n  }\\n  public static void main(String[] args) {\\n    YallaPOS c = new YallaPOS();\\n    c.ajouter(new Service(\\"Livraison\\", 10.0, 2));\\n    System.out.println(c.total());\\n  }\\n}"}], "label": "1. Buggy YallaPOS (Service extends Article)", "activity_id": "act_2", "description": "Student makes Service extend Article and keeps Article[] basket, so services cannot be decoupled.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Facturable.java", "content": "public interface Facturable {\\n  double getMontantTTC();\\n}"}, {"name": "Article.java", "content": "public abstract class Article implements Facturable {\\n  protected String nom;\\n  protected double prixHT;\\n  protected double tva = 19.0;\\n  public Article(String nom, double prixHT) {\\n    this.nom = nom;\\n    this.prixHT = prixHT;\\n  }\\n  @Override\\n  public double getMontantTTC() {\\n    return prixHT * (1 + tva / 100.0);\\n  }\\n}"}, {"name": "Service.java", "content": "public class Service implements Facturable {\\n  private String nomService;\\n  private double tarifHoraire;\\n  private int nombreHeures;\\n  public Service(String nomService, double tarifHoraire, int nombreHeures) {\\n    this.nomService = nomService;\\n    this.tarifHoraire = tarifHoraire;\\n    this.nombreHeures = nombreHeures;\\n  }\\n  @Override\\n  public double getMontantTTC() {\\n    return tarifHoraire * nombreHeures;\\n  }\\n}"}, {"name": "ArticlePerissable.java", "content": "public class ArticlePerissable extends Article {\\n  public ArticlePerissable(String nom, double prixHT) { super(nom, prixHT); }\\n}"}, {"name": "ArticleElectronique.java", "content": "public class ArticleElectronique extends Article {\\n  public ArticleElectronique(String nom, double prixHT) { super(nom, prixHT); }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  static final int MAX = 100;\\n  Facturable[] panier = new Facturable[MAX];\\n  int count = 0;\\n  public void ajouter(Facturable f) {\\n    if (count < MAX) panier[count++] = f;\\n  }\\n  public double total() {\\n    double s = 0;\\n    for (int i = 0; i < count; i++) s += panier[i].getMontantTTC();\\n    return s;\\n  }\\n  public static void main(String[] args) {\\n    YallaPOS c = new YallaPOS();\\n    c.ajouter(new ArticlePerissable(\\"Lait\\", 2.0));\\n    c.ajouter(new ArticleElectronique(\\"Casque\\", 100.0));\\n    c.ajouter(new Service(\\"Livraison\\", 10.0, 2));\\n    c.ajouter(new Service(\\"Installation\\", 25.0, 3));\\n    System.out.println(\\"Grand Total: \\" + c.total());\\n  }\\n}"}], "label": "2. Validated Solution (Facturable Basket)", "activity_id": "act_2", "description": "Decoupled reference: Article implements Facturable, Service implements Facturable, basket is Facturable[].", "preset_type": "solution"}]	t	2026-11-01 22:19:40.333+00	[{"page": 1, "text": "TP 9 : Définition et implémentation d'Interfaces\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Comprendre qu'une interface agit comme un contrat décrivant un ensemble de\\nméthodes abstraites.\\n Implémenter une ou plusieurs interfaces dans une classe grâce au mot-clé\\nimplements .\\n Utiliser une interface comme un nouveau type de référence pour généraliser le\\npolymorphisme.\\nActivité N°1 (Indépendante) : Le gestionnaire de téléchargements\\nDans cette activité, nous allons manipuler les interfaces en reproduisant l'exemple du\\ngestionnaire de fichiers téléchargeables vu en cours, pour comprendre comment des objets\\ncomplètement différents peuvent être traités de la même manière s'ils respectent le même\\ncontrat.\\n1. L'Interface :\\no Créez une interface nommée Downloadable .\\no Ajoutez-y un attribut constant String baseURL =\\n\\"[http://monsite.tn/](http://monsite.tn/)\\"; (Rappel : les attributs\\nd'une interface sont implicitement public static final ).\\no Déclarez la signature de la méthode abstraite void printDownloadURL(); .\\n2. Les Implémentations :\\no Créez une classe Document (avec un titre et un fileName ) qui spécifie\\nimplements Downloadable . Implémentez la méthode printDownloadURL()\\npour qu'elle affiche baseURL + fileName .\\no Créez une classe Program (avec un nomProgramme et un programFileName )\\nqui implémente également l'interface Downloadable et fournit sa propre\\nversion de printDownloadURL() .\\n3. Le Polymorphisme (DownloadManager) :\\no Créez une classe DownloadManager avec un tableau Downloadable[]\\ndownloadList = new Downloadable[100]; .\\no Ajoutez une méthode addDownload(Downloadable d) pour remplir le\\ntableau et une méthode showDownloads() qui parcourt le tableau en\\nappelant la méthode printDownloadURL() sur chaque élément.\\no Dans le main , instanciez le manager, ajoutez-y quelques Document et\\nProgram , puis lancez l'affichage.\\nActivité N°2 (Projet Fil Rouge) : L'interface Facturable dans Yalla POS\\nNotre système de caisse gérait parfaitement les \\"Articles\\" (frais ou électroniques) puisqu'ils\\navaient une classe mère commune. Mais Yalla POS souhaite désormais vendre des\\nprestations de \\"Services\\" immatériels (ex: Livraison, Installation). Un service n'est pas un\\narticle (pas de stock, pas de code-barres), il ne peut donc pas hériter de la classe Article ."}, {"page": 2, "text": "TP 9 : Définition et implémentation d'InterfacesMohamed Belhassen\\nComment faire pour qu'une même caisse puisse encaisser à la fois des Articles et des\\nServices ? La solution : l'interface Facturable !\\nTravail demandé :\\n1. Le Contrat :\\no Créez une interface Facturable .\\no Ajoutez la méthode abstraite double getMontantTTC(); . Tout ce qui sera\\nvendu dans notre magasin devra obligatoirement posséder cette méthode.\\n2. L'adaptation de l'existant :\\no Modifiez votre classe abstraite Article pour qu'elle déclare l'implémentation\\nde ce contrat : abstract class Article implements Facturable .\\no Développez le code de getMontantTTC() à l'intérieur de Article (rappel :\\ncalcul du prix HT + TVA).\\n3. Le nouveau type de produit (Service) :\\no Créez une toute nouvelle classe Service qui n'hérite de rien, mais qui spécifie\\nimplements Facturable .\\no Ajoutez des attributs pertinents : nomService , tarifHoraire , et\\nnombreHeures .\\no Implémentez la méthode obligatoire getMontantTTC() (ici, le calcul sera\\nsimplement tarifHoraire * nombreHeures ).\\n4. La révolution de la Caisse (YallaPOS) :\\no C'est ici que la magie opère. Dans YallaPOS , changez le type de votre tableau\\n(votre \\"panier\\"). Au lieu d'avoir un tableau de Article[] , déclarez un tableau\\nd'interfaces : Facturable[] panier = new Facturable[MAX]; .\\no Dans ce panier, ajoutez des instances de ArticlePerissable , de\\nArticleElectronique ET des instances de Service .\\no Faites une boucle pour calculer le Grand Total de la facture en appelant\\npanier[i].getMontantTTC() . Votre caisse accepte désormais n'importe\\nquel objet, du moment qu'il est \\"Facturable\\" !\\nBilan du TP 9 : Ce qu'il faut retenir\\nÀ la fin de ce TP, vous devez avoir validé les points suivants :\\n [ ] Interface vs Classe : Vous comprenez qu'une interface définit des interactions (un\\ncontrat de méthodes à implémenter) sans imposer de s'insérer dans une hiérarchie\\nd'héritage stricte.\\n [ ] Mot-clé implements : Vous savez déclarer qu'une classe s'engage à respecter un\\nou plusieurs contrats.\\n [ ] Nouveau Type : Vous avez utilisé une interface comme un type de donnée pour\\nvotre tableau, permettant une généralisation poussée du polymorphisme.\\n [ ] Yalla POS : Votre architecture est devenue extrêmement découplée et évolutive.\\nVous pouvez demain ajouter des \\"Abonnements\\" ou des \\"Cartes Cadeaux\\", il suffira\\nqu'ils implémentent Facturable pour être acceptés par la caisse.\\nLa suite : Jusqu'en Java 7, les interfaces ne contenaient que des signatures de méthodes\\nabstraites. Mais l'évolution du langage a introduit la possibilité d'ajouter des méthodes avec"}, {"page": 3, "text": "TP 9 : Définition et implémentation d'InterfacesMohamed Belhassen\\ndu vrai code directement dans une interface ! Lors du prochain TP, nous aborderons les\\nfonctionnalités avancées des interfaces : les méthodes default (pour faire évoluer une\\ninterface sans casser le code existant), les méthodes static , et un cas très particulier utilisé\\npar Java : les interfaces marqueurs (comme Cloneable ), qui n'ont aucune méthode mais\\nservent juste à \\"étiqueter\\" un objet."}]	{"en": "TP 9 — Lab 9: Definition and Implementation of Interfaces", "fr": "TP 9 : Définition et implémentation d'Interfaces"}	{"en": "This lab teaches interfaces as contracts decoupled from inheritance, first via a polymorphic download manager then by generalizing the Yalla POS basket to cash both articles and services.", "fr": "Ce TP initie aux interfaces comme contrats découplés de l'héritage, d'abord via un gestionnaire de téléchargements polymorphe puis en généralisant le panier Yalla POS pour encaisser articles et services."}	2026-11-02 20:07:42.438083+00
09600e76-13c5-4922-9ae6-6331690aaef6	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	7	TP7	TP 7 — Lab 7: Inheritance and the extends Keyword	This lab teaches single inheritance with extends, method overriding and super constructor/method reuse through a feline hierarchy and specialized Yalla POS articles.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp7.pdf	[{"id": "act_1", "order": 1, "title": "Activity No. 1 (Independent): The Feline Hierarchy", "milestones": [{"id": "m1_1", "order": 1, "title": "Superclass Felin with state and behavior", "title_i18n": {"en": "Superclass Felin with state and behavior", "fr": "Super-classe Felin avec état et comportement"}, "validation_criteria": "Class `Felin` declares `aFaim = true`, defines `parler()` and defines `appeler()` which prints \\"Le Felin est appelé\\" and calls `parler()` only if `aFaim` is true.", "validation_criteria_i18n": {"en": "Class `Felin` declares `aFaim = true`, defines `parler()` and defines `appeler()` which prints \\"Le Felin est appelé\\" and calls `parler()` only if `aFaim` is true.", "fr": "La classe `Felin` déclare `aFaim = true`, définit `parler()` et définit `appeler()` qui affiche \\"Le Felin est appelé\\" et appelle `parler()` uniquement si `aFaim` est vrai."}}, {"id": "m1_2", "order": 2, "title": "Subclasses Tigre and Chat with extends and overriding", "title_i18n": {"en": "Subclasses Tigre and Chat with extends and overriding", "fr": "Sous-classes Tigre et Chat avec extends et redéfinition"}, "validation_criteria": "`Tigre extends Felin` overrides `parler()` to \\"Groar!\\" and adds `chasser()`; `Chat extends Felin` adds `race` and overrides `parler()` to \\"Miaou!\\".", "validation_criteria_i18n": {"en": "`Tigre extends Felin` overrides `parler()` to \\"Groar!\\" and adds `chasser()`; `Chat extends Felin` adds `race` and overrides `parler()` to \\"Miaou!\\".", "fr": "`Tigre extends Felin` redéfinit `parler()` en \\"Groar!\\" et ajoute `chasser()` ; `Chat extends Felin` ajoute `race` et redéfinit `parler()` en \\"Miaou!\\"."}}, {"id": "m1_3", "order": 3, "title": "TestFelin test with specific and inherited methods", "title_i18n": {"en": "TestFelin test with specific and inherited methods", "fr": "Test avec TestFelin des méthodes spécifique et héritée"}, "validation_criteria": "`TestFelin` with `main` instantiates `Tigre` and successively calls `tigre.chasser()` and inherited `tigre.appeler()` without compilation error.", "validation_criteria_i18n": {"en": "`TestFelin` with `main` instantiates `Tigre` and successively calls `tigre.chasser()` and inherited `tigre.appeler()` without compilation error.", "fr": "`TestFelin` avec `main` instancie un `Tigre` et appelle successivement `tigre.chasser()` et `tigre.appeler()` héritée sans erreur de compilation."}}], "title_i18n": {"en": "Activity No. 1 (Independent): The Feline Hierarchy", "fr": "Activité N°1 (Indépendante) : La hiérarchie des Félins"}, "target_files": ["Felin.java", "Tigre.java", "Chat.java", "TestFelin.java"], "instructions_i18n": {"en": "Reproduce the animal hierarchy seen in class to assimilate basic inheritance.\\n\\n**Implementation Steps:**\\n1. Create the superclass `Felin`:\\n   * Declare the attribute `aFaim` initialized to `true`.\\n   * Add the method `parler()` with generic behavior.\\n   * Add the method `appeler()` which displays `\\"Le Felin est appelé\\"` and calls `parler()` only if `aFaim` is true (`if (aFaim)`).\\n2. Create the subclasses:\\n   * Create `Tigre extends Felin`, override `parler()` to display `\\"Groar!\\"` and add the specific method `chasser()` which displays `\\"Le tigre part en chasse\\"`.\\n   * Create `Chat extends Felin` with the specific attribute `race` and override `parler()` to display `\\"Miaou!\\"`.\\n3. Test in `TestFelin`:\\n   * In `main`, instantiate a `Tigre`, then call the specific method `tigre.chasser()` and the inherited method `tigre.appeler()`.", "fr": "Reproduire la hiérarchie animale vue en cours pour manipuler les concepts de base de l'héritage.\\n\\n**Étapes de réalisation :**\\n1. Créer la super-classe `Felin` :\\n   * Déclarer l'attribut `aFaim` initialisé à `true`.\\n   * Ajouter la méthode `parler()` avec un comportement générique.\\n   * Ajouter la méthode `appeler()` qui affiche `\\"Le Felin est appelé\\"` et qui appelle `parler()` si le félin a faim (`if (aFaim)`).\\n2. Créer les sous-classes :\\n   * Créer `Tigre extends Felin`, redéfinir `parler()` pour afficher `\\"Groar!\\"` et ajouter la méthode propre `chasser()` qui affiche `\\"Le tigre part en chasse\\"`.\\n   * Créer `Chat extends Felin` avec l'attribut spécifique `race` et redéfinir `parler()` pour afficher `\\"Miaou!\\"`.\\n3. Tester dans `TestFelin` :\\n   * Dans `main`, instancier un `Tigre`, puis appeler la méthode spécifique `tigre.chasser()` et la méthode héritée `tigre.appeler()`."}, "instructions_markdown": "Reproduce the animal hierarchy seen in class to assimilate basic inheritance.\\n\\n**Implementation Steps:**\\n1. Create the superclass `Felin`:\\n   * Declare the attribute `aFaim` initialized to `true`.\\n   * Add the method `parler()` with generic behavior.\\n   * Add the method `appeler()` which displays `\\"Le Felin est appelé\\"` and calls `parler()` only if `aFaim` is true (`if (aFaim)`).\\n2. Create the subclasses:\\n   * Create `Tigre extends Felin`, override `parler()` to display `\\"Groar!\\"` and add the specific method `chasser()` which displays `\\"Le tigre part en chasse\\"`.\\n   * Create `Chat extends Felin` with the specific attribute `race` and override `parler()` to display `\\"Miaou!\\"`.\\n3. Test in `TestFelin`:\\n   * In `main`, instantiate a `Tigre`, then call the specific method `tigre.chasser()` and the inherited method `tigre.appeler()`."}, {"id": "act_2", "order": 2, "title": "Activity No. 2 (Ongoing Project): Catalog Specialization in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Perishable article with super constructor and override", "title_i18n": {"en": "Perishable article with super constructor and override", "fr": "Article périssable avec constructeur super et redéfinition"}, "validation_criteria": "`ArticlePerissable extends Article` declares `private String dateExpiration`, its constructor calls `super(...)` first, exposes getter/setter, and `afficherDetails()` calls `super.afficherDetails()` plus expiration date.", "validation_criteria_i18n": {"en": "`ArticlePerissable extends Article` declares `private String dateExpiration`, its constructor calls `super(...)` first, exposes getter/setter, and `afficherDetails()` calls `super.afficherDetails()` plus expiration date.", "fr": "`ArticlePerissable extends Article` déclare `private String dateExpiration`, son constructeur appelle `super(...)` en premier, expose getter/setter, et `afficherDetails()` appelle `super.afficherDetails()` plus la date d'expiration."}}, {"id": "m2_2", "order": 2, "title": "Electronic article with warranty and override", "title_i18n": {"en": "Electronic article with warranty and override", "fr": "Article électronique avec garantie et redéfinition"}, "validation_criteria": "`ArticleElectronique extends Article` declares `private int dureeGarantieMois`, its constructor initializes inherited fields via `super(...)` and `afficherDetails()` includes the warranty.", "validation_criteria_i18n": {"en": "`ArticleElectronique extends Article` declares `private int dureeGarantieMois`, its constructor initializes inherited fields via `super(...)` and `afficherDetails()` includes the warranty.", "fr": "`ArticleElectronique extends Article` déclare `private int dureeGarantieMois`, son constructeur initialise les champs hérités via `super(...)` et `afficherDetails()` inclut la garantie."}}, {"id": "m2_3", "order": 3, "title": "YallaPOS checkout with polymorphic Article array", "title_i18n": {"en": "YallaPOS checkout with polymorphic Article array", "fr": "Caisse YallaPOS avec tableau polymorphique d'Article"}, "validation_criteria": "`YallaPOS` fills `Article[] panier` with `Article`, `ArticlePerissable`, `ArticleElectronique` at indices 0,1,2 and the unchanged loop `panier[i].afficherDetails()` dispatches to the correct override.", "validation_criteria_i18n": {"en": "`YallaPOS` fills `Article[] panier` with `Article`, `ArticlePerissable`, `ArticleElectronique` at indices 0,1,2 and the unchanged loop `panier[i].afficherDetails()` dispatches to the correct override.", "fr": "`YallaPOS` remplit `Article[] panier` avec `Article`, `ArticlePerissable`, `ArticleElectronique` aux indices 0,1,2 et la boucle inchangée `panier[i].afficherDetails()` appelle la bonne version redéfinie."}}], "title_i18n": {"en": "Activity No. 2 (Ongoing Project): Catalog Specialization in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : Spécialisation du catalogue dans Yalla POS"}, "target_files": ["Article.java", "ArticlePerissable.java", "ArticleElectronique.java", "YallaPOS.java"], "instructions_i18n": {"en": "Specialize the Yalla POS catalog with inheritance instead of polluting `Article` with attributes useless for all products.\\n\\n**Implementation Steps:**\\n1. Create the perishable article:\\n   * Create `ArticlePerissable` which inherits from `Article` (`extends Article`).\\n   * Add the specific attribute `dateExpiration` (`private String`).\\n   * Create the constructor initializing designation, price and barcode via `super(...)` as the first instruction, then generate getter/setter for `dateExpiration`.\\n   * Override `afficherDetails()` by calling `super.afficherDetails()` then displaying the expiration date.\\n2. Create the electronic article:\\n   * Create `ArticleElectronique extends Article` with `dureeGarantieMois` (`private int`), its constructor using `super(...)` for inherited attributes, and override `afficherDetails()` to include the warranty.\\n3. Update the checkout in `YallaPOS`:\\n   * In an `Article[]` array `panier`, insert at index 0 a standard `Article`, at index 1 an `ArticlePerissable`, at index 2 an `ArticleElectronique`.\\n   * Keep the ticket printing loop `panier[i].afficherDetails()` and observe polymorphic dispatch.", "fr": "Spécialiser le catalogue Yalla POS par héritage au lieu de polluer `Article` avec des attributs inutiles pour tous les produits.\\n\\n**Étapes de réalisation :**\\n1. Créer l'article périssable :\\n   * Créer `ArticlePerissable` qui hérite de `Article` (`extends Article`).\\n   * Ajouter l'attribut spécifique `dateExpiration` (`private String`).\\n   * Créer le constructeur qui initialise désignation, prix et code-barres en appelant `super(...)` en première instruction, puis générer getter/setter pour `dateExpiration`.\\n   * Redéfinir `afficherDetails()` en appelant `super.afficherDetails()` puis en affichant la date d'expiration.\\n2. Créer l'article électronique :\\n   * Créer `ArticleElectronique extends Article` avec `dureeGarantieMois` (`private int`), son constructeur utilisant `super(...)` pour les attributs hérités, et redéfinir `afficherDetails()` pour inclure la garantie.\\n3. Mettre à jour la caisse dans `YallaPOS` :\\n   * Dans un tableau `panier` de type `Article[]`, insérer à l'indice 0 un `Article` standard, à l'indice 1 un `ArticlePerissable`, et à l'indice 2 un `ArticleElectronique`.\\n   * Laisser la boucle d'impression `panier[i].afficherDetails()` et observer la distribution polymorphique."}, "instructions_markdown": "Specialize the Yalla POS catalog with inheritance instead of polluting `Article` with attributes useless for all products.\\n\\n**Implementation Steps:**\\n1. Create the perishable article:\\n   * Create `ArticlePerissable` which inherits from `Article` (`extends Article`).\\n   * Add the specific attribute `dateExpiration` (`private String`).\\n   * Create the constructor initializing designation, price and barcode via `super(...)` as the first instruction, then generate getter/setter for `dateExpiration`.\\n   * Override `afficherDetails()` by calling `super.afficherDetails()` then displaying the expiration date.\\n2. Create the electronic article:\\n   * Create `ArticleElectronique extends Article` with `dureeGarantieMois` (`private int`), its constructor using `super(...)` for inherited attributes, and override `afficherDetails()` to include the warranty.\\n3. Update the checkout in `YallaPOS`:\\n   * In an `Article[]` array `panier`, insert at index 0 a standard `Article`, at index 1 an `ArticlePerissable`, at index 2 an `ArticleElectronique`.\\n   * Keep the ticket printing loop `panier[i].afficherDetails()` and observe polymorphic dispatch."}]	{EXTENDS_SINGLE_INHERITANCE,SUPER_ACCESS_CHAINING,ABSTRACT_POLYMORPHISM}	[{"key": "act_1_buggy", "files": [{"name": "Felin.java", "content": "public class Felin {\\n  boolean aFaim = true;\\n  public void parler() {\\n    System.out.println(\\"Felin generique\\");\\n  }\\n  void appeler() {\\n    System.out.println(\\"Le Felin est appelé\\");\\n    parler();\\n  }\\n}"}, {"name": "Tigre.java", "content": "public class Tigre {\\n  public void parler() {\\n    System.out.println(\\"Groar!\\");\\n  }\\n  void chasser() {\\n    System.out.println(\\"Le tigre part en chasse\\");\\n  }\\n}"}, {"name": "Chat.java", "content": "public class Chat {\\n  String race;\\n  public void parler() {\\n    System.out.println(\\"Miaou!\\");\\n  }\\n}"}, {"name": "TestFelin.java", "content": "public class TestFelin {\\n  public static void main(String[] args) {\\n    Tigre tigre = new Tigre();\\n    tigre.chasser();\\n    tigre.parler();\\n  }\\n}"}], "label": "1. Buggy Felines (No extends)", "activity_id": "act_1", "description": "Tigre does not extend Felin and appeler ignores aFaim, so inheritance is broken.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Felin.java", "content": "public class Felin {\\n  boolean aFaim = true;\\n  public void parler() {\\n    System.out.println(\\"Felin generique\\");\\n  }\\n  void appeler() {\\n    System.out.println(\\"Le Felin est appelé\\");\\n    if (aFaim) {\\n      parler();\\n    }\\n  }\\n}"}, {"name": "Tigre.java", "content": "public class Tigre extends Felin {\\n  @Override\\n  public void parler() {\\n    System.out.println(\\"Groar!\\");\\n  }\\n  void chasser() {\\n    System.out.println(\\"Le tigre part en chasse\\");\\n  }\\n}"}, {"name": "Chat.java", "content": "public class Chat extends Felin {\\n  String race;\\n  @Override\\n  public void parler() {\\n    System.out.println(\\"Miaou!\\");\\n  }\\n}"}, {"name": "TestFelin.java", "content": "public class TestFelin {\\n  public static void main(String[] args) {\\n    Tigre tigre = new Tigre();\\n    tigre.chasser();\\n    tigre.appeler();\\n  }\\n}"}], "label": "2. Validated Solution (Feline Hierarchy)", "activity_id": "act_1", "description": "Correct Felin hierarchy with extends, overriding and inherited test.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Article.java", "content": "public class Article {\\n  private String designation;\\n  private double prix;\\n  private String codeBarres;\\n  public Article() {}\\n  public Article(String designation, double prix, String codeBarres) {\\n    this.designation = designation;\\n    this.prix = prix;\\n    this.codeBarres = codeBarres;\\n  }\\n  public void afficherDetails() {\\n    System.out.println(designation + \\" | \\" + prix + \\" | \\" + codeBarres);\\n  }\\n}"}, {"name": "ArticlePerissable.java", "content": "public class ArticlePerissable extends Article {\\n  private String dateExpiration;\\n  private String designation;\\n  private double prix;\\n  public ArticlePerissable(String designation, double prix, String codeBarres, String dateExpiration) {\\n    this.designation = designation;\\n    this.prix = prix;\\n    this.dateExpiration = dateExpiration;\\n  }\\n  public void afficherDetails() {\\n    System.out.println(dateExpiration);\\n  }\\n}"}, {"name": "ArticleElectronique.java", "content": "public class ArticleElectronique extends Article {\\n  private int dureeGarantieMois;\\n  public ArticleElectronique(String designation, double prix, String codeBarres, int dureeGarantieMois) {\\n    this.dureeGarantieMois = dureeGarantieMois;\\n  }\\n  public void afficherDetails() {\\n    System.out.println(\\"Garantie : \\" + dureeGarantieMois);\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    ArticlePerissable p = new ArticlePerissable(\\"Lait\\", 2.5, \\"111\\", \\"2026-12-01\\");\\n    ArticleElectronique e = new ArticleElectronique(\\"Four\\", 300.0, \\"222\\", 24);\\n    p.afficherDetails();\\n    e.afficherDetails();\\n  }\\n}"}], "label": "1. Buggy Catalog (No super reuse)", "activity_id": "act_2", "description": "Perishable article duplicates fields, misses super call and super.afficherDetails.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Article.java", "content": "public class Article {\\n  private String designation;\\n  private double prix;\\n  private String codeBarres;\\n  public Article(String designation, double prix, String codeBarres) {\\n    this.designation = designation;\\n    this.prix = prix;\\n    this.codeBarres = codeBarres;\\n  }\\n  public void afficherDetails() {\\n    System.out.println(designation + \\" | \\" + prix + \\" | \\" + codeBarres);\\n  }\\n}"}, {"name": "ArticlePerissable.java", "content": "public class ArticlePerissable extends Article {\\n  private String dateExpiration;\\n  public ArticlePerissable(String designation, double prix, String codeBarres, String dateExpiration) {\\n    super(designation, prix, codeBarres);\\n    this.dateExpiration = dateExpiration;\\n  }\\n  public String getDateExpiration() { return dateExpiration; }\\n  public void setDateExpiration(String dateExpiration) { this.dateExpiration = dateExpiration; }\\n  @Override\\n  public void afficherDetails() {\\n    super.afficherDetails();\\n    System.out.println(\\"Expiration : \\" + dateExpiration);\\n  }\\n}"}, {"name": "ArticleElectronique.java", "content": "public class ArticleElectronique extends Article {\\n  private int dureeGarantieMois;\\n  public ArticleElectronique(String designation, double prix, String codeBarres, int dureeGarantieMois) {\\n    super(designation, prix, codeBarres);\\n    this.dureeGarantieMois = dureeGarantieMois;\\n  }\\n  public int getDureeGarantieMois() { return dureeGarantieMois; }\\n  public void setDureeGarantieMois(int dureeGarantieMois) { this.dureeGarantieMois = dureeGarantieMois; }\\n  @Override\\n  public void afficherDetails() {\\n    super.afficherDetails();\\n    System.out.println(\\"Garantie : \\" + dureeGarantieMois + \\" mois\\");\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article[] panier = new Article[3];\\n    panier[0] = new Article(\\"Cafe\\", 4.5, \\"100\\");\\n    panier[1] = new ArticlePerissable(\\"Lait\\", 2.5, \\"111\\", \\"2026-12-01\\");\\n    panier[2] = new ArticleElectronique(\\"Four\\", 300.0, \\"222\\", 24);\\n    for (int i = 0; i < panier.length; i++) {\\n      panier[i].afficherDetails();\\n    }\\n  }\\n}"}], "label": "2. Validated Solution (Specialized Catalog)", "activity_id": "act_2", "description": "Clean specialization with super constructors and polymorphic Article array.", "preset_type": "solution"}]	t	2026-11-01 23:17:21.328+00	[{"page": 1, "text": "TP 7 : L'Héritage et le mot-clé extends\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Dériver une classe à partir d'une autre classe en utilisant le mot-clé extends .\\n Comprendre qu'une sous-classe hérite des caractéristiques de sa classe mère tout en\\npouvant se spécialiser avec d'autres fonctionnalités.\\n Redéfinir une ou plusieurs méthodes héritées dans la sous-classe.\\n Utiliser le mot-clé super pour faire appel au constructeur ou aux méthodes de la\\nclasse mère.\\nActivité N°1 (Indépendante) : La hiérarchie des Félins\\nDans cette activité, nous allons manipuler les concepts de base de l'héritage en reproduisant\\nla hiérarchie animale vue en cours.\\n1. La Super-classe :\\no Créez une classe Felin avec un attribut boolean aFaim = true; .\\no Ajoutez une méthode public void parler() (laissez son corps vide ou\\naffichez un message générique).\\no Ajoutez une méthode void appeler() qui affiche \\"Le Felin est appelé\\" et qui\\nappelle la méthode parler() si le félin a faim ( if (aFaim) ).\\n2. Les Sous-classes :\\no Créez une classe Tigre qui dérive de la classe mère en utilisant la syntaxe :\\nclass Tigre extends Felin .\\no Dans Tigre , redéfinissez la méthode parler() pour qu'elle affiche \\"Groar!\\".\\no Ajoutez une nouvelle méthode propre au tigre : void chasser() qui affiche\\n\\"Le tigre part en chasse\\".\\no Créez une autre classe Chat extends Felin avec un attribut spécifique\\nString race; et redéfinissez sa méthode parler() pour afficher \\"Miaou!\\".\\n3. Le Test :\\no Dans une classe TestFelin avec une méthode main , instanciez un Tigre .\\no Appelez tigre.chasser() (méthode spécifique) et tigre.appeler()\\n(méthode héritée de la classe mère).\\nActivité N°2 (Projet Fil Rouge) : Spécialisation du catalogue dans Yalla POS\\nNotre point de vente s'agrandit ! Nous vendons désormais des produits frais (qui possèdent\\nune date de péremption) et de l'électroménager (qui possède une durée de garantie). Au\\nlieu de polluer notre classe Article avec des attributs qui ne servent pas à tous les produits,\\nnous allons utiliser l'héritage pour créer des articles spécialisés.\\nTravail demandé :\\n1. L'Article Périssable :"}, {"page": 2, "text": "TP 7 : L'Héritage et le mot-clé extends Mohamed Belhassen\\no Créez une nouvelle classe ArticlePerissable qui hérite de Article\\n( extends Article ).\\no Ajoutez un attribut spécifique private String dateExpiration .\\no Créez le constructeur de ArticlePerissable . Attention : ce constructeur\\ndoit initialiser la désignation, le prix et le code-barres en appelant le\\nconstructeur de la classe mère à l'aide de l'instruction super(...) . (Rappel :\\nl'appel à super() doit obligatoirement être la première instruction du\\nconstructeur).\\no Générez le Getter et Setter pour dateExpiration .\\no Redéfinissez la méthode afficherDetails() . À l'intérieur, appelez\\nsuper.afficherDetails() pour afficher les infos de base, puis concaténez\\nl'affichage de la date d'expiration.\\n2. L'Article Électronique :\\no Créez une classe ArticleElectronique extends Article .\\no Ajoutez un attribut private int dureeGarantieMois .\\no Créez son constructeur (en utilisant super(...) pour les attributs hérités) et\\nredéfinissez sa méthode afficherDetails() pour inclure la garantie.\\n3. Mise à jour de la caisse :\\no Dans YallaPOS , remplacez la boucle de saisie par des instanciations \\"en dur\\"\\npour tester notre nouvelle architecture.\\no Dans votre tableau panier (qui est de type Article[] ), insérez à l'indice 0 un\\nArticle standard, à l'indice 1 un ArticlePerissable , et à l'indice 2 un\\nArticleElectronique .\\no Laissez votre boucle d'impression du ticket telle quelle\\n( panier[i].afficherDetails() ). Que remarquez-vous lors de l'exécution ?\\nBilan du TP 7 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Le mot-clé extends : Vous savez créer une hiérarchie de classes, sachant qu'en\\nJava, une classe ne peut hériter que d'une seule classe mère directe.\\n [ ] Le mot-clé super : Vous savez invoquer le constructeur de la super-classe et\\naccéder à ses méthodes non redéfinies.\\n [ ] Redéfinition : Vous savez écraser le comportement d'une méthode héritée pour\\nl'adapter à la sous-classe.\\n [ ] Yalla POS : Votre modèle de données est devenu très flexible sans dupliquer le\\ncode des attributs de base (nom, prix, code-barres).\\nLa suite : Lors du test de Yalla POS à l'étape 3, vous avez inséré des objets de type\\nArticlePerissable et ArticleElectronique dans un tableau prévu pour des Article .\\nMieux encore, la boucle a appelé la bonne version de afficherDetails() selon la nature\\nréelle du produit ! C'est ce qu'on appelle la magie du Polymorphisme . De plus, a-t-on\\nvraiment le droit de créer un \\"Article\\" générique ? Un article est forcément soit périssable,\\nsoit électronique, soit d'un autre type spécifique. Lors du prochain TP, nous approfondirons\\nle Polymorphisme , l'opérateur instanceof , et nous découvrirons les Classes Abstraites\\n( abstract ) pour interdire l'instanciation de concepts trop vagues !"}]	{"en": "TP 7 — Lab 7: Inheritance and the extends Keyword", "fr": "TP 7 : L'Héritage et le mot-clé extends"}	{"en": "This lab teaches single inheritance with extends, method overriding and super constructor/method reuse through a feline hierarchy and specialized Yalla POS articles.", "fr": "Ce TP enseigne l'héritage simple avec extends, la redéfinition de méthodes et la réutilisation via super à travers la hiérarchie des félins et la spécialisation des articles Yalla POS."}	2026-11-02 20:07:42.438083+00
244f23ea-1177-4bc1-9ce1-9d6cf5b678ec	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	11	TP11	TP 11 — Lab 11: Exception Handling and Defensive Programming	This lab teaches defensive programming in Java with try, catch and finally, Throwable inspection, then hardens the YallaPOS checkout against invalid keyboard input.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp11.pdf	[{"id": "act_1", "order": 1, "title": "Activity No.1 (Independent): Secure Calculator and Division by Zero", "milestones": [{"id": "m1_1", "order": 1, "title": "Reproducing the crash via division by zero", "title_i18n": {"en": "Reproducing the crash via division by zero", "fr": "Reproduction du plantage par division par zéro"}, "validation_criteria": "`CalculMath` defines `double division(int x, int y)` returning `x / y` and `TestCalcul` calls `division(2, 0)`, producing unhandled `java.lang.ArithmeticException: / by zero`.", "validation_criteria_i18n": {"en": "`CalculMath` defines `double division(int x, int y)` returning `x / y` and `TestCalcul` calls `division(2, 0)`, producing unhandled `java.lang.ArithmeticException: / by zero`.", "fr": "`CalculMath` définit `double division(int x, int y)` retournant `x / y` et `TestCalcul` appelle `division(2, 0)`, provoquant `java.lang.ArithmeticException: / by zero` non gérée."}}, {"id": "m1_2", "order": 2, "title": "Capture with try/catch and Throwable inspection", "title_i18n": {"en": "Capture with try/catch and Throwable inspection", "fr": "Capture avec try/catch et inspection Throwable"}, "validation_criteria": "Call is wrapped in `try`, caught with `catch (ArithmeticException e)`, displays friendly message, and calls `e.getMessage()` and `e.printStackTrace()` inside the catch.", "validation_criteria_i18n": {"en": "Call is wrapped in `try`, caught with `catch (ArithmeticException e)`, displays friendly message, and calls `e.getMessage()` and `e.printStackTrace()` inside the catch.", "fr": "L'appel est entouré d'un `try`, capturé avec `catch (ArithmeticException e)`, affiche le message convivial, et appelle `e.getMessage()` et `e.printStackTrace()` dans le catch."}}, {"id": "m1_3", "order": 3, "title": "Finally block always executed", "title_i18n": {"en": "Finally block always executed", "fr": "Bloc finally toujours exécuté"}, "validation_criteria": "`finally` block displays \\"Opération de calcul terminée.\\" and executes whether `division` threw or not, without blocking execution.", "validation_criteria_i18n": {"en": "`finally` block displays \\"Opération de calcul terminée.\\" and executes whether `division` threw or not, without blocking execution.", "fr": "Le bloc `finally` affiche \\"Opération de calcul terminée.\\" et s'exécute toujours, que `division` ait levé une exception ou non, sans bloquer l'exécution."}}], "title_i18n": {"en": "Activity No.1 (Independent): Secure Calculator and Division by Zero", "fr": "Activité N°1 (Indépendante) : Calculatrice sécurisée et Division par zéro"}, "target_files": ["CalculMath.java", "TestCalcul.java"], "instructions_i18n": {"en": "Scenario: visualize the JVM crash on division by zero, then fix it with defensive exception handling.\\n\\nImplementation Steps:\\n1. Reproduce the crash (unhandled exception):\\n   - Create the class `CalculMath` with the method `double division(int x, int y)` that simply returns `x / y`.\\n   - Create the class `TestCalcul` containing the `main`, instantiate `CalculMath` and call `division(2, 0)`.\\n   - Run and observe `java.lang.ArithmeticException: / by zero` and the brutal stop.\\n2. Capture with `try`/`catch`:\\n   - Wrap the call to `division` with a `try { ... }` block.\\n   - Add `catch (ArithmeticException e) { ... }` just below.\\n   - Display \\"Erreur : Division par zéro impossible !\\", then use `e.getMessage()` and `e.printStackTrace()` to inspect the error.\\n3. Add the `finally` block:\\n   - Add `finally { ... }` displaying \\"Opération de calcul terminée.\\" .\\n   - Verify that it always executes, whether the exception was thrown or not.", "fr": "Scénario : visualiser le plantage de la machine virtuelle lors d'une division par zéro puis le corriger par capture d'exception.\\n\\nÉtapes de réalisation :\\n1. Reproduire le plantage (exception non gérée) :\\n   - Créer la classe `CalculMath` contenant la méthode `double division(int x, int y)` qui retourne simplement `x / y`.\\n   - Créer la classe `TestCalcul` contenant le `main`, instancier `CalculMath` et appeler `division(2, 0)`.\\n   - Exécuter et observer `java.lang.ArithmeticException: / by zero` et l'arrêt brutal.\\n2. Capturer avec `try`/`catch` :\\n   - Entourer l'appel à `division` avec un bloc `try { ... }`.\\n   - Ajouter `catch (ArithmeticException e) { ... }` juste en dessous.\\n   - Afficher \\"Erreur : Division par zéro impossible !\\", puis utiliser `e.getMessage()` et `e.printStackTrace()` pour inspecter l'erreur.\\n3. Ajouter le bloc `finally` :\\n   - Ajouter `finally { ... }` affichant \\"Opération de calcul terminée.\\" .\\n   - Constater qu'il s'exécute toujours, que l'exception ait été levée ou non."}, "instructions_markdown": "Scenario: visualize the JVM crash on division by zero, then fix it with defensive exception handling.\\n\\nImplementation Steps:\\n1. Reproduce the crash (unhandled exception):\\n   - Create the class `CalculMath` with the method `double division(int x, int y)` that simply returns `x / y`.\\n   - Create the class `TestCalcul` containing the `main`, instantiate `CalculMath` and call `division(2, 0)`.\\n   - Run and observe `java.lang.ArithmeticException: / by zero` and the brutal stop.\\n2. Capture with `try`/`catch`:\\n   - Wrap the call to `division` with a `try { ... }` block.\\n   - Add `catch (ArithmeticException e) { ... }` just below.\\n   - Display \\"Erreur : Division par zéro impossible !\\", then use `e.getMessage()` and `e.printStackTrace()` to inspect the error.\\n3. Add the `finally` block:\\n   - Add `finally { ... }` displaying \\"Opération de calcul terminée.\\" .\\n   - Verify that it always executes, whether the exception was thrown or not."}, {"id": "act_2", "order": 2, "title": "Activity No.2 (Red Thread Project): Securing Keyboard Input in YallaPOS", "milestones": [{"id": "m2_1", "order": 1, "title": "Securing price reading with try/catch", "title_i18n": {"en": "Securing price reading with try/catch", "fr": "Sécurisation de la lecture du prix avec try/catch"}, "validation_criteria": "In `YallaPOS`, `clavier.nextDouble()` is wrapped in `try` and `InputMismatchException` (or `Exception`) is caught with `catch`.", "validation_criteria_i18n": {"en": "In `YallaPOS`, `clavier.nextDouble()` is wrapped in `try` and `InputMismatchException` (or `Exception`) is caught with `catch`.", "fr": "Dans `YallaPOS`, `clavier.nextDouble()` est entouré d'un `try` et `InputMismatchException` (ou `Exception`) est capturée avec `catch`."}}, {"id": "m2_2", "order": 2, "title": "Checkout error handling with buffer flush and continue", "title_i18n": {"en": "Checkout error handling with buffer flush and continue", "fr": "Traitement de l'erreur avec vidage tampon et continue"}, "validation_criteria": "Catch displays the alert, clears buffer with `clavier.nextLine()`, does not count the article, and uses `continue` to re-ask the same article.", "validation_criteria_i18n": {"en": "Catch displays the alert, clears buffer with `clavier.nextLine()`, does not count the article, and uses `continue` to re-ask the same article.", "fr": "Le catch affiche l'alerte, vide le tampon avec `clavier.nextLine()`, ne comptabilise pas l'article et utilise `continue` pour redemander le même article."}}, {"id": "m2_3", "order": 3, "title": "Robustness test without crash", "title_i18n": {"en": "Robustness test without crash", "fr": "Test de robustesse sans crash"}, "validation_criteria": "Entering letters instead of a price does not crash `YallaPOS`; it shows the alert and restarts the line input, ensuring service continuity.", "validation_criteria_i18n": {"en": "Entering letters instead of a price does not crash `YallaPOS`; it shows the alert and restarts the line input, ensuring service continuity.", "fr": "La saisie de lettres au lieu d'un prix ne fait pas crasher `YallaPOS` ; il affiche l'alerte et recommence la saisie de la ligne, assurant la continuité de service."}}], "title_i18n": {"en": "Activity No.2 (Red Thread Project): Securing Keyboard Input in YallaPOS", "fr": "Activité N°2 (Projet Fil Rouge) : Sécurisation des saisies au clavier dans Yalla POS"}, "target_files": ["YallaPOS.java"], "instructions_i18n": {"en": "Scenario: make the `YallaPOS` checkout bulletproof against invalid keystrokes when entering the price.\\n\\nImplementation Steps:\\n1. Secure price reading:\\n   - In `YallaPOS`, locate the loop asking the cashier for the article price.\\n   - Wrap the reading instruction `clavier.nextDouble()` with a `try` block.\\n   - Catch `InputMismatchException` (or more generally `Exception`) with a `catch` block.\\n2. Handle the checkout error:\\n   - Display `*** ERREUR SAISIE : Veuillez entrer un montant numérique valide ! ***`.\\n   - Clear the scanner buffer with `clavier.nextLine()` to avoid an infinite loop.\\n   - Do not count the defective article and use `continue` to force the loop to restart and ask again for the same article price.\\n3. Robustness test:\\n   - Launch `YallaPOS` and enter letters instead of a price.\\n   - Verify the system absorbs the shock, displays the alert, and offers to retry the line without shutting down.", "fr": "Scénario : rendre la caisse `YallaPOS` robuste face aux erreurs de frappe lors de la saisie du prix.\\n\\nÉtapes de réalisation :\\n1. Sécurisation de la lecture du prix :\\n   - Dans `YallaPOS`, localiser la boucle où vous demandez la saisie du prix d'un article.\\n   - Entourer l'instruction de lecture `clavier.nextDouble()` avec un bloc `try`.\\n   - Capturer `InputMismatchException` (ou plus généralement `Exception`) avec un bloc `catch`.\\n2. Traitement de l'erreur en caisse :\\n   - Afficher `*** ERREUR SAISIE : Veuillez entrer un montant numérique valide ! ***`.\\n   - Vider le tampon du scanner avec `clavier.nextLine()` pour éviter la boucle infinie.\\n   - Ne pas comptabiliser l'article défectueux et utiliser `continue` pour forcer la boucle à recommencer et redemander le prix du même article.\\n3. Test de robustesse :\\n   - Lancer `YallaPOS` et entrer des lettres au lieu d'un prix.\\n   - Vérifier que le système encaisse le choc, affiche l'alerte, et propose de recommencer la saisie sans s'éteindre."}, "instructions_markdown": "Scenario: make the `YallaPOS` checkout bulletproof against invalid keystrokes when entering the price.\\n\\nImplementation Steps:\\n1. Secure price reading:\\n   - In `YallaPOS`, locate the loop asking the cashier for the article price.\\n   - Wrap the reading instruction `clavier.nextDouble()` with a `try` block.\\n   - Catch `InputMismatchException` (or more generally `Exception`) with a `catch` block.\\n2. Handle the checkout error:\\n   - Display `*** ERREUR SAISIE : Veuillez entrer un montant numérique valide ! ***`.\\n   - Clear the scanner buffer with `clavier.nextLine()` to avoid an infinite loop.\\n   - Do not count the defective article and use `continue` to force the loop to restart and ask again for the same article price.\\n3. Robustness test:\\n   - Launch `YallaPOS` and enter letters instead of a price.\\n   - Verify the system absorbs the shock, displays the alert, and offers to retry the line without shutting down."}]	{TRY_CATCH_FINALLY_ORDER,THROWABLE_HIERARCHY,CONTROL_FLOW_BREAK}	[{"key": "act_1_buggy", "files": [{"name": "CalculMath.java", "content": "public class CalculMath {\\n  public double division(int x, int y) {\\n    return x / y;\\n  }\\n}"}, {"name": "TestCalcul.java", "content": "public class TestCalcul {\\n  public static void main(String[] args) {\\n    CalculMath calc = new CalculMath();\\n    System.out.println(calc.division(2, 0));\\n    System.out.println(\\"Opération de calcul terminée.\\");\\n  }\\n}"}], "label": "1. Buggy Calculator (Unhandled Division)", "activity_id": "act_1", "description": "Calls division(2,0) with no try/catch, JVM crashes with ArithmeticException.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "CalculMath.java", "content": "public class CalculMath {\\n  public double division(int x, int y) {\\n    return x / y;\\n  }\\n}"}, {"name": "TestCalcul.java", "content": "public class TestCalcul {\\n  public static void main(String[] args) {\\n    CalculMath calc = new CalculMath();\\n    try {\\n      System.out.println(calc.division(2, 0));\\n    } catch (ArithmeticException e) {\\n      System.out.println(\\"Erreur : Division par zéro impossible !\\");\\n      System.out.println(e.getMessage());\\n      e.printStackTrace();\\n    } finally {\\n      System.out.println(\\"Opération de calcul terminée.\\");\\n    }\\n  }\\n}"}], "label": "2. Validated Solution (Secure Calculator)", "activity_id": "act_1", "description": "Secure division with try/catch ArithmeticException, getMessage, printStackTrace and finally.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void main(String[] args) {\\n    Scanner clavier = new Scanner(System.in);\\n    double total = 0;\\n    for (int i = 1; i <= 3; i++) {\\n      System.out.print(\\"Prix article \\" + i + \\" : \\");\\n      try {\\n        double prix = clavier.nextDouble();\\n        total += prix;\\n      } catch (Exception e) {\\n        System.out.println(\\"*** ERREUR SAISIE : Veuillez entrer un montant numérique valide ! ***\\");\\n      }\\n    }\\n    System.out.println(\\"Total : \\" + total);\\n  }\\n}"}], "label": "1. Buggy YallaPOS (Missing Buffer Flush)", "activity_id": "act_2", "description": "Catches input error but forgets nextLine flush, causing infinite loop.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "YallaPOS.java", "content": "import java.util.Scanner;\\nimport java.util.InputMismatchException;\\npublic class YallaPOS {\\n  public static void main(String[] args) {\\n    Scanner clavier = new Scanner(System.in);\\n    double total = 0;\\n    for (int i = 1; i <= 3; i++) {\\n      System.out.print(\\"Prix article \\" + i + \\" : \\");\\n      try {\\n        double prix = clavier.nextDouble();\\n        total += prix;\\n      } catch (InputMismatchException e) {\\n        System.out.println(\\"*** ERREUR SAISIE : Veuillez entrer un montant numérique valide ! ***\\");\\n        clavier.nextLine();\\n        i--;\\n        continue;\\n      }\\n    }\\n    System.out.println(\\"Total : \\" + total);\\n    clavier.close();\\n  }\\n}"}], "label": "2. Validated Solution (Bulletproof YallaPOS)", "activity_id": "act_2", "description": "Defensive YallaPOS with InputMismatchException catch, nextLine flush and continue retry.", "preset_type": "solution"}]	t	2026-11-01 22:20:22.976+00	[{"page": 1, "text": "TP 11 : Gestion des Exceptions et Programmation Défensive\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Appliquer les principes de la programmation défensive pour améliorer la robustesse\\ndu logiciel face aux incidents prévus ou imprévus.\\n Utiliser les blocs try , catch et finally pour détecter et traiter les exceptions sans\\nbloquer l'exécution.\\n Exploiter les méthodes de la classe Throwable telles que getMessage() et\\nprintStackTrace() pour analyser l'erreur.\\n Comprendre la hiérarchie des erreurs en Java ( Error , Exception ,\\nRuntimeException ).\\nActivité N°1 (Indépendante) : Calculatrice sécurisée et Division par zéro\\nDans cette activité, nous allons reproduire le problème classique de la division par zéro\\nabordé en cours pour visualiser le plantage de l'application, puis le corriger avec un\\nmécanisme de gestion des exceptions.\\n1. Le plantage (L'exception non gérée) :\\no Créez une classe CalculMath contenant une méthode double division(int\\nx, int y) qui retourne simplement x / y .\\no Dans une classe TestCalcul (contenant le main ), instanciez CalculMath et\\nappelez la méthode division(2, 0) .\\no Exécutez le programme. Observez l'arrêt brutal de la machine virtuelle et le\\nmessage en rouge dans la console : java.lang.ArithmeticException: /\\nby zero .\\n2. La capture (Le bloc try/catch) :\\no Entourez l'appel de votre méthode division avec un bloc try { ... } .\\no Ajoutez un bloc catch (ArithmeticException e) { ... } juste en\\ndessous.\\no À l'intérieur du catch , affichez un message convivial (\\"Erreur : Division par\\nzéro impossible !\\"), puis utilisez e.getMessage() et e.printStackTrace()\\npour inspecter la trace technique de l'erreur.\\n3. Le bloc finally :\\no Ajoutez un bloc finally { ... } après le catch .\\no Faites-lui afficher \\"Opération de calcul terminée.\\" . Constatez que ce\\nbloc s'exécute toujours, que l'exception ait été levée ou non.\\nActivité N°2 (Projet Fil Rouge) : Sécurisation des saisies au clavier dans Yalla POS\\nNotre caisse enregistreuse est fonctionnelle, mais elle est extrêmement fragile face aux\\nerreurs de frappe ! Si le système demande le prix d'un article (un double ) et que le caissier\\ntape \\"abc\\" par inadvertance, la classe Scanner va lever une exception\\n( InputMismatchException ) et l'application entière va crasher, faisant perdre le ticket de"}, {"page": 2, "text": "TP 11 : Gestion des Exceptions et Programmation Défensive Mohamed Belhassen\\ncaisse en cours au client. Nous allons mettre en place une véritable programmation\\ndéfensive.\\nTravail demandé :\\n1. Sécurisation de la lecture du prix :\\no Ouvrez la classe YallaPOS et localisez la boucle où vous demandez au caissier\\nde saisir le prix d'un article.\\no Entourez l'instruction de lecture ( clavier.nextDouble() ) avec un bloc try .\\no Capturez l'exception InputMismatchException (ou plus généralement\\nException pour attraper toute erreur de format) avec un bloc catch .\\n2. Traitement de l'erreur en caisse :\\no Dans le catch , affichez un message d'alerte en console : *** ERREUR SAISIE\\n: Veuillez entrer un montant numérique valide ! *** .\\no Attention : N'oubliez pas de \\"vider\\" le tampon du scanner dans le catch (en\\nfaisant un clavier.nextLine() ), sinon votre programme partira dans une\\nboucle infinie !\\no Ne comptabilisez pas cet article défectueux et utilisez l'instruction continue\\npour forcer la boucle à recommencer et demander à nouveau le prix du\\nmême article.\\n3. Test de robustesse :\\no Lancez Yalla POS. Essayez d'entrer des lettres au lieu d'un prix.\\no Votre système doit encaisser le choc, afficher l'alerte, et proposer de\\nrecommencer la saisie de la ligne sans s'éteindre !\\nBilan du TP 11 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Mécanisme de protection : Vous comprenez comment l'exécution normale\\ns'arrête dans le try pour sauter immédiatement dans le bloc catch adéquat dès\\nqu'une erreur survient.\\n [ ] Continuité de service : Votre logiciel ne \\"crashe\\" plus brutalement. Il intercepte\\nl'erreur, la traite, et continue son exécution.\\n [ ] Trace de l'erreur : Vous savez extraire les détails d'une exception capturée grâce à\\nprintStackTrace() .\\n [ ] Yalla POS : Votre terminal d'encaissement est désormais \\"bulletproof\\" (robuste)\\nface aux fausses manœuvres de l'utilisateur.\\nLa suite : Intercepter les erreurs standard de Java (comme les divisions par zéro ou les\\nmauvaises saisies) est essentiel. Mais qu'en est-il des erreurs métier ? Par exemple, si un\\ncaissier tente de vendre un article dont le stock est épuisé, ou si le total d'un paiement par\\ncarte bancaire est insuffisant. Java ne possède aucune classe StockEpuiseException\\nintégrée ! Lors de notre dernier TP, nous apprendrons à Créer nos propres Exceptions\\nPersonnalisées et à utiliser le mot-clé throw pour déclencher nous-mêmes ces alertes afin\\nde finaliser Yalla POS avec des règles métier strictes."}]	{"en": "TP 11 — Lab 11: Exception Handling and Defensive Programming", "fr": "TP 11 : Gestion des Exceptions et Programmation Défensive"}	{"en": "This lab teaches defensive programming in Java with try, catch and finally, Throwable inspection, then hardens the YallaPOS checkout against invalid keyboard input.", "fr": "Ce TP enseigne la programmation défensive en Java avec try, catch et finally et l'inspection Throwable, puis sécurise la caisse YallaPOS contre les saisies clavier invalides."}	2026-11-02 20:07:42.438083+00
88c1ca7d-b1dc-4006-aff7-9e6928a5be41	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	10	TP10	TP 10 — Lab 10: Advanced Interfaces (Default, Static and Marker Methods)	This lab teaches evolving interfaces without breaking implementations via default and static methods and using the Cloneable marker, applied to a banking system then to Yalla POS for loyalty discounts and service duplication.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp10.pdf	[{"id": "act_1", "order": 1, "title": "Activity No.1 (Independent): Bank Management and Deep Cloning", "milestones": [{"id": "m1_1", "order": 1, "title": "Default transferer implementation in Compte", "title_i18n": {"en": "Default transferer implementation in Compte", "fr": "Implémentation par défaut transferer dans Compte"}, "validation_criteria": "Compte declares default void transferer using this.retirer(montant) and destination.deposer(montant) and CompteBancaire compiles without rewriting transfer code.", "validation_criteria_i18n": {"en": "Compte declares default void transferer using this.retirer(montant) and destination.deposer(montant) and CompteBancaire compiles without rewriting transfer code.", "fr": "Compte déclare default void transferer(Compte destination) utilisant this.retirer(montant) et destination.deposer(montant) et CompteBancaire compile sans réécrire le transfert."}}, {"id": "m1_2", "order": 2, "title": "Static utility getBalanceTotale", "title_i18n": {"en": "Static utility getBalanceTotale", "fr": "Utilitaire statique getBalanceTotale"}, "validation_criteria": "Compte declares static int getBalanceTotale(Compte... comptes) that loops over comptes and returns the sum of getBalance().", "validation_criteria_i18n": {"en": "Compte declares static int getBalanceTotale(Compte... comptes) that loops over comptes and returns the sum of getBalance().", "fr": "Compte déclare static int getBalanceTotale(Compte... comptes) qui parcourt les comptes et retourne la somme des getBalance()."}}, {"id": "m1_3", "order": 3, "title": "Marker Cloneable and clone() in TestClone", "title_i18n": {"en": "Marker Cloneable and clone() in TestClone", "fr": "Marqueur Cloneable et clone() dans TestClone"}, "validation_criteria": "TestClone declares implements Cloneable and overrides clone() inherited from Object without throwing CloneNotSupportedException.", "validation_criteria_i18n": {"en": "TestClone declares implements Cloneable and overrides clone() inherited from Object without throwing CloneNotSupportedException.", "fr": "TestClone déclare implements Cloneable et redéfinit clone() héritée de Object sans provoquer CloneNotSupportedException."}}], "title_i18n": {"en": "Activity No.1 (Independent): Bank Management and Deep Cloning", "fr": "Activité N°1 (Indépendante) : Gestion bancaire et Clonage profond"}, "target_files": ["Compte.java", "CompteBancaire.java", "TestClone.java"], "instructions_i18n": {"en": "Scenario: Simulate a bank account system to explore modern interface features since Java 8 and object cloning.\\n\\nImplementation Steps:\\n1. Default implementation (`default`):\\n   - Create the `Compte` interface with `deposer(int montant)`, `retirer(int montant)` and `getBalance()`.\\n   - Create the `CompteBancaire` class that implements `Compte` in the classic way.\\n   - Add `default void transferer(Compte destination)` in `Compte` using `this.retirer(montant)` and `destination.deposer(montant)`; observe that `CompteBancaire` automatically inherits this behavior.\\n2. Static method (`static`):\\n   - Add `static int getBalanceTotale(Compte... comptes)` in `Compte` that iterates over the given accounts to return the sum of balances.\\n3. Marker interface (`Cloneable`):\\n   - Create the `TestClone` class with simple attributes.\\n   - Declare `implements Cloneable` (a marker interface with no methods).\\n   - Override `clone()` inherited from `Object`; without the marker Java throws `CloneNotSupportedException` at runtime.", "fr": "Objectif : Simuler un système de comptes bancaires pour explorer les fonctionnalités modernes des interfaces depuis Java 8 puis étudier le clonage d'objets.\\n\\nÉtapes de réalisation :\\n1. L'implémentation par défaut (`default`) :\\n   - Créer l'interface `Compte` contenant `deposer(int montant)`, `retirer(int montant)` et `getBalance()`.\\n   - Créer la classe `CompteBancaire` qui implémente `Compte` de manière classique.\\n   - Ajouter `default void transferer(Compte destination)` dans `Compte` en utilisant `this.retirer(montant)` et `destination.deposer(montant)`; constater que `CompteBancaire` hérite automatiquement de ce comportement.\\n2. La méthode statique (`static`) :\\n   - Ajouter `static int getBalanceTotale(Compte... comptes)` dans `Compte` qui parcourt les comptes passés en paramètre pour retourner la somme de leurs soldes.\\n3. L'interface marqueur (`Cloneable`) :\\n   - Créer la classe `TestClone` avec des attributs simples.\\n   - Déclarer `implements Cloneable` (une interface marqueur qui ne contient aucune méthode).\\n   - Redéfinir la méthode `clone()` héritée de `Object`; sans le marqueur Java lèvera `CloneNotSupportedException` à l'exécution."}, "instructions_markdown": "Scenario: Simulate a bank account system to explore modern interface features since Java 8 and object cloning.\\n\\nImplementation Steps:\\n1. Default implementation (`default`):\\n   - Create the `Compte` interface with `deposer(int montant)`, `retirer(int montant)` and `getBalance()`.\\n   - Create the `CompteBancaire` class that implements `Compte` in the classic way.\\n   - Add `default void transferer(Compte destination)` in `Compte` using `this.retirer(montant)` and `destination.deposer(montant)`; observe that `CompteBancaire` automatically inherits this behavior.\\n2. Static method (`static`):\\n   - Add `static int getBalanceTotale(Compte... comptes)` in `Compte` that iterates over the given accounts to return the sum of balances.\\n3. Marker interface (`Cloneable`):\\n   - Create the `TestClone` class with simple attributes.\\n   - Declare `implements Cloneable` (a marker interface with no methods).\\n   - Override `clone()` inherited from `Object`; without the marker Java throws `CloneNotSupportedException` at runtime."}, {"id": "act_2", "order": 2, "title": "Activity No.2 (Red Thread Project): Evolving Contracts and Duplication in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Evolving contract Remisable with loyalty default", "title_i18n": {"en": "Evolving contract Remisable with loyalty default", "fr": "Contrat évolutif Remisable avec défaut fidélité"}, "validation_criteria": "Remisable declares abstract appliquerRemise(double pourcentage) and default appliquerRemiseFidelite() calling appliquerRemise(5); ArticleElectronique implements Remisable and modifies HT price.", "validation_criteria_i18n": {"en": "Remisable declares abstract appliquerRemise(double pourcentage) and default appliquerRemiseFidelite() calling appliquerRemise(5); ArticleElectronique implements Remisable and modifies HT price.", "fr": "Remisable déclare appliquerRemise(double pourcentage) abstraite et default appliquerRemiseFidelite() appelant appliquerRemise(5); ArticleElectronique implémente Remisable et modifie le prix HT."}}, {"id": "m2_2", "order": 2, "title": "Static header utility in Facturable", "title_i18n": {"en": "Static header utility in Facturable", "fr": "Utilitaire statique d'en-tête dans Facturable"}, "validation_criteria": "Facturable declares static void imprimerEnTeteEnseigne() printing ================= YALLA POS ================ and YallaPOS calls Facturable.imprimerEnTeteEnseigne() before ticket printing.", "validation_criteria_i18n": {"en": "Facturable declares static void imprimerEnTeteEnseigne() printing ================= YALLA POS ================ and YallaPOS calls Facturable.imprimerEnTeteEnseigne() before ticket printing.", "fr": "Facturable déclare static void imprimerEnTeteEnseigne() affichant ================ YALLA POS ================ et YallaPOS appelle Facturable.imprimerEnTeteEnseigne() au début de l'impression."}}, {"id": "m2_3", "order": 3, "title": "Service duplication via Cloneable", "title_i18n": {"en": "Service duplication via Cloneable", "fr": "Duplication de Service via Cloneable"}, "validation_criteria": "Service declares implements Facturable, Cloneable and overrides clone(); YallaPOS clones Installation Réseau service inside try/catch and adds both services to the cart.", "validation_criteria_i18n": {"en": "Service declares implements Facturable, Cloneable and overrides clone(); YallaPOS clones Installation Réseau service inside try/catch and adds both services to the cart.", "fr": "Service déclare implements Facturable, Cloneable et surcharge clone(); YallaPOS clone le Service Installation Réseau dans un try/catch et ajoute les deux au panier."}}], "title_i18n": {"en": "Activity No.2 (Red Thread Project): Evolving Contracts and Duplication in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : Évolution des contrats et duplication dans Yalla POS"}, "target_files": ["Remisable.java", "Facturable.java", "ArticleElectronique.java", "Service.java", "YallaPOS.java"], "instructions_i18n": {"en": "Scenario: Evolve Yalla POS contracts to add a global loyalty discount and allow the cashier to duplicate a ticket line via cloning.\\n\\nImplementation Steps:\\n1. Evolving contract (`Remisable`):\\n   - Create the `Remisable` interface with abstract `appliquerRemise(double pourcentage)`.\\n   - Add `default void appliquerRemiseFidelite()` that simply calls `appliquerRemise(5)` for 5% loyalty discount.\\n   - Make `ArticleElectronique` implement `Remisable` and define `appliquerRemise` behavior (modify HT price).\\n2. Static utility in `Facturable`:\\n   - Open the `Facturable` interface and add `static void imprimerEnTeteEnseigne()` that displays `\\"================ YALLA POS ================\\"`.\\n   - In `YallaPOS`, call `Facturable.imprimerEnTeteEnseigne()` at the very start of ticket printing.\\n3. Duplication of `Service` (`Cloneable`):\\n   - Open the `Service` class (already implementing `Facturable`) and add the marker: `implements Facturable, Cloneable`.\\n   - Override the `clone()` method to allow copying the service.\\n   - In `YallaPOS`, instantiate a `Service` (e.g. \\"Installation Réseau\\" at 50 TND/h), use `clone()` to create an identical second service and add both to the cart (temporarily handle the exception with an IDE-generated `try/catch`).", "fr": "Objectif : Faire évoluer les contrats Yalla POS pour ajouter une remise fidélité globale et permettre de dupliquer une ligne du ticket par clonage.\\n\\nÉtapes de réalisation :\\n1. Le contrat évolutif (`Remisable`) :\\n   - Créer la nouvelle interface `Remisable` avec `appliquerRemise(double pourcentage)` abstraite.\\n   - Ajouter `default void appliquerRemiseFidelite()` qui appelle simplement `appliquerRemise(5)` pour 5% de remise fidèle.\\n   - Faire en sorte que `ArticleElectronique` implémente `Remisable` et définisse `appliquerRemise` (modifier le prix HT).\\n2. L'utilitaire statique dans `Facturable` :\\n   - Ouvrir l'interface `Facturable` et ajouter `static void imprimerEnTeteEnseigne()` qui affiche : `\\"================ YALLA POS ================\\"`.\\n   - Dans `YallaPOS`, appeler `Facturable.imprimerEnTeteEnseigne()` tout au début de l'impression du ticket.\\n3. Duplication de `Service` (`Cloneable`) :\\n   - Ouvrir la classe `Service` (qui implémente déjà `Facturable`) et ajouter le marqueur : `implements Facturable, Cloneable`.\\n   - Surcharger la méthode `clone()` pour permettre la copie du service.\\n   - Dans `YallaPOS`, instancier un `Service` (ex: \\"Installation Réseau\\" à 50 TND/h), utiliser `clone()` pour créer un deuxième service identique et ajouter les deux au panier (gérer temporairement l'exception avec un bloc `try/catch` autogénéré)."}, "instructions_markdown": "Scenario: Evolve Yalla POS contracts to add a global loyalty discount and allow the cashier to duplicate a ticket line via cloning.\\n\\nImplementation Steps:\\n1. Evolving contract (`Remisable`):\\n   - Create the `Remisable` interface with abstract `appliquerRemise(double pourcentage)`.\\n   - Add `default void appliquerRemiseFidelite()` that simply calls `appliquerRemise(5)` for 5% loyalty discount.\\n   - Make `ArticleElectronique` implement `Remisable` and define `appliquerRemise` behavior (modify HT price).\\n2. Static utility in `Facturable`:\\n   - Open the `Facturable` interface and add `static void imprimerEnTeteEnseigne()` that displays `\\"================ YALLA POS ================\\"`.\\n   - In `YallaPOS`, call `Facturable.imprimerEnTeteEnseigne()` at the very start of ticket printing.\\n3. Duplication of `Service` (`Cloneable`):\\n   - Open the `Service` class (already implementing `Facturable`) and add the marker: `implements Facturable, Cloneable`.\\n   - Override the `clone()` method to allow copying the service.\\n   - In `YallaPOS`, instantiate a `Service` (e.g. \\"Installation Réseau\\" at 50 TND/h), use `clone()` to create an identical second service and add both to the cart (temporarily handle the exception with an IDE-generated `try/catch`)."}]	{INTERFACE_CONTRACT,INTERFACE_CONSTANTS_STATIC,MARKER_DEFAULT_EVOLUTION,TRY_CATCH_FINALLY_ORDER}	[{"key": "act_1_buggy", "files": [{"name": "Compte.java", "content": "public interface Compte {\\n  void deposer(int montant);\\n  int retirer(int montant);\\n  int getBalance();\\n  void transferer(Compte destination);\\n}"}, {"name": "CompteBancaire.java", "content": "public class CompteBancaire implements Compte {\\n  private int balance;\\n  public void deposer(int montant) { balance += montant; }\\n  public int retirer(int montant) { balance -= montant; return montant; }\\n  public int getBalance() { return balance; }\\n  public void transferer(Compte destination) {\\n    destination.deposer(100);\\n  }\\n}"}, {"name": "TestClone.java", "content": "public class TestClone {\\n  int value = 10;\\n  public Object clone() throws CloneNotSupportedException {\\n    return super.clone();\\n  }\\n}"}], "label": "1. Buggy Bank (Abstract Transfer + No Marker)", "activity_id": "act_1", "description": "Transfer declared abstract breaking existing impl, no static total, clone without marker.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Compte.java", "content": "public interface Compte {\\n  void deposer(int montant);\\n  int retirer(int montant);\\n  int getBalance();\\n  default void transferer(int montant, Compte destination) {\\n    int somme = this.retirer(montant);\\n    destination.deposer(somme);\\n  }\\n  static int getBalanceTotale(Compte... comptes) {\\n    int total = 0;\\n    for (Compte c : comptes) { total += c.getBalance(); }\\n    return total;\\n  }\\n}"}, {"name": "CompteBancaire.java", "content": "public class CompteBancaire implements Compte {\\n  private int balance;\\n  public void deposer(int montant) { balance += montant; }\\n  public int retirer(int montant) { balance -= montant; return montant; }\\n  public int getBalance() { return balance; }\\n}"}, {"name": "TestClone.java", "content": "public class TestClone implements Cloneable {\\n  int value = 10;\\n  @Override\\n  public Object clone() throws CloneNotSupportedException {\\n    return super.clone();\\n  }\\n}"}], "label": "2. Validated Solution (Default + Static + Marker)", "activity_id": "act_1", "description": "Default transfer, static total and Cloneable correctly implemented.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Remisable.java", "content": "public interface Remisable {\\n  void appliquerRemise(double pourcentage);\\n}"}, {"name": "Facturable.java", "content": "public interface Facturable {\\n  double getPrixFacture();\\n}"}, {"name": "Service.java", "content": "public class Service implements Facturable {\\n  private String nom;\\n  private double prixHeure;\\n  public Service(String nom, double prixHeure) { this.nom = nom; this.prixHeure = prixHeure; }\\n  public double getPrixFacture() { return prixHeure; }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Service s1 = new Service(\\"Installation Reseau\\", 50);\\n    System.out.println(s1.getPrixFacture());\\n  }\\n}"}], "label": "1. Buggy Yalla POS (No Default, No Static, No Clone)", "activity_id": "act_2", "description": "No default loyalty, no static header, Service not cloneable.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Remisable.java", "content": "public interface Remisable {\\n  void appliquerRemise(double pourcentage);\\n  default void appliquerRemiseFidelite() {\\n    appliquerRemise(5);\\n  }\\n}"}, {"name": "Facturable.java", "content": "public interface Facturable {\\n  double getPrixFacture();\\n  static void imprimerEnTeteEnseigne() {\\n    System.out.println(\\"================ YALLA POS ================\\");\\n  }\\n}"}, {"name": "Service.java", "content": "public class Service implements Facturable, Cloneable {\\n  private String nom;\\n  private double prixHeure;\\n  public Service(String nom, double prixHeure) { this.nom = nom; this.prixHeure = prixHeure; }\\n  public double getPrixFacture() { return prixHeure; }\\n  @Override\\n  public Object clone() throws CloneNotSupportedException {\\n    return super.clone();\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Facturable.imprimerEnTeteEnseigne();\\n    Service s1 = new Service(\\"Installation Reseau\\", 50);\\n    try {\\n      Service s2 = (Service) s1.clone();\\n      System.out.println(s1.getPrixFacture() + \\" \\" + s2.getPrixFacture());\\n    } catch (CloneNotSupportedException e) {\\n      e.printStackTrace();\\n    }\\n  }\\n}"}], "label": "2. Validated Solution (Remisable + Header + Clone)", "activity_id": "act_2", "description": "Loyalty default, static header and Cloneable Service with try/catch duplication.", "preset_type": "solution"}]	t	2026-11-01 22:20:03.105+00	[{"page": 1, "text": "TP 10 : Interfaces avancées (Méthodes par défaut, statiques et marqueurs)\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Faire évoluer une interface sans casser les implémentations existantes grâce aux\\nméthodes default .\\n Déclarer et utiliser des méthodes static directement au sein d'une interface.\\n Utiliser des interfaces \\"marqueurs\\" (sans méthodes) pour signaler un comportement\\nspécifique à la machine virtuelle Java (ex: Cloneable ).\\nActivité N°1 (Indépendante) : Gestion bancaire et Clonage profond\\nDans cette activité, nous allons explorer les fonctionnalités modernes des interfaces\\n(apparues depuis Java 8) en simulant un système de comptes bancaires, puis nous\\nétudierons le clonage d'objets.\\n1. L'implémentation par défaut ( default ) :\\no Créez une interface Compte contenant les méthodes abstraites void\\ndeposer(int montant) , int retirer(int montant) , et int\\ngetBalance() .\\no Créez une classe CompteBancaire qui implémente cette interface de manière\\nclassique.\\no Imaginons que l'on veuille ajouter une fonctionnalité de transfert sans obliger\\ntoutes les classes existantes à réécrire leur code. Ajoutez la méthode suivante\\ndans l'interface Compte : default void transferer(Compte\\ndestination) .\\no Dans le corps de cette méthode default , utilisez this.retirer(montant) et\\ndestination.deposer(montant) pour réaliser le transfert. Constatez que\\nCompteBancaire hérite de ce comportement automatiquement !\\n2. La méthode statique ( static ) :\\no Ajoutez une méthode static int getBalanceTotale(Compte...\\ncomptes) dans l'interface Compte qui parcourt les comptes passés en\\nparamètre pour retourner la somme de leurs soldes.\\n3. L'interface marqueur ( Cloneable ) :\\no Créez une classe TestClone avec des attributs simples.\\no Pour autoriser la duplication de cet objet, déclarez qu'il implements\\nCloneable (une interface marqueur qui ne contient aucune méthode).\\no Redéfinissez la méthode clone() héritée de la classe Object . Notez que si\\nl'interface marqueur n'est pas présente, Java lèvera une\\nCloneNotSupportedException à l'exécution.\\nActivité N°2 (Projet Fil Rouge) : Évolution des contrats et duplication dans Yalla POS\\nNotre architecture à base d'interfaces (comme Facturable ) est excellente, mais le client\\ndemande deux nouvelles fonctionnalités urgentes : un système de remise fidélité global, et"}, {"page": 2, "text": "TP 10 : Interfaces avancées (Méthodes par défaut, statiques et marqueurs) Mohamed Belhassen\\nla possibilité pour le caissier de \\"dupliquer\\" une ligne du ticket (par exemple, pour un Service\\ncomplexe paramétré sur mesure) pour gagner du temps.\\nTravail demandé :\\n1. Le contrat évolutif (Remisable) :\\no Créez une nouvelle interface Remisable .\\no Ajoutez une méthode abstraite void appliquerRemise(double\\npourcentage); .\\no Ajoutez une méthode par défaut : default void\\nappliquerRemiseFidelite() . Son implémentation appellera simplement\\nappliquerRemise(5); pour accorder automatiquement 5% de remise aux\\nclients fidèles.\\no Faites en sorte que la classe ArticleElectronique implémente Remisable ,\\net définissez le comportement de appliquerRemise (modifier le prix HT).\\n2. L'utilitaire statique dans Facturable :\\no Ouvrez votre interface Facturable .\\no Ajoutez une méthode statique static void imprimerEnTeteEnseigne()\\nqui affiche : \\"================ YALLA POS ================\\" .\\no Dans votre YallaPOS , appelez Facturable.imprimerEnTeteEnseigne()\\ntout au début de l'impression de votre ticket.\\n3. Duplication de Service (Cloneable) :\\no Ouvrez votre classe Service (qui implémente déjà Facturable ).\\no Ajoutez l'interface marqueur : implements Facturable, Cloneable .\\no Surchargez la méthode clone() pour permettre la copie de ce service.\\no Dans YallaPOS , instanciez un Service (ex: \\"Installation Réseau\\" à 50 TND/h).\\nUtilisez la méthode clone() pour créer un deuxième service identique et\\najoutez les deux au panier . (Gérez temporairement l'exception avec un bloc\\ntry/catch autogénéré par votre IDE).\\nBilan du TP 10 : Ce qu'il faut retenir\\nÀ la fin de ce TP, vous devez avoir validé les points suivants :\\n [ ] Méthodes default : Vous savez comment ajouter de nouvelles fonctionnalités à\\nune interface sans provoquer d'erreurs de compilation dans les classes existantes.\\n [ ] Méthodes static : Vous savez regrouper des méthodes utilitaires directement\\ndans l'interface concernée plutôt que de créer des classes externes.\\n [ ] Interfaces Marqueurs : Vous comprenez que l'implémentation de Cloneable agit\\ncomme une \\"étiquette\\" autorisant la JVM à cloner l'objet en mémoire.\\n [ ] Yalla POS : Votre système tire désormais parti des fonctionnalités les plus\\navancées des interfaces pour la duplication et les remises automatiques.\\nLa suite : Lors de l'activité sur le clonage, votre IDE (Eclipse, IntelliJ ou NetBeans) vous a\\nprobablement forcé à ajouter un étrange bloc try { ... } catch { ... } autour de\\nvotre appel à clone() , sous peine de refuser de compiler. Pourquoi le langage Java est-il si\\nexigeant à cet endroit précis ? C'est parce qu'une opération de clonage peut potentiellement\\néchouer (l'erreur CloneNotSupportedException ) ! Lors du prochain TP, nous allons enfin"}, {"page": 3, "text": "TP 10 : Interfaces avancées (Méthodes par défaut, statiques et marqueurs) Mohamed Belhassen\\npercer le mystère de la Gestion des Exceptions . Nous apprendrons à anticiper les erreurs\\nd'exécution (comme une division par zéro, ou un prix invalide en caisse) pour éviter que\\nnotre application Yalla POS ne plante brutalement en plein milieu de la journée !"}]	{"en": "TP 10 — Lab 10: Advanced Interfaces (Default, Static and Marker Methods)", "fr": "TP 10 : Interfaces avancées (Méthodes par défaut, statiques et marqueurs)"}	{"en": "This lab teaches evolving interfaces without breaking implementations via default and static methods and using the Cloneable marker, applied to a banking system then to Yalla POS for loyalty discounts and service duplication.", "fr": "Ce TP apprend à faire évoluer les interfaces sans casser l'existant grâce aux méthodes default et static et à exploiter le marqueur Cloneable, appliqués à un système bancaire puis à Yalla POS pour remises fidélité et duplication de services."}	2026-11-02 20:07:42.438083+00
8390d7ac-a7e5-4e9e-9568-e07ed07da0bc	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	3	TP3	TP 3 — Lab 3: Arrays and String Manipulation	This lab teaches declaring, allocating and traversing 1D and 2D arrays and manipulating text with immutable String versus mutable StringBuffer, culminating in a detailed YallaPOS receipt memorizing the full cart.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp3.pdf	[{"id": "act_1", "order": 1, "title": "Activity 1 (Independent): Grade management and text formatting", "milestones": [{"id": "m1_1", "order": 1, "title": "Declaration of the 2D notes array", "title_i18n": {"en": "Declaration of the 2D notes array", "fr": "Déclaration du tableau 2D des notes"}, "validation_criteria": "The `double` array `notes` is directly initialized with 3 rows and 2 columns containing {{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}} inside `GestionNotes`.", "validation_criteria_i18n": {"en": "The `double` array `notes` is directly initialized with 3 rows and 2 columns containing {{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}} inside `GestionNotes`.", "fr": "Le tableau `notes` de type `double` est initialisé directement avec 3 lignes et 2 colonnes contenant {{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}} dans `GestionNotes`."}}, {"id": "m1_2", "order": 2, "title": "Overall average computed with nested loops", "title_i18n": {"en": "Overall average computed with nested loops", "fr": "Moyenne générale calculée par boucles imbriquées"}, "validation_criteria": "Nested loops traverse the entire `notes` array without overflow and correctly compute the average of all grades.", "validation_criteria_i18n": {"en": "Nested loops traverse the entire `notes` array without overflow and correctly compute the average of all grades.", "fr": "Des boucles imbriquées parcourent l'intégralité du tableau `notes` sans débordement et calculent correctement la moyenne de toutes les notes."}}, {"id": "m1_3", "order": 3, "title": "Dynamic report built with StringBuffer", "title_i18n": {"en": "Dynamic report built with StringBuffer", "fr": "Rapport dynamique construit avec StringBuffer"}, "validation_criteria": "`rapport` is initialized with `new StringBuffer(\\"Bilan : \\")`, conditionally completed according to average >= 10 and displayed with the concatenated average.", "validation_criteria_i18n": {"en": "`rapport` is initialized with `new StringBuffer(\\"Bilan : \\")`, conditionally completed according to average >= 10 and displayed with the concatenated average.", "fr": "`rapport` est initialisé avec `new StringBuffer(\\"Bilan : \\")`, complété conditionnellement selon moyenne >= 10 et affiché avec la moyenne concaténée."}}], "title_i18n": {"en": "Activity 1 (Independent): Grade management and text formatting", "fr": "Activité N°1 (Indépendante) : Gestion des notes et formatage de texte"}, "target_files": ["GestionNotes.java"], "instructions_i18n": {"en": "Objective: process a 2D grid of grades and dynamically build an evaluation report with `StringBuffer`.\\n\\nImplementation Steps:\\n1. Create the class `GestionNotes`.\\n2. Declare and directly initialize the 2D `double` array `notes` with `{{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}}`.\\n   * 3 students x 2 subjects.\\n3. Compute the class overall average with nested loops.\\n   * Traverse all elements of `notes` with nested loops and average all grades.\\n4. Build a dynamic message with `StringBuffer`.\\n   * Initialize with `StringBuffer rapport = new StringBuffer(\\"Bilan : \\")`.\\n   * If average >= 10, append `\\"Classe validée avec la moyenne de \\"`, otherwise append `\\"Niveau insuffisant, moyenne de \\"`.\\n   * Concatenate the computed average at the end of `rapport`.\\n5. Display the final content of `rapport` on the console.", "fr": "Objectif : traiter une grille de notes en 2D et construire dynamiquement un bilan d'évaluation avec `StringBuffer`.\\n\\nÉtapes de réalisation :\\n1. Créez une classe `GestionNotes`.\\n2. Déclarez et initialisez directement le tableau 2D de `double` nommé `notes` avec `{{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}}`.\\n   * 3 étudiants x 2 matières.\\n3. Calculez la moyenne générale de la classe avec des boucles imbriquées.\\n   * Parcourez tous les éléments de `notes` et faites la moyenne de toutes les notes.\\n4. Construisez un message dynamique avec `StringBuffer`.\\n   * Initialisez-le avec `StringBuffer rapport = new StringBuffer(\\"Bilan : \\")`.\\n   * Si la moyenne est supérieure ou égale à 10, ajoutez `\\"Classe validée avec la moyenne de \\"`, sinon ajoutez `\\"Niveau insuffisant, moyenne de \\"`.\\n   * Concaténez la moyenne calculée à la fin du `rapport`.\\n5. Affichez le contenu final du `rapport` en console."}, "instructions_markdown": "Objective: process a 2D grid of grades and dynamically build an evaluation report with `StringBuffer`.\\n\\nImplementation Steps:\\n1. Create the class `GestionNotes`.\\n2. Declare and directly initialize the 2D `double` array `notes` with `{{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}}`.\\n   * 3 students x 2 subjects.\\n3. Compute the class overall average with nested loops.\\n   * Traverse all elements of `notes` with nested loops and average all grades.\\n4. Build a dynamic message with `StringBuffer`.\\n   * Initialize with `StringBuffer rapport = new StringBuffer(\\"Bilan : \\")`.\\n   * If average >= 10, append `\\"Classe validée avec la moyenne de \\"`, otherwise append `\\"Niveau insuffisant, moyenne de \\"`.\\n   * Concatenate the computed average at the end of `rapport`.\\n5. Display the final content of `rapport` on the console."}, {"id": "act_2", "order": 2, "title": "Activity 2 (Red Thread Project): Detailed Yalla POS receipt", "milestones": [{"id": "m2_1", "order": 1, "title": "Allocation of parallel arrays", "title_i18n": {"en": "Allocation of parallel arrays", "fr": "Allocation des tableaux parallèles"}, "validation_criteria": "`MAX_ARTICLES` equals 10 and `nomsArticles` (String) and `prixArticles` (double) are instantiated with `new Type[MAX_ARTICLES]`.", "validation_criteria_i18n": {"en": "`MAX_ARTICLES` equals 10 and `nomsArticles` (String) and `prixArticles` (double) are instantiated with `new Type[MAX_ARTICLES]`.", "fr": "`MAX_ARTICLES` vaut 10 et `nomsArticles` (`String`) et `prixArticles` (`double`) sont instanciés avec `new Type[MAX_ARTICLES]`."}}, {"id": "m2_2", "order": 2, "title": "Memorized input loop with counter", "title_i18n": {"en": "Memorized input loop with counter", "fr": "Boucle de saisie mémorisée avec compteur"}, "validation_criteria": "`compteur` tracks additions, `Scanner` stores inputs in `nomsArticles[compteur]` and `prixArticles[compteur]` with increment, stopping on price 0 or `MAX_ARTICLES` without overflow.", "validation_criteria_i18n": {"en": "`compteur` tracks additions, `Scanner` stores inputs in `nomsArticles[compteur]` and `prixArticles[compteur]` with increment, stopping on price 0 or `MAX_ARTICLES` without overflow.", "fr": "`compteur` suit les ajouts, `Scanner` stocke les saisies dans `nomsArticles[compteur]` et `prixArticles[compteur]` avec incrémentation, arrêt sur prix 0 ou `MAX_ARTICLES` sans débordement."}}, {"id": "m2_3", "order": 3, "title": "Detailed ticket printing and totals", "title_i18n": {"en": "Detailed ticket printing and totals", "fr": "Impression du ticket détaillé et totaux"}, "validation_criteria": "`for` loop from 0 to `compteur` displays each article and price, computes `totalHT`, then displays TVA and final TTC.", "validation_criteria_i18n": {"en": "`for` loop from 0 to `compteur` displays each article and price, computes `totalHT`, then displays TVA and final TTC.", "fr": "Boucle `for` de 0 jusqu'au `compteur` affichant chaque article et son prix, calculant le `totalHT`, puis affichant la TVA et le TTC final."}}], "title_i18n": {"en": "Activity 2 (Red Thread Project): Detailed Yalla POS receipt", "fr": "Activité N°2 (Projet Fil Rouge) : Le ticket de caisse détaillé de Yalla POS"}, "target_files": ["YallaPOS.java"], "instructions_i18n": {"en": "Objective: memorize the full cart in parallel arrays to print a detailed POS receipt in `YallaPOS`.\\n\\nImplementation Steps:\\n1. Allocate the arrays.\\n   * Define an integer constant `MAX_ARTICLES` set to 10.\\n   * Declare and instantiate a `String` array named `nomsArticles` of size `MAX_ARTICLES`.\\n   * Declare and instantiate a `double` array named `prixArticles` of the same size.\\n2. Memorized input loop with `compteur`.\\n   * Add a `compteur` variable initialized to 0.\\n   * In your input loop using `Scanner`, ask for the article name then its price.\\n   * Store values in `nomsArticles[compteur]` and `prixArticles[compteur]`, then increment `compteur`.\\n   * The loop must stop if the cashier enters a price of 0, or if `compteur` reaches `MAX_ARTICLES`.\\n3. Print the detailed ticket.\\n   * Display a separation line.\\n   * Use a `for` loop from 0 to `compteur` to display each article and its price (e.g. `- Clavier Mécanique : 45.50 TND`).\\n   * In the same loop, sum to obtain `totalHT`.\\n4. Finalize by computing and displaying VAT (`TVA`) and final TTC at the bottom of the ticket.", "fr": "Objectif : mémoriser l'intégralité du panier dans des tableaux parallèles pour imprimer un ticket détaillé dans `YallaPOS`.\\n\\nÉtapes de réalisation :\\n1. L'allocation des tableaux.\\n   * Définissez une constante entière `MAX_ARTICLES` fixée à 10.\\n   * Déclarez et instanciez un tableau de `String` nommé `nomsArticles` d'une taille de `MAX_ARTICLES`.\\n   * Déclarez et instanciez un tableau de `double` nommé `prixArticles` de la même taille.\\n2. La boucle de saisie mémorisée avec `compteur`.\\n   * Ajoutez une variable `compteur` initialisée à 0.\\n   * Dans votre boucle de saisie (utilisant `Scanner`), demandez le nom de l'article puis son prix.\\n   * Stockez ces valeurs dans `nomsArticles[compteur]` et `prixArticles[compteur]`, puis incrémentez le `compteur`.\\n   * La boucle doit s'arrêter si le caissier saisit un prix de 0, ou si le `compteur` atteint `MAX_ARTICLES`.\\n3. L'impression du ticket détaillé.\\n   * Affichez une ligne de séparation.\\n   * Utilisez une boucle `for` allant de 0 jusqu'au `compteur` pour afficher chaque article et son prix (ex : `- Clavier Mécanique : 45.50 TND`).\\n   * Dans cette même boucle, calculez la somme pour obtenir le `totalHT`.\\n4. Finalisation : calculez et affichez la TVA et le TTC final en bas du ticket."}, "instructions_markdown": "Objective: memorize the full cart in parallel arrays to print a detailed POS receipt in `YallaPOS`.\\n\\nImplementation Steps:\\n1. Allocate the arrays.\\n   * Define an integer constant `MAX_ARTICLES` set to 10.\\n   * Declare and instantiate a `String` array named `nomsArticles` of size `MAX_ARTICLES`.\\n   * Declare and instantiate a `double` array named `prixArticles` of the same size.\\n2. Memorized input loop with `compteur`.\\n   * Add a `compteur` variable initialized to 0.\\n   * In your input loop using `Scanner`, ask for the article name then its price.\\n   * Store values in `nomsArticles[compteur]` and `prixArticles[compteur]`, then increment `compteur`.\\n   * The loop must stop if the cashier enters a price of 0, or if `compteur` reaches `MAX_ARTICLES`.\\n3. Print the detailed ticket.\\n   * Display a separation line.\\n   * Use a `for` loop from 0 to `compteur` to display each article and its price (e.g. `- Clavier Mécanique : 45.50 TND`).\\n   * In the same loop, sum to obtain `totalHT`.\\n4. Finalize by computing and displaying VAT (`TVA`) and final TTC at the bottom of the ticket."}]	{PRIMITIVE_ARRAY_STRING,CONTROL_FLOW_BREAK,STRINGBUFFER_MUTABLE}	[{"key": "act_1_buggy", "files": [{"name": "GestionNotes.java", "content": "public class GestionNotes {\\n  public static void main(String[] args) {\\n    double[][] notes = {{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}};\\n    double somme = 0;\\n    for (int i = 0; i <= 3; i++) {\\n      for (int j = 0; j <= 2; j++) {\\n        somme += notes[i][j];\\n      }\\n    }\\n    double moyenne = somme / 6;\\n    String rapport = \\"Bilan : \\";\\n    if (moyenne == 10) {\\n      rapport += \\"Classe validee avec la moyenne de \\";\\n    }\\n    rapport += moyenne;\\n    System.out.println(rapport);\\n  }\\n}"}], "label": "1. Buggy Grades (Overflow + No StringBuffer)", "activity_id": "act_1", "description": "Uses String instead of StringBuffer and overflows the 2D array with <= bounds.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "GestionNotes.java", "content": "public class GestionNotes {\\n  public static void main(String[] args) {\\n    double[][] notes = {{12.5, 14.0}, {9.0, 11.5}, {15.0, 16.5}};\\n    double somme = 0;\\n    int nb = 0;\\n    for (int i = 0; i < notes.length; i++) {\\n      for (int j = 0; j < notes[i].length; j++) {\\n        somme += notes[i][j];\\n        nb++;\\n      }\\n    }\\n    double moyenne = somme / nb;\\n    StringBuffer rapport = new StringBuffer(\\"Bilan : \\");\\n    if (moyenne >= 10) {\\n      rapport.append(\\"Classe validee avec la moyenne de \\");\\n    } else {\\n      rapport.append(\\"Niveau insuffisant, moyenne de \\");\\n    }\\n    rapport.append(moyenne);\\n    System.out.println(rapport.toString());\\n  }\\n}"}], "label": "2. Validated Solution (Grades + StringBuffer)", "activity_id": "act_1", "description": "Correct 2D traversal, average and conditional StringBuffer report.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void main(String[] args) {\\n    int MAX_ARTICLES = 10;\\n    String[] nomsArticles = new String[MAX_ARTICLES];\\n    double[] prixArticles = new double[MAX_ARTICLES];\\n    Scanner sc = new Scanner(System.in);\\n    int compteur = 0;\\n    while (true) {\\n      System.out.print(\\"Nom article : \\");\\n      String nom = sc.nextLine();\\n      System.out.print(\\"Prix (0 pour finir) : \\");\\n      double prix = sc.nextDouble();\\n      sc.nextLine();\\n      nomsArticles[compteur] = nom;\\n      prixArticles[compteur] = prix;\\n      compteur++;\\n      if (compteur > MAX_ARTICLES) break;\\n    }\\n    double totalHT = 0;\\n    for (int i = 0; i <= compteur; i++) {\\n      System.out.println(\\"- \\" + nomsArticles[i] + \\" : \\" + prixArticles[i] + \\" TND\\");\\n      totalHT += prixArticles[i];\\n    }\\n    System.out.println(\\"TotalHT : \\" + totalHT);\\n  }\\n}"}], "label": "1. Buggy Cart (Overflow + No TVA)", "activity_id": "act_2", "description": "Stores terminating 0 price and overflows with <= compteur and missing TVA/TTC.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void main(String[] args) {\\n    final int MAX_ARTICLES = 10;\\n    String[] nomsArticles = new String[MAX_ARTICLES];\\n    double[] prixArticles = new double[MAX_ARTICLES];\\n    Scanner sc = new Scanner(System.in);\\n    int compteur = 0;\\n    while (compteur < MAX_ARTICLES) {\\n      System.out.print(\\"Nom article : \\");\\n      String nom = sc.nextLine();\\n      System.out.print(\\"Prix (0 pour finir) : \\");\\n      double prix = sc.nextDouble();\\n      sc.nextLine();\\n      if (prix == 0) break;\\n      nomsArticles[compteur] = nom;\\n      prixArticles[compteur] = prix;\\n      compteur++;\\n    }\\n    System.out.println(\\"---------------- TICKET ----------------\\");\\n    double totalHT = 0;\\n    for (int i = 0; i < compteur; i++) {\\n      System.out.println(\\"- \\" + nomsArticles[i] + \\" : \\" + prixArticles[i] + \\" TND\\");\\n      totalHT += prixArticles[i];\\n    }\\n    double tva = totalHT * 0.19;\\n    double ttc = totalHT + tva;\\n    System.out.println(\\"TotalHT : \\" + totalHT + \\" TND\\");\\n    System.out.println(\\"TVA (19%) : \\" + tva + \\" TND\\");\\n    System.out.println(\\"TTC : \\" + ttc + \\" TND\\");\\n    sc.close();\\n  }\\n}"}], "label": "2. Validated Solution (Detailed Ticket)", "activity_id": "act_2", "description": "Correct parallel arrays, guarded Scanner loop and detailed ticket with TVA/TTC.", "preset_type": "solution"}]	t	2026-11-01 23:15:35.272+00	[{"page": 1, "text": "TP 3 : Tableaux et manipulation des chaînes de caractères\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Déclarer, allouer et parcourir des tableaux à une ou deux dimensions.\\n Manipuler et comparer des chaînes de caractères avec la classe String .\\n Optimiser les modifications de texte à l'aide de la classe StringBuffer .\\nActivité N°1 (Indépendante) : Gestion des notes et formatage de texte\\nDans cette activité, nous allons manipuler les tableaux à deux dimensions pour traiter des\\ndonnées en grille, et utiliser StringBuffer pour construire dynamiquement un message de\\nrésultat.\\n1. Créez une classe GestionNotes .\\n2. Déclarez et initialisez directement un tableau 2D de double nommé notes\\nreprésentant les notes de 3 étudiants dans 2 matières. Par exemple : {{12.5,\\n14.0}, {9.0, 11.5}, {15.0, 16.5}} .\\n3. Utilisez des boucles imbriquées pour calculer la moyenne générale de la classe (la\\nmoyenne de toutes les notes du tableau).\\n4. Utilisez la classe StringBuffer pour construire un message d'évaluation dynamique.\\no Initialisez-le avec : StringBuffer rapport = new StringBuffer(\\"Bilan :\\n\\"); .\\no Si la moyenne est supérieure ou égale à 10, ajoutez au rapport \\"Classe\\nvalidée avec la moyenne de \\" .\\no Sinon, ajoutez \\"Niveau insuffisant, moyenne de \\" .\\no Concaténez la moyenne calculée à la fin du StringBuffer .\\n5. Affichez le contenu final du rapport en console.\\nActivité N°2 (Projet Fil Rouge) : Le ticket de caisse détaillé de Yalla POS\\nJusqu'à présent, notre caisse oubliait les articles au fur et à mesure de la saisie. Nous allons\\nutiliser des tableaux pour mémoriser l'intégralité du panier et imprimer un ticket détaillé\\ndigne d'un vrai Point de Vente.\\nTravail demandé : Mettez à jour votre classe YallaPOS avec la nouvelle logique suivante :\\n1. L'allocation des tableaux :\\no Définissez une constante entière MAX_ARTICLES fixée à 10.\\no Déclarez et instanciez un tableau de String nommé nomsArticles d'une\\ntaille de MAX_ARTICLES .\\no Déclarez et instanciez un tableau de double nommé prixArticles de la\\nmême taille.\\n2. La boucle de saisie mémorisée :\\no Ajoutez une variable compteur initialisée à 0 pour suivre le nombre d'articles\\najoutés."}, {"page": 2, "text": "TP 3 : Tableaux et manipulation des chaînes de caractères Mohamed Belhassen\\no Dans votre boucle de saisie (utilisant Scanner ), demandez le nom de l'article\\npuis son prix.\\no Stockez ces valeurs dans nomsArticles[compteur] et\\nprixArticles[compteur] , puis incrémentez le compteur .\\no La boucle doit s'arrêter si le caissier saisit un prix de 0, ou si le compteur\\natteint MAX_ARTICLES .\\n3. L'impression du ticket détaillé :\\no Videz l'écran de la console (ou affichez une ligne de séparation).\\no Utilisez une boucle for (allant de 0 jusqu'au compteur ) pour afficher\\nproprement chaque article et son prix (ex: - Clavier Mécanique : 45.50\\nTND ).\\no Dans cette même boucle, calculez la somme pour obtenir le totalHT .\\n4. Finalisation : Calculez et affichez la TVA et le TTC final en bas du ticket.\\nBilan du TP 3 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Tableaux : Vous savez instancier des tableaux ( new Type[taille] ) et accéder à\\nleurs éléments via leurs indices.\\n [ ] Parcours : Vous maîtrisez les boucles ( for ) pour lire et écrire l'intégralité d'un\\ntableau, en faisant attention à ne pas déborder.\\n [ ] Manipulation de texte : Vous différenciez l'usage d'un String immuable de celui\\nd'un StringBuffer modifiable en mémoire.\\n [ ] Yalla POS : Votre système génère désormais un véritable ticket de caisse détaillé\\nretraçant l'ensemble de la transaction.\\nLa suite : Pour l'instant, notre caisse utilise des tableaux \\"parallèles\\" (un tableau pour les\\nnoms, un tableau pour les prix). Cela devient vite ingérable si l'on souhaite rajouter des\\ncodes-barres, des quantités ou des catégories d'articles ! Lors du prochain TP, nous\\nfranchirons un cap majeur en abordant la Programmation Orientée Objet (POO) . Nous\\nallons créer notre toute première classe Article qui encapsulera toutes ces données, et\\nnous instancierons de véritables objets en mémoire pour remplacer nos tableaux séparés."}]	{"en": "TP 3 — Lab 3: Arrays and String Manipulation", "fr": "TP 3 : Tableaux et manipulation des chaînes de caractères"}	{"en": "This lab teaches declaring, allocating and traversing 1D and 2D arrays and manipulating text with immutable String versus mutable StringBuffer, culminating in a detailed YallaPOS receipt memorizing the full cart.", "fr": "Ce TP apprend à déclarer, allouer et parcourir des tableaux à une et deux dimensions et à manipuler le texte avec String immuable versus StringBuffer modifiable, en culminant avec un ticket de caisse détaillé mémorisant tout le panier dans YallaPOS."}	2026-11-02 20:07:42.438083+00
644e4f09-8c84-4529-a178-6f47996829ef	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	1	TP1	TP 1 — Lab 1: Introduction to Java and Variable Manipulation	This lab introduces Java program structure (Bytecode, JVM), primitive variables and explicit/implicit casting, while building the static receipt calculation base for Yalla POS.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp1.pdf	[{"id": "act_1", "order": 1, "title": "Activity 1 (Independent): Arithmetic operations and casting", "milestones": [{"id": "m1_1", "order": 1, "title": "Calculatrice class and integer division", "title_i18n": {"en": "Calculatrice class and integer division", "fr": "Classe Calculatrice et division entière"}, "validation_criteria": "The class `Calculatrice` contains `main`, declares `int` `a` = 15 and `b` = 2 and displays `a / b` showing integer result 7.", "validation_criteria_i18n": {"en": "The class `Calculatrice` contains `main`, declares `int` `a` = 15 and `b` = 2 and displays `a / b` showing integer result 7.", "fr": "La classe `Calculatrice` contient `main`, déclare `a` = 15 et `b` = 2 de type `int` et affiche `a / b` avec le résultat entier 7."}}, {"id": "m1_2", "order": 2, "title": "Fix with cast to float/double", "title_i18n": {"en": "Fix with cast to float/double", "fr": "Correction par transtypage vers float/double"}, "validation_criteria": "An explicit cast such as `(double) a / b` produces 7.5 stored and displayed in a `float` or `double` variable.", "validation_criteria_i18n": {"en": "An explicit cast such as `(double) a / b` produces 7.5 stored and displayed in a `float` or `double` variable.", "fr": "Un cast explicite comme `(double) a / b` produit 7.5 stocké et affiché dans une variable de type `float` ou `double`."}}, {"id": "m1_3", "order": 3, "title": "PI constant and circle perimeter", "title_i18n": {"en": "PI constant and circle perimeter", "fr": "Constante PI et périmètre du cercle"}, "validation_criteria": "Constant `PI` declared with `final` = 3.14159, radius `r` = 5.5, perimeter `2 * PI * r` computed and displayed formatted.", "validation_criteria_i18n": {"en": "Constant `PI` declared with `final` = 3.14159, radius `r` = 5.5, perimeter `2 * PI * r` computed and displayed formatted.", "fr": "Constante `PI` déclarée avec `final` = 3.14159, rayon `r` = 5.5, périmètre `2 * PI * r` calculé et affiché formaté."}}], "title_i18n": {"en": "Activity 1 (Independent): Arithmetic operations and casting", "fr": "Activité N°1 (Indépendante) : Opérations arithmétiques et transtypage"}, "target_files": ["Calculatrice.java"], "instructions_i18n": {"en": "Objective: manipulate numeric types and observe Java compiler behavior during conversions.\\n\\nImplementation Steps:\\n1. Create the class `Calculatrice` containing the `main` method.\\n2. Declare two `int` variables `a` and `b` initialized to `15` and `2`, compute and display `a / b` and observe integer division.\\n3. Fix the code using an explicit cast to `double` or `float` to obtain the exact result `7.5` stored in a `double` or `float` variable.\\n4. Declare a constant `PI` with the keyword `final` initialized to `3.14159`, declare a radius `r` = `5.5` and compute and display the circle perimeter `2 * PI * r`.", "fr": "Objectif : manipuler les types de données numériques et observer le comportement du compilateur Java lors des conversions.\\n\\nÉtapes de réalisation :\\n1. Créez une classe `Calculatrice` contenant la méthode `main`.\\n2. Déclarez deux variables entières `a` et `b` initialisées respectivement à `15` et `2`, calculez et affichez le résultat de la division de `a` par `b` et observez la division entière.\\n3. Corrigez le code en utilisant le transtypage (cast) vers `double` ou `float` pour obtenir le résultat exact `7.5` stocké dans une variable de type `float` ou `double`.\\n4. Déclarez une constante `PI` avec le mot-clé `final` initialisée à `3.14159`, déclarez un rayon `r` = `5.5` et calculez puis affichez le périmètre du cercle `2 * PI * r`."}, "instructions_markdown": "Objective: manipulate numeric types and observe Java compiler behavior during conversions.\\n\\nImplementation Steps:\\n1. Create the class `Calculatrice` containing the `main` method.\\n2. Declare two `int` variables `a` and `b` initialized to `15` and `2`, compute and display `a / b` and observe integer division.\\n3. Fix the code using an explicit cast to `double` or `float` to obtain the exact result `7.5` stored in a `double` or `float` variable.\\n4. Declare a constant `PI` with the keyword `final` initialized to `3.14159`, declare a radius `r` = `5.5` and compute and display the circle perimeter `2 * PI * r`."}, {"id": "act_2", "order": 2, "title": "Activity 2 (Red-Thread Project): Initialization of the \\"Yalla POS\\" cash register", "milestones": [{"id": "m2_1", "order": 1, "title": "Receipt header with escape sequences", "title_i18n": {"en": "Receipt header with escape sequences", "fr": "En-tête du ticket avec séquences d'échappement"}, "validation_criteria": "Class `YallaPOS` with `main` displays the welcome message using `\\\\n` and `\\\\t` for formatted output.", "validation_criteria_i18n": {"en": "Class `YallaPOS` with `main` displays the welcome message using `\\\\n` and `\\\\t` for formatted output.", "fr": "La classe `YallaPOS` avec `main` affiche le message de bienvenue en utilisant `\\\\n` et `\\\\t` pour un affichage formaté."}}, {"id": "m2_2", "order": 2, "title": "Hard-coded item data declaration", "title_i18n": {"en": "Hard-coded item data declaration", "fr": "Déclaration des données de l'article en dur"}, "validation_criteria": "Variables declared with correct types: item name `String`, HT unit price `double`, quantity `int`, VAT rate `double`.", "validation_criteria_i18n": {"en": "Variables declared with correct types: item name `String`, HT unit price `double`, quantity `int`, VAT rate `double`.", "fr": "Variables déclarées avec les bons types : nom article `String`, prix unitaire HT `double`, quantité `int`, taux TVA `double`."}}, {"id": "m2_3", "order": 3, "title": "HT, VAT, TTC calculations and receipt rendering", "title_i18n": {"en": "HT, VAT, TTC calculations and receipt rendering", "fr": "Calculs HT, TVA, TTC et rendu du ticket"}, "validation_criteria": "Total HT, VAT amount and total TTC correctly computed and receipt recap displayed with `Sous-Total HT`, `TVA (19%)` and `TOTAL A PAYER`.", "validation_criteria_i18n": {"en": "Total HT, VAT amount and total TTC correctly computed and receipt recap displayed with `Sous-Total HT`, `TVA (19%)` and `TOTAL A PAYER`.", "fr": "Total HT, montant TVA et total TTC correctement calculés et récapitulatif affiché avec `Sous-Total HT`, `TVA (19%)` et `TOTAL A PAYER`."}}], "title_i18n": {"en": "Activity 2 (Red-Thread Project): Initialization of the \\"Yalla POS\\" cash register", "fr": "Activité N°2 (Projet Fil Rouge) : Initialisation de la caisse \\"Yalla POS\\""}, "target_files": ["YallaPOS.java"], "instructions_i18n": {"en": "Objective: start the Yalla POS Console red-thread project with a static receipt printed from hard-coded variables.\\n\\nImplementation Steps:\\n1. Create the class `YallaPOS` with its `main` method.\\n2. Display a formatted welcome header using escape sequences `\\\\n` and `\\\\t`, e.g. `*** Bienvenue sur Yalla POS ***` `*** Votre terminal d'encaissement ***`.\\n3. Declare and initialize hard-coded item data: item name `String`, unit price HT of type `double` (e.g. 45.50), purchased quantity of type `int` (e.g. 3), VAT rate of type `double` (e.g. 0.19).\\n4. Compute total HT (`prix unitaire * quantité`), VAT amount (`total HT * taux TVA`) and total TTC (`Total HT + Montant TVA`).\\n5. Display a clear summary simulating a receipt with `Article`, `Quantité`, `Prix Unitaire HT`, `Sous-Total HT`, `TVA (19%)` and `TOTAL A PAYER`.", "fr": "Objectif : démarrer l'application fil rouge Yalla POS Console avec un ticket de caisse basique affiché à partir de variables en dur.\\n\\nÉtapes de réalisation :\\n1. Créez une classe `YallaPOS` et, dans sa méthode `main`, implémentez les étapes suivantes.\\n2. Affichez un message de bienvenue bien formaté avec les séquences d'échappement `\\\\n` et `\\\\t`, par exemple : `*** Bienvenue sur Yalla POS ***` `*** Votre terminal d'encaissement ***`.\\n3. Déclarez et initialisez en dur les données de l'article : nom de l'article `String` (ex: \\"Clavier Mécanique\\"), prix unitaire HT de type `double` (ex: 45.50), quantité de type `int` (ex: 3), taux de TVA de type `double` (ex: 0.19).\\n4. Calculez le total HT (`prix unitaire * quantité`), le montant de la TVA (`total HT * taux TVA`) et le total TTC (`Total HT + Montant TVA`).\\n5. Affichez un récapitulatif clair simulant un ticket de caisse avec `Article`, `Quantité`, `Prix Unitaire HT`, `Sous-Total HT`, `TVA (19%)` et `TOTAL A PAYER`."}, "instructions_markdown": "Objective: start the Yalla POS Console red-thread project with a static receipt printed from hard-coded variables.\\n\\nImplementation Steps:\\n1. Create the class `YallaPOS` with its `main` method.\\n2. Display a formatted welcome header using escape sequences `\\\\n` and `\\\\t`, e.g. `*** Bienvenue sur Yalla POS ***` `*** Votre terminal d'encaissement ***`.\\n3. Declare and initialize hard-coded item data: item name `String`, unit price HT of type `double` (e.g. 45.50), purchased quantity of type `int` (e.g. 3), VAT rate of type `double` (e.g. 0.19).\\n4. Compute total HT (`prix unitaire * quantité`), VAT amount (`total HT * taux TVA`) and total TTC (`Total HT + Montant TVA`).\\n5. Display a clear summary simulating a receipt with `Article`, `Quantité`, `Prix Unitaire HT`, `Sous-Total HT`, `TVA (19%)` and `TOTAL A PAYER`."}]	{JVM_BYTECODE_JIT,JDK_HELLO_WORKFLOW,IDENTIFIERS_CONSTANTS,PRIMITIVE_ARRAY_STRING,CASTING_SCOPE,STATIC_FINAL_MEMBERS}	[{"key": "act_1_buggy", "files": [{"name": "Calculatrice.java", "content": "public class Calculatrice {\\n  public static void main(String[] args) {\\n    int a = 15;\\n    int b = 2;\\n    double resultat = a / b;\\n    System.out.println(\\"Division: \\" + resultat);\\n    double PI = 3.14159;\\n    double r = 5.5;\\n    double perimetre = 2 * PI * r;\\n    System.out.println(\\"Perimetre: \\" + perimetre);\\n  }\\n}"}], "label": "1. Buggy Calculator (Integer division without cast)", "activity_id": "act_1", "description": "Integer division without cast gives 7.0 and PI is not final.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Calculatrice.java", "content": "public class Calculatrice {\\n  public static void main(String[] args) {\\n    int a = 15;\\n    int b = 2;\\n    System.out.println(\\"Division entiere: \\" + (a / b));\\n    double resultat = (double) a / b;\\n    System.out.println(\\"Division exacte: \\" + resultat);\\n    final double PI = 3.14159;\\n    double r = 5.5;\\n    double perimetre = 2 * PI * r;\\n    System.out.println(\\"Perimetre: \\" + perimetre);\\n  }\\n}"}], "label": "2. Validated Solution (Calculator with cast)", "activity_id": "act_1", "description": "Correct cast to double, final PI and circle perimeter.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    System.out.println(\\"*** Bienvenue sur Yalla POS *** *** Votre terminal d'encaissement ***\\");\\n    String article = \\"Clavier Mecanique\\";\\n    int prixHT = 45;\\n    int quantite = 3;\\n    int tauxTVA = 19;\\n    double totalHT = prixHT * quantite;\\n    double totalTTC = totalHT + tauxTVA;\\n    System.out.println(\\"Article : \\" + article);\\n    System.out.println(\\"TOTAL A PAYER : \\" + totalTTC + \\" TND\\");\\n  }\\n}"}], "label": "1. Buggy Yalla POS (Wrong types and VAT)", "activity_id": "act_2", "description": "Wrong types and VAT formula, no escape sequences for header.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    System.out.println(\\"\\\\n\\\\t*** Bienvenue sur Yalla POS ***\\\\n\\\\t*** Votre terminal d'encaissement ***\\\\n\\");\\n    String article = \\"Clavier Mecanique\\";\\n    double prixHT = 45.50;\\n    int quantite = 3;\\n    double tauxTVA = 0.19;\\n    double totalHT = prixHT * quantite;\\n    double montantTVA = totalHT * tauxTVA;\\n    double totalTTC = totalHT + montantTVA;\\n    System.out.println(\\"-----------------------------------\\");\\n    System.out.println(\\"Article : \\" + article);\\n    System.out.println(\\"Quantite : \\" + quantite);\\n    System.out.println(\\"Prix Unitaire HT : \\" + prixHT + \\" TND\\");\\n    System.out.println(\\"-----------------------------------\\");\\n    System.out.println(\\"Sous-Total HT : \\" + totalHT + \\" TND\\");\\n    System.out.println(\\"TVA (19%) : \\" + montantTVA + \\" TND\\");\\n    System.out.println(\\"TOTAL A PAYER : \\" + totalTTC + \\" TND\\");\\n    System.out.println(\\"-----------------------------------\\");\\n  }\\n}"}], "label": "2. Validated Solution (Yalla POS receipt)", "activity_id": "act_2", "description": "Formatted header, correct double/int types and HT/TVA/TTC receipt.", "preset_type": "solution"}]	t	2026-11-01 23:14:34.13+00	[{"page": 1, "text": "TP 1 : Introduction à Java et manipulation des variables\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Comprendre la structure d'un programme Java basique et son exécution (Bytecode,\\nJVM).\\n Déclarer, initialiser et manipuler des variables avec les types primitifs (int, double,\\nchar, boolean).\\n Appliquer les opérateurs arithmétiques et effectuer un transtypage (cast) explicite ou\\nimplicite.\\nActivité N°1 (Indépendante) : Opérations arithmétiques et transtypage\\nDans cette activité, nous allons manipuler les types de données numériques et observer le\\ncomportement du compilateur Java lors des conversions.\\n1. Créez une classe Calculatrice contenant la méthode main .\\n2. Déclarez deux variables entières a et b initialisées respectivement à 15 et 2.\\n3. Calculez et affichez le résultat de la division de a par b . Que remarquez-vous ?\\n4. Corrigez le code en utilisant le transtypage (cast) pour obtenir le résultat exact (7.5)\\nstocké dans une variable de type float ou double .\\n5. Déclarez une constante PI (utilisez le mot-clé final ) initialisée à 3.14159. Calculez le\\npérimètre d'un cercle de rayon r = 5.5 et affichez le résultat formaté.\\nActivité N°2 (Projet Fil Rouge) : Initialisation de la caisse \\"Yalla POS\\"\\nNous allons démarrer le développement de notre application fil rouge de point de vente,\\nnommée Yalla POS Console . Pour cette première étape, le système ne possède pas encore\\nde classes complexes ; nous allons concevoir le script d'impression d'un ticket de caisse\\nbasique avec de simples variables.\\nTravail demandé : Créez une classe YallaPOS et, dans sa méthode main , implémentez les\\nétapes suivantes :\\n1. L'en-tête du ticket : Affichez dans la console un message de bienvenue bien formaté\\n(utilisez les séquences d'échappement \\\\n et \\\\t ), par exemple : *** Bienvenue sur\\nYalla POS *** *** Votre terminal d'encaissement ***\\n2. Les données de l'article : Déclarez et initialisez les variables suivantes sans utiliser la\\nlecture au clavier pour le moment (données \\"en dur\\") :\\no Le nom de l'article (ex: \\"Clavier Mécanique\\").\\no Le prix unitaire hors taxe (HT) de type double (ex: 45.50).\\no La quantité achetée de type int (ex: 3).\\no Le taux de TVA de type double (ex: 0.19 pour 19%).\\n3. Les calculs :\\no Calculez le total HT (prix unitaire * quantité).\\no Calculez le montant de la TVA (total HT * taux TVA)."}, {"page": 2, "text": "TP1: Introduction à Java et manipulation des variables Mohamed Belhassen\\no Calculez le total TTC (Total HT + Montant TVA).\\n4. Le rendu final : Affichez un récapitulatif clair simulant l'impression d'un ticket de\\ncaisse :\\nPlaintext\\n-----------------------------------\\nArticle : Clavier Mécanique\\nQuantité : 3\\nPrix Unitaire HT : 45.50 TND\\n-----------------------------------\\nSous-Total HT : 136.50 TND\\nTVA (19%) : 25.935 TND\\nTOTAL A PAYER : 162.435 TND\\n-----------------------------------\\nBilan du TP 1 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Compilation et Exécution : Vous savez créer une classe main et l'exécuter dans\\nvotre environnement de développement.\\n [ ] Variables et Constantes : Vous différenciez l'utilisation de int et double , et savez\\nutiliser le mot-clé final .\\n [ ] Transtypage : Vous savez forcer la conversion d'un type vers un autre pour éviter\\nla perte de précision (division d'entiers).\\n [ ] Projet Yalla POS : La structure de base de calcul d'un ticket de caisse est\\nopérationnelle.\\nLa suite : Pour le moment, notre caisse enregistreuse est totalement statique : les prix et les\\nquantités sont écrits \\"en dur\\" dans le code et on ne gère qu'un seul article. Lors du prochain TP, nous\\nallons rendre ce terminal interactif ! Nous utiliserons la classe Scanner pour permettre au caissier\\nde saisir lui-même les prix au clavier. Mieux encore, grâce aux boucles et aux conditions , nous\\npourrons simuler l'ajout de plusieurs articles à la suite pour construire un véritable panier d'achat, et\\nnous mettrons en place un système pour appliquer automatiquement des remises promotionnelles si\\nle total dépasse un certain montant."}]	{"en": "TP 1 — Lab 1: Introduction to Java and Variable Manipulation", "fr": "TP 1 : Introduction à Java et manipulation des variables"}	{"en": "This lab introduces Java program structure (Bytecode, JVM), primitive variables and explicit/implicit casting, while building the static receipt calculation base for Yalla POS.", "fr": "Ce TP initie à la structure d'un programme Java (Bytecode, JVM), à la manipulation des variables primitives et au transtypage, tout en posant la base statique de calcul du ticket Yalla POS."}	2026-11-02 20:07:42.438083+00
2cef427c-737b-4305-8c58-b402604fac8f	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	4	TP4	TP 4 — Lab 4: Introduction to Object-Oriented Programming (Classes, Objects and Constructors)	Introductory OOP lab that distinguishes classes from objects through a Four-Aliment interaction and implements the Article business entity with constructors for the Yalla POS cash register.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp4.pdf	[{"id": "act_1", "order": 1, "title": "Activity No.1 (Independent): Object Interactions (Four and Aliments)", "milestones": [{"id": "m1_1", "order": 1, "title": "Aliment class with manger() behavior", "title_i18n": {"en": "Aliment class with manger() behavior", "fr": "Classe Aliment avec comportement manger()"}, "validation_criteria": "Class Aliment declares nom (String) and estCuit (boolean) and manger() displays cooked message if estCuit is true, raw message otherwise.", "validation_criteria_i18n": {"en": "Class Aliment declares nom (String) and estCuit (boolean) and manger() displays cooked message if estCuit is true, raw message otherwise.", "fr": "La classe Aliment déclare nom (String) et estCuit (boolean) et manger() affiche le message cuit si estCuit est true, sinon le message cru."}}, {"id": "m1_2", "order": 2, "title": "Four class with cuire(Aliment) interaction", "title_i18n": {"en": "Four class with cuire(Aliment) interaction", "fr": "Classe Four avec interaction cuire(Aliment)"}, "validation_criteria": "Class Four declares puissance and capacite and cuire(Aliment aliment) prints cooking message and sets aliment.estCuit to true.", "validation_criteria_i18n": {"en": "Class Four declares puissance and capacite and cuire(Aliment aliment) prints cooking message and sets aliment.estCuit to true.", "fr": "La classe Four déclare puissance et capacite et cuire(Aliment aliment) affiche le message de cuisson et met aliment.estCuit à true."}}, {"id": "m1_3", "order": 3, "title": "Instantiation in TestFour and state observation", "title_i18n": {"en": "Instantiation in TestFour and state observation", "fr": "Instanciation dans TestFour et observation d'état"}, "validation_criteria": "TestFour.main with new instantiates petitFour, grandFour and cake (Cake aux fruits, false) and chains cake.manger(), grandFour.cuire(cake), cake.manger() showing state change.", "validation_criteria_i18n": {"en": "TestFour.main with new instantiates petitFour, grandFour and cake (Cake aux fruits, false) and chains cake.manger(), grandFour.cuire(cake), cake.manger() showing state change.", "fr": "TestFour.main avec new instancie petitFour, grandFour et cake (Cake aux fruits, false) et enchaîne cake.manger(), grandFour.cuire(cake), cake.manger() en montrant le changement d'état."}}], "title_i18n": {"en": "Activity No.1 (Independent): Object Interactions (Four and Aliments)", "fr": "Activité N°1 (Indépendante) : Interactions entre objets (Le Four et les Aliments)"}, "target_files": ["Aliment.java", "Four.java", "TestFour.java"], "instructions_i18n": {"en": "Scenario: Handle classes and objects by creating two interacting classes where a `Four` cooks `Aliment` objects.\\n\\nImplementation Steps:\\n1. Create the `Aliment` class:\\n   * Add attributes `nom` (`String`) and `estCuit` (`boolean`).\\n   * Add method `manger()` that displays `Miam, [nom] est bien cuit` if `estCuit` is true, otherwise `Beurk, [nom] est cru !`.\\n2. Create the `Four` class:\\n   * Add attributes `puissance` (`int`) and `capacite` (`int`).\\n   * Add method `cuire(Aliment aliment)` that takes an `Aliment` object as parameter, displays `Cuisson de [nom] en cours...` and sets `estCuit` of the aliment to `true`.\\n3. Instantiation with the `TestFour` class:\\n   * Create class `TestFour` containing method `main`.\\n   * Instantiate two different fours (`petitFour` and `grandFour`) with different `puissance` and `capacite`.\\n   * Instantiate one aliment (`cake` with `nom = \\"Cake aux fruits\\"`, `estCuit = false`).\\n   * Call `cake.manger()`, then `grandFour.cuire(cake)`, then again `cake.manger()` to observe the state change of the object in memory.", "fr": "Scénario : Manipuler les concepts de classes et objets en créant deux classes qui interagissent entre elles : un `Four` qui cuit des `Aliment`.\\n\\nÉtapes de réalisation :\\n1. Créer la classe `Aliment` :\\n   * Ajouter les attributs `nom` (`String`) et `estCuit` (`boolean`).\\n   * Ajouter la méthode `manger()` qui affiche `Miam, [nom] est bien cuit` si l'aliment est cuit, ou `Beurk, [nom] est cru !` sinon.\\n2. Créer la classe `Four` :\\n   * Ajouter les attributs `puissance` (`int`) et `capacite` (`int`).\\n   * Créer la méthode `cuire(Aliment aliment)` qui prend un objet `Aliment` en paramètre, affiche `Cuisson de [nom] en cours...` et modifie l'attribut `estCuit` de l'aliment à `true`.\\n3. L'instanciation avec la classe `TestFour` :\\n   * Créer la classe `TestFour` contenant la méthode `main`.\\n   * Instancier deux fours différents (`petitFour` et `grandFour`) avec des `puissance` et `capacite` différentes.\\n   * Instancier un aliment (`cake` avec `nom = \\"Cake aux fruits\\"`, `estCuit = false`).\\n   * Appeler `cake.manger()`, puis `grandFour.cuire(cake)`, et enfin à nouveau `cake.manger()` pour observer le changement d'état de l'objet en mémoire."}, "instructions_markdown": "Scenario: Handle classes and objects by creating two interacting classes where a `Four` cooks `Aliment` objects.\\n\\nImplementation Steps:\\n1. Create the `Aliment` class:\\n   * Add attributes `nom` (`String`) and `estCuit` (`boolean`).\\n   * Add method `manger()` that displays `Miam, [nom] est bien cuit` if `estCuit` is true, otherwise `Beurk, [nom] est cru !`.\\n2. Create the `Four` class:\\n   * Add attributes `puissance` (`int`) and `capacite` (`int`).\\n   * Add method `cuire(Aliment aliment)` that takes an `Aliment` object as parameter, displays `Cuisson de [nom] en cours...` and sets `estCuit` of the aliment to `true`.\\n3. Instantiation with the `TestFour` class:\\n   * Create class `TestFour` containing method `main`.\\n   * Instantiate two different fours (`petitFour` and `grandFour`) with different `puissance` and `capacite`.\\n   * Instantiate one aliment (`cake` with `nom = \\"Cake aux fruits\\"`, `estCuit = false`).\\n   * Call `cake.manger()`, then `grandFour.cuire(cake)`, then again `cake.manger()` to observe the state change of the object in memory."}, {"id": "act_2", "order": 2, "title": "Activity No.2 (Ongoing Project): The Article Entity of Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Article business class with constructor and this", "title_i18n": {"en": "Article business class with constructor and this", "fr": "Classe métier Article avec constructeur et this"}, "validation_criteria": "Article declares designation, prixHT, codeBarre, defines constructor Article(designation, prix, code) using this and method afficherDetails() printing readable format.", "validation_criteria_i18n": {"en": "Article declares designation, prixHT, codeBarre, defines constructor Article(designation, prix, code) using this and method afficherDetails() printing readable format.", "fr": "Article déclare designation, prixHT, codeBarre, définit le constructeur Article(designation, prix, code) avec this et la méthode afficherDetails() affichant le format lisible."}}, {"id": "m2_2", "order": 2, "title": "YallaPOS migration to Article[] panier", "title_i18n": {"en": "YallaPOS migration to Article[] panier", "fr": "Migration YallaPOS vers Article[] panier"}, "validation_criteria": "YallaPOS removes parallel String/double arrays, declares Article[] panier = new Article[MAX_ARTICLES]; reads with Scanner and stores Article nouvelArt = new Article(designation, prix, code) in panier[compteur].", "validation_criteria_i18n": {"en": "YallaPOS removes parallel String/double arrays, declares Article[] panier = new Article[MAX_ARTICLES]; reads with Scanner and stores Article nouvelArt = new Article(designation, prix, code) in panier[compteur].", "fr": "YallaPOS supprime les tableaux parallèles String/double, déclare Article[] panier = new Article[MAX_ARTICLES]; lit avec Scanner et stocke Article nouvelArt = new Article(designation, prix, code) dans panier[compteur]."}}, {"id": "m2_3", "order": 3, "title": "Receipt via panier[i].afficherDetails()", "title_i18n": {"en": "Receipt via panier[i].afficherDetails()", "fr": "Ticket via panier[i].afficherDetails()"}, "validation_criteria": "Receipt printing loop iterates over panier and calls panier[i].afficherDetails() for each Article.", "validation_criteria_i18n": {"en": "Receipt printing loop iterates over panier and calls panier[i].afficherDetails() for each Article.", "fr": "La boucle d'impression du ticket parcourt panier et appelle panier[i].afficherDetails() pour chaque Article."}}], "title_i18n": {"en": "Activity No.2 (Ongoing Project): The Article Entity of Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : L'entité Article de Yalla POS"}, "target_files": ["Article.java", "YallaPOS.java"], "instructions_i18n": {"en": "Scenario: Professionalize the cash register by replacing parallel primitive arrays with a single business class `Article`.\\n\\nImplementation Steps:\\n1. Create the business class `Article`:\\n   * Add attributes `designation` (`String`), `prixHT` (`double`) and `codeBarre` (`String`).\\n   * Create a constructor taking these three values as parameters and assigning them with `this` when parameter names match attributes.\\n   * Add method `afficherDetails()` displaying e.g. `[12345] Clavier Mécanique - 45.50 TND`.\\n2. Update the cash register (`YallaPOS`):\\n   * Remove old `String` and double arrays.\\n   * Declare `Article[] panier = new Article[MAX_ARTICLES];`.\\n   * In the input loop use `Scanner` to read designation, price and barcode.\\n   * Instantiate `Article nouvelArt = new Article(designation, prix, code);` and store it in `panier[compteur]`.\\n3. Final rendering: modify the receipt printing loop to iterate over the object array and call `panier[i].afficherDetails();` for each article.", "fr": "Scénario : Regrouper les caractéristiques d'un produit commercial au sein d'une seule classe métier `Article` pour professionnaliser la caisse.\\n\\nÉtapes de réalisation :\\n1. Créer la classe métier `Article` :\\n   * Ajouter les attributs `designation` (`String`), `prixHT` (`double`) et `codeBarre` (`String`).\\n   * Créer un constructeur qui prend ces trois valeurs en paramètres pour les affecter aux attributs lors de l'instanciation avec le mot-clé `this` si les noms sont identiques.\\n   * Ajouter la méthode `afficherDetails()` qui affiche un format lisible, par exemple : `[12345] Clavier Mécanique - 45.50 TND`.\\n2. Mettre à jour la Caisse (`YallaPOS`) :\\n   * Supprimer les anciens tableaux de `String` et de doubles.\\n   * Déclarer `Article[] panier = new Article[MAX_ARTICLES];`.\\n   * Dans la boucle de saisie, utiliser le `Scanner` pour lire la désignation, le prix et le code-barres.\\n   * Instancier `Article nouvelArt = new Article(designation, prix, code);` et stocker cet objet dans `panier[compteur]`.\\n3. Rendu final : modifier la boucle d'impression du ticket de caisse pour parcourir le tableau d'objets et appeler `panier[i].afficherDetails();` pour chaque article."}, "instructions_markdown": "Scenario: Professionalize the cash register by replacing parallel primitive arrays with a single business class `Article`.\\n\\nImplementation Steps:\\n1. Create the business class `Article`:\\n   * Add attributes `designation` (`String`), `prixHT` (`double`) and `codeBarre` (`String`).\\n   * Create a constructor taking these three values as parameters and assigning them with `this` when parameter names match attributes.\\n   * Add method `afficherDetails()` displaying e.g. `[12345] Clavier Mécanique - 45.50 TND`.\\n2. Update the cash register (`YallaPOS`):\\n   * Remove old `String` and double arrays.\\n   * Declare `Article[] panier = new Article[MAX_ARTICLES];`.\\n   * In the input loop use `Scanner` to read designation, price and barcode.\\n   * Instantiate `Article nouvelArt = new Article(designation, prix, code);` and store it in `panier[compteur]`.\\n3. Final rendering: modify the receipt printing loop to iterate over the object array and call `panier[i].afficherDetails();` for each article."}]	{CLASS_OBJECT_REFERENCES,CONSTRUCTORS_THIS,PRIMITIVE_ARRAY_STRING,SCANNER_KEYBOARD_INPUT}	[{"key": "act_1_buggy", "files": [{"name": "Aliment.java", "content": "public class Aliment {\\n  String nom;\\n  boolean estCuit;\\n  public Aliment(String nom, boolean estCuit) {\\n    nom = nom;\\n    estCuit = estCuit;\\n  }\\n  public void manger() {\\n    System.out.println(\\"Miam, \\" + nom + \\" est bien cuit\\");\\n  }\\n}"}, {"name": "Four.java", "content": "public class Four {\\n  int puissance;\\n  int capacite;\\n  public void cuire(Aliment aliment) {\\n    System.out.println(\\"Cuisson de \\" + aliment.nom + \\" en cours...\\");\\n  }\\n}"}, {"name": "TestFour.java", "content": "public class TestFour {\\n  public static void main(String[] args) {\\n    Four petitFour = new Four();\\n    Four grandFour = new Four();\\n    Aliment cake = new Aliment(\\"Cake aux fruits\\", false);\\n    cake.manger();\\n    grandFour.cuire(cake);\\n    cake.manger();\\n  }\\n}"}], "label": "1. Buggy Four-Aliment (No State Change)", "activity_id": "act_1", "description": "Constructor shadowing without this and manger() ignoring estCuit, cuire() never sets estCuit to true.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Aliment.java", "content": "public class Aliment {\\n  String nom;\\n  boolean estCuit;\\n  public Aliment(String nom, boolean estCuit) {\\n    this.nom = nom;\\n    this.estCuit = estCuit;\\n  }\\n  public void manger() {\\n    if (this.estCuit) {\\n      System.out.println(\\"Miam, \\" + this.nom + \\" est bien cuit\\");\\n    } else {\\n      System.out.println(\\"Beurk, \\" + this.nom + \\" est cru !\\");\\n    }\\n  }\\n}"}, {"name": "Four.java", "content": "public class Four {\\n  int puissance;\\n  int capacite;\\n  public void cuire(Aliment aliment) {\\n    System.out.println(\\"Cuisson de \\" + aliment.nom + \\" en cours...\\");\\n    aliment.estCuit = true;\\n  }\\n}"}, {"name": "TestFour.java", "content": "public class TestFour {\\n  public static void main(String[] args) {\\n    Four petitFour = new Four();\\n    petitFour.puissance = 800;\\n    petitFour.capacite = 20;\\n    Four grandFour = new Four();\\n    grandFour.puissance = 2000;\\n    grandFour.capacite = 60;\\n    Aliment cake = new Aliment(\\"Cake aux fruits\\", false);\\n    cake.manger();\\n    grandFour.cuire(cake);\\n    cake.manger();\\n  }\\n}"}], "label": "2. Validated Solution (Four Cooks Aliment)", "activity_id": "act_1", "description": "Clean interaction where Four.cuire() flips estCuit and manger() reflects state.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Article.java", "content": "public class Article {\\n  String designation;\\n  double prixHT;\\n  String codeBarre;\\n}"}, {"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  static final int MAX_ARTICLES = 10;\\n  public static void main(String[] args) {\\n    Scanner sc = new Scanner(System.in);\\n    String[] noms = new String[MAX_ARTICLES];\\n    double[] prix = new double[MAX_ARTICLES];\\n    int compteur = 0;\\n    System.out.print(\\"Designation: \\");\\n    noms[compteur] = sc.nextLine();\\n    System.out.print(\\"Prix: \\");\\n    prix[compteur] = sc.nextDouble();\\n    compteur++;\\n    for (int i = 0; i < compteur; i++) {\\n      System.out.println(noms[i] + \\" - \\" + prix[i]);\\n    }\\n  }\\n}"}], "label": "1. Buggy Article (Parallel Arrays Kept)", "activity_id": "act_2", "description": "Article without parameterized constructor and YallaPOS still using parallel primitive arrays.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Article.java", "content": "public class Article {\\n  String designation;\\n  double prixHT;\\n  String codeBarre;\\n  public Article(String designation, double prixHT, String codeBarre) {\\n    this.designation = designation;\\n    this.prixHT = prixHT;\\n    this.codeBarre = codeBarre;\\n  }\\n  public void afficherDetails() {\\n    System.out.println(\\"[\\" + this.codeBarre + \\"] \\" + this.designation + \\" - \\" + this.prixHT + \\" TND\\");\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  static final int MAX_ARTICLES = 10;\\n  public static void main(String[] args) {\\n    Scanner sc = new Scanner(System.in);\\n    Article[] panier = new Article[MAX_ARTICLES];\\n    int compteur = 0;\\n    System.out.print(\\"Designation: \\");\\n    String designation = sc.nextLine();\\n    System.out.print(\\"Prix: \\");\\n    double prix = sc.nextDouble();\\n    sc.nextLine();\\n    System.out.print(\\"Code-barres: \\");\\n    String code = sc.nextLine();\\n    Article nouvelArt = new Article(designation, prix, code);\\n    panier[compteur] = nouvelArt;\\n    compteur++;\\n    for (int i = 0; i < compteur; i++) {\\n      panier[i].afficherDetails();\\n    }\\n  }\\n}"}], "label": "2. Validated Solution (Article Entity)", "activity_id": "act_2", "description": "Business class with this-constructor and YallaPOS using Article[] panier and afficherDetails().", "preset_type": "solution"}]	t	2026-11-01 23:15:55.572+00	[{"page": 1, "text": "TP 4 : Introduction à la Programmation Orientée Objet (Classes, Objets et\\nConstructeurs)\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Comprendre la différence fondamentale entre une classe (le concept/modèle) et un\\nobjet (l'instance en mémoire).\\n Créer une classe en définissant ses données membres (attributs) et ses\\ncomportements (méthodes).\\n Instancier des objets à l'aide de l'opérateur new .\\n Définir et utiliser des constructeurs pour initialiser les ressources de l'objet dès sa\\ncréation.\\nActivité N°1 (Indépendante) : Interactions entre objets (Le Four et les Aliments)\\nDans cette activité, nous allons manipuler les concepts vus en cours en créant deux classes\\nqui interagissent entre elles : un four qui cuit des aliments.\\n1. La classe Aliment :\\no Créez une classe Aliment avec deux attributs : nom (String) et estCuit\\n(boolean).\\no Ajoutez une méthode manger() qui affiche \\"Miam, [nom] est bien cuit\\" si\\nl'aliment est cuit, ou \\"Beurk, [nom] est cru !\\" sinon.\\n2. La classe Four :\\no Créez une classe Four avec deux attributs : puissance (int) et capacite (int).\\no Créez une méthode cuire(Aliment aliment) qui prend un objet Aliment\\nen paramètre. Cette méthode doit afficher \\"Cuisson de [nom] en cours...\\" et\\nmodifier l'attribut estCuit de l'aliment à true .\\n3. L'instanciation (La classe Test) :\\no Créez une classe TestFour contenant la méthode main .\\no Instanciez deux fours différents (ex: petitFour et grandFour ) et affectez-leur\\ndes puissances et capacités différentes.\\no Instanciez un aliment (ex: cake avec nom = \\"Cake aux fruits\\" , estCuit =\\nfalse ).\\no Appelez cake.manger() , puis grandFour.cuire(cake) , et enfin à nouveau\\ncake.manger() pour observer le changement d'état de l'objet en mémoire.\\nActivité N°2 (Projet Fil Rouge) : L'entité Article de Yalla POS\\nFini les tableaux \\"parallèles\\" (un tableau pour les noms, un autre pour les prix) ! Nous allons\\nregrouper les caractéristiques d'un produit commercial au sein d'une seule et unique classe\\nmétier. Le code de notre point de vente va devenir beaucoup plus professionnel.\\nTravail demandé :"}, {"page": 2, "text": "TP 4 : Introduction à la Programmation Orientée Objet Mohamed Belhassen\\n1. Création de la classe métier :\\no Créez une nouvelle classe Article .\\no Ajoutez-lui les attributs suivants : designation (String), prixHT (double) et\\ncodeBarre (String).\\no Créez un constructeur qui prend ces trois valeurs en paramètres pour les\\naffecter aux attributs de la classe lors de l'instanciation (rappel : si le nom des\\nparamètres est identique à celui des attributs, n'oubliez pas d'utiliser le mot-\\nclé this ).\\no Ajoutez une méthode afficherDetails() dans la classe Article qui affiche\\ndans la console un format lisible, par exemple : [12345] Clavier\\nMécanique - 45.50 TND .\\n2. Mise à jour de la Caisse (YallaPOS) :\\no Dans votre classe YallaPOS , supprimez vos anciens tableaux de String et de\\ndoubles.\\no Déclarez et allouez un seul tableau capable de contenir vos objets :\\nArticle[] panier = new Article[MAX_ARTICLES]; .\\no Dans la boucle de saisie, utilisez le Scanner pour lire la désignation, le prix et\\nle code-barres.\\no Instanciez le nouvel article : Article nouvelArt = new\\nArticle(designation, prix, code); .\\no Stockez cet objet dans votre panier[compteur] .\\n3. Le rendu final : Modifiez la boucle d'impression de votre ticket de caisse pour qu'elle\\nparcoure le tableau d'objets et appelle tout simplement la méthode\\npanier[i].afficherDetails(); pour chaque article.\\nBilan du TP 4 : Ce qu'il faut retenir\\nÀ la fin de ce TP, vous devez avoir validé les points suivants :\\n [ ] Classes vs Objets : Vous ne confondez plus la description du type (la classe) avec\\nson utilisation concrète en mémoire (l'objet).\\n [ ] Constructeurs : Vous savez initialiser l'état d'un objet (ses variables) dès l'appel du\\nnew en lui passant des paramètres.\\n [ ] Méthodes : Vos objets ne sont plus de simples boîtes de rangement de données ;\\nils embarquent leurs propres actions (comme cuire() ou afficherDetails() ).\\n [ ] Yalla POS : Votre système de caisse est devenu beaucoup plus modulaire.\\nManipuler un tableau d'objets Article est bien plus pratique que de gérer de\\nmultiples tableaux primitifs.\\nLa suite : Actuellement, rien n'empêche un caissier de contourner le constructeur et de\\nmodifier manuellement le prix d'un article en écrivant directement monArticle.prixHT =\\n-50; dans le code. C'est une faille de sécurité majeure pour un logiciel de caisse ! Lors du\\nprochain TP, nous allons verrouiller l'accès direct à nos données avec l' encapsulation (la\\nvisibilité private , les méthodes Getters et Setters ). Nous en profiterons également pour\\nexplorer plus en profondeur l'utilité du mot-clé this et la surcharge de méthodes."}]	{"en": "TP 4 — Lab 4: Introduction to Object-Oriented Programming (Classes, Objects and Constructors)", "fr": "TP 4 : Introduction à la Programmation Orientée Objet (Classes, Objets et Constructeurs)"}	{"en": "Introductory OOP lab that distinguishes classes from objects through a Four-Aliment interaction and implements the Article business entity with constructors for the Yalla POS cash register.", "fr": "TP d'introduction à la POO qui distingue classes et objets via l'interaction Four-Aliments et implémente l'entité métier Article avec constructeurs pour la caisse Yalla POS."}	2026-11-02 20:07:42.438083+00
55555555-5555-5555-5555-555555555555	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	5	TP5	TP 5 — Lab 5: Encapsulation, Self-Reference (this) and Overloading	This lab teaches encapsulation with private visibility and guarded getters/setters, self-reference with this, and method/constructor overloading to secure Four and the Yalla POS Article.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp5.pdf	[{"id": "act_1", "order": 1, "title": "Activity No.1 (Independent): Four Access Control", "milestones": [{"id": "m1_1", "order": 1, "title": "Private visibility of all Four attributes", "title_i18n": {"en": "Private visibility of all Four attributes", "fr": "Visibilité private de tous les attributs de Four"}, "validation_criteria": "Attributes `puissance`, `capacite`, `resistance` and `soufflerie` in `Four` are explicitly declared with `private`; direct access `monFour.resistance = null;` no longer compiles.", "validation_criteria_i18n": {"en": "Attributes `puissance`, `capacite`, `resistance` and `soufflerie` in `Four` are explicitly declared with `private`; direct access `monFour.resistance = null;` no longer compiles.", "fr": "Les attributs `puissance`, `capacite`, `resistance` et `soufflerie` de `Four` sont déclarés explicitement avec `private` ; l'accès direct `monFour.resistance = null;` ne compile plus."}}, {"id": "m1_2", "order": 2, "title": "Read Getters for puissance and capacite", "title_i18n": {"en": "Read Getters for puissance and capacite", "fr": "Getters de lecture pour puissance et capacite"}, "validation_criteria": "Getters return the current value of `puissance` and `capacite` and allow external reading without direct field access.", "validation_criteria_i18n": {"en": "Getters return the current value of `puissance` and `capacite` and allow external reading without direct field access.", "fr": "Les Getters retournent la valeur courante de `puissance` et `capacite` et permettent la lecture externe sans accès direct aux champs."}}, {"id": "m1_3", "order": 3, "title": "Guarded Setter for Soufflerie", "title_i18n": {"en": "Guarded Setter for Soufflerie", "fr": "Setter sécurisé pour la Soufflerie"}, "validation_criteria": "`setSoufflerie(Soufflerie s)` checks with `if` that `s` is not `null` (or uses `instanceof`) before assigning `this.soufflerie`.", "validation_criteria_i18n": {"en": "`setSoufflerie(Soufflerie s)` checks with `if` that `s` is not `null` (or uses `instanceof`) before assigning `this.soufflerie`.", "fr": "`setSoufflerie(Soufflerie s)` vérifie avec un `if` que `s` n'est pas `null` (ou utilise `instanceof`) avant d'affecter `this.soufflerie`."}}], "title_i18n": {"en": "Activity No.1 (Independent): Four Access Control", "fr": "Activité N°1 (Indépendante) : Le contrôle d'accès du Four"}, "target_files": ["Four.java", "Resistance.java", "Soufflerie.java"], "instructions_i18n": {"en": "Secure the internal mechanics of the oven against fraudulent external manipulation.\\n\\n**Implementation Steps:**\\n1. Retrieve or recreate the `Four` class from the previous lab.\\n2. Create two empty classes `Resistance` and `Soufflerie` to model internal components.\\n3. Add them as attributes in `Four` (`Resistance resistance;`, `Soufflerie soufflerie;`) alongside `puissance` and `capacite`.\\n4. Apply encapsulation: change the visibility of all attributes (`puissance`, `capacite`, `resistance`, `soufflerie`) to `private` to forbid `monFour.resistance = null;` from outside.\\n5. Generate `Getters` returning the value for `puissance` and `capacite`, and create `setSoufflerie(Soufflerie s)` with an `if` check (`s != null` or `instanceof`) before assignment.", "fr": "Protéger la mécanique interne du four contre les manipulations frauduleuses depuis l'extérieur.\\n\\n**Étapes de réalisation :**\\n1. Reprenez (ou recréez) la classe `Four` du TP précédent.\\n2. Créez deux classes vides `Resistance` et `Soufflerie` pour modéliser les composants internes.\\n3. Ajoutez-les comme attributs dans `Four` (`Resistance resistance;`, `Soufflerie soufflerie;`) avec `puissance` et `capacite`.\\n4. Appliquez l'encapsulation : passez tous les attributs (`puissance`, `capacite`, `resistance`, `soufflerie`) en `private` pour interdire `monFour.resistance = null;` depuis l'extérieur.\\n5. Générez les `Getters` pour lire `puissance` et `capacite`, et créez `setSoufflerie(Soufflerie s)` avec un contrôle `if` (`s != null` ou `instanceof`) avant modification."}, "instructions_markdown": "Secure the internal mechanics of the oven against fraudulent external manipulation.\\n\\n**Implementation Steps:**\\n1. Retrieve or recreate the `Four` class from the previous lab.\\n2. Create two empty classes `Resistance` and `Soufflerie` to model internal components.\\n3. Add them as attributes in `Four` (`Resistance resistance;`, `Soufflerie soufflerie;`) alongside `puissance` and `capacite`.\\n4. Apply encapsulation: change the visibility of all attributes (`puissance`, `capacite`, `resistance`, `soufflerie`) to `private` to forbid `monFour.resistance = null;` from outside.\\n5. Generate `Getters` returning the value for `puissance` and `capacite`, and create `setSoufflerie(Soufflerie s)` with an `if` check (`s != null` or `instanceof`) before assignment."}, {"id": "act_2", "order": 2, "title": "Activity No.2 (Capstone Project): Securing Article and Overloading in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Encapsulation of Article with business-rule setter", "title_i18n": {"en": "Encapsulation of Article with business-rule setter", "fr": "Encapsulation d'Article avec setter métier"}, "validation_criteria": "`designation`, `prixHT`, `codeBarre` are `private` with getters; `setPrixHT(double nouveauPrix)` refuses strictly negative values with message `\\"Erreur : Le prix ne peut pas être négatif !\\"` without changing the field.", "validation_criteria_i18n": {"en": "`designation`, `prixHT`, `codeBarre` are `private` with getters; `setPrixHT(double nouveauPrix)` refuses strictly negative values with message `\\"Erreur : Le prix ne peut pas être négatif !\\"` without changing the field.", "fr": "`designation`, `prixHT`, `codeBarre` sont `private` avec getters ; `setPrixHT(double nouveauPrix)` refuse les valeurs strictement négatives avec le message `\\"Erreur : Le prix ne peut pas être négatif !\\"` sans modifier le champ."}}, {"id": "m2_2", "order": 2, "title": "Self-reference this and constructor overloading", "title_i18n": {"en": "Self-reference this and constructor overloading", "fr": "Autoréférence this et surcharge du constructeur"}, "validation_criteria": "Constructor and setters use `this.prixHT` to resolve shadowing; second constructor delegates via `this(designation, prixHT, \\"000000\\")` for default barcode `\\"000000\\"`.", "validation_criteria_i18n": {"en": "Constructor and setters use `this.prixHT` to resolve shadowing; second constructor delegates via `this(designation, prixHT, \\"000000\\")` for default barcode `\\"000000\\"`.", "fr": "Le constructeur et les setters utilisent `this.prixHT` pour lever l'ambiguïté ; le second constructeur délègue via `this(designation, prixHT, \\"000000\\")` pour le code-barres par défaut `\\"000000\\"`."}}, {"id": "m2_3", "order": 3, "title": "YallaPOS update to controlled access", "title_i18n": {"en": "YallaPOS update to controlled access", "fr": "Mise à jour de YallaPOS vers l'accès contrôlé"}, "validation_criteria": "`YallaPOS` no longer uses `panier[0].prixHT` (compilation error) but `panier[0].getPrixHT()`; negative-price test via setter leaves price unchanged.", "validation_criteria_i18n": {"en": "`YallaPOS` no longer uses `panier[0].prixHT` (compilation error) but `panier[0].getPrixHT()`; negative-price test via setter leaves price unchanged.", "fr": "`YallaPOS` n'utilise plus `panier[0].prixHT` (erreur de compilation) mais `panier[0].getPrixHT()` ; le test de prix négatif via le setter laisse le prix inchangé."}}], "title_i18n": {"en": "Activity No.2 (Capstone Project): Securing Article and Overloading in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : Sécurisation de l'Article et Surcharge dans Yalla POS"}, "target_files": ["Article.java", "YallaPOS.java"], "instructions_i18n": {"en": "Secure the cash register by encapsulating `Article` and offering multiple construction modes via overloading.\\n\\n**Implementation Steps:**\\n1. Encapsulate data: pass `designation`, `prixHT` and `codeBarre` of `Article` to `private`, generate `Getters` for the three attributes.\\n2. Generate `setPrixHT(double nouveauPrix)` with strict business rule: if `nouveauPrix < 0`, print `\\"Erreur : Le prix ne peut pas être négatif !\\"` and do not modify `this.prixHT`.\\n3. Master `this`: use `this.prixHT` to distinguish the field from the `prixHT` parameter in constructor and setters.\\n4. Overload the constructor: create a second constructor `Article(designation, prixHT)` that delegates with `this(\\"designation\\", prixHT, \\"000000\\")` to handle items without barcode.\\n5. Update `YallaPOS`: replace forbidden `panier[0].prixHT` with `panier[0].getPrixHT()` and test `setPrixHT()` with a negative value.", "fr": "Sécuriser la caisse enregistreuse en encapsulant `Article` et en offrant plusieurs modes de construction par surcharge.\\n\\n**Étapes de réalisation :**\\n1. Encapsulation des données : passez `designation`, `prixHT` et `codeBarre` de `Article` en `private`, générez les `Getters` pour ces trois attributs.\\n2. Générez `setPrixHT(double nouveauPrix)` avec règle métier stricte : si `nouveauPrix < 0`, affichez `\\"Erreur : Le prix ne peut pas être négatif !\\"` et ne modifiez pas `this.prixHT`.\\n3. Maîtrisez `this` : utilisez `this.prixHT` pour différencier l'attribut du paramètre `prixHT` dans le constructeur et les setters.\\n4. Surchargez le constructeur : créez un deuxième constructeur `Article(designation, prixHT)` qui délègue avec `this(\\"designation\\", prixHT, \\"000000\\")` pour les articles sans code-barres.\\n5. Mettez à jour `YallaPOS` : remplacez l'accès interdit `panier[0].prixHT` par `panier[0].getPrixHT()` et testez `setPrixHT()` avec une valeur négative."}, "instructions_markdown": "Secure the cash register by encapsulating `Article` and offering multiple construction modes via overloading.\\n\\n**Implementation Steps:**\\n1. Encapsulate data: pass `designation`, `prixHT` and `codeBarre` of `Article` to `private`, generate `Getters` for the three attributes.\\n2. Generate `setPrixHT(double nouveauPrix)` with strict business rule: if `nouveauPrix < 0`, print `\\"Erreur : Le prix ne peut pas être négatif !\\"` and do not modify `this.prixHT`.\\n3. Master `this`: use `this.prixHT` to distinguish the field from the `prixHT` parameter in constructor and setters.\\n4. Overload the constructor: create a second constructor `Article(designation, prixHT)` that delegates with `this(\\"designation\\", prixHT, \\"000000\\")` to handle items without barcode.\\n5. Update `YallaPOS`: replace forbidden `panier[0].prixHT` with `panier[0].getPrixHT()` and test `setPrixHT()` with a negative value."}]	{VISIBILITY_ENCAPSULATION,CONSTRUCTORS_THIS,CLASS_OBJECT_REFERENCES,METHOD_CONSTRUCTOR_OVERLOADING}	[{"key": "act_1_buggy", "files": [{"name": "Four.java", "content": "public class Four {\\n  int puissance;\\n  int capacite;\\n  Resistance resistance;\\n  Soufflerie soufflerie;\\n\\n  public Four(int puissance, int capacite) {\\n    puissance = puissance;\\n    capacite = capacite;\\n    resistance = new Resistance();\\n    soufflerie = new Soufflerie();\\n  }\\n\\n  public int getPuissance() { return puissance; }\\n\\n  public void setSoufflerie(Soufflerie s) {\\n    soufflerie = s;\\n  }\\n}"}, {"name": "Resistance.java", "content": "public class Resistance {\\n}"}, {"name": "Soufflerie.java", "content": "public class Soufflerie {\\n}"}], "label": "1. Buggy Four (Public Fields, No Guard)", "activity_id": "act_1", "description": "Four exposes public/default fields and setter without null check; shadowing without this breaks initialization.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Four.java", "content": "public class Four {\\n  private int puissance;\\n  private int capacite;\\n  private Resistance resistance;\\n  private Soufflerie soufflerie;\\n\\n  public Four(int puissance, int capacite) {\\n    this.puissance = puissance;\\n    this.capacite = capacite;\\n    this.resistance = new Resistance();\\n    this.soufflerie = new Soufflerie();\\n  }\\n\\n  public int getPuissance() { return this.puissance; }\\n  public int getCapacite() { return this.capacite; }\\n  public Resistance getResistance() { return this.resistance; }\\n  public Soufflerie getSoufflerie() { return this.soufflerie; }\\n\\n  public void setSoufflerie(Soufflerie s) {\\n    if (s == null) return;\\n    if (!(s instanceof Soufflerie)) return;\\n    this.soufflerie = s;\\n  }\\n}"}, {"name": "Resistance.java", "content": "public class Resistance {\\n}"}, {"name": "Soufflerie.java", "content": "public class Soufflerie {\\n}"}], "label": "2. Validated Solution (Encapsulated Four)", "activity_id": "act_1", "description": "Fully encapsulated Four with private fields, getters and null-checked setter using this.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Article.java", "content": "public class Article {\\n  public String designation;\\n  public double prixHT;\\n  public String codeBarre;\\n\\n  public Article(String designation, double prixHT, String codeBarre) {\\n    designation = designation;\\n    prixHT = prixHT;\\n    codeBarre = codeBarre;\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article[] panier = new Article[1];\\n    panier[0] = new Article(\\"Lait\\", 1.5, \\"123456\\");\\n    System.out.println(panier[0].prixHT);\\n    panier[0].prixHT = -10.0;\\n    System.out.println(panier[0].prixHT);\\n  }\\n}"}], "label": "1. Buggy Article (Public Price, No Overloading)", "activity_id": "act_2", "description": "Article leaves fields public, constructor shadows without this, and YallaPOS corrupts price directly.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Article.java", "content": "public class Article {\\n  private String designation;\\n  private double prixHT;\\n  private String codeBarre;\\n\\n  public Article(String designation, double prixHT, String codeBarre) {\\n    this.designation = designation;\\n    this.prixHT = prixHT;\\n    this.codeBarre = codeBarre;\\n  }\\n\\n  public Article(String designation, double prixHT) {\\n    this(designation, prixHT, \\"000000\\");\\n  }\\n\\n  public String getDesignation() { return this.designation; }\\n  public double getPrixHT() { return this.prixHT; }\\n  public String getCodeBarre() { return this.codeBarre; }\\n\\n  public void setPrixHT(double prixHT) {\\n    if (prixHT < 0) {\\n      System.out.println(\\"Erreur : Le prix ne peut pas etre negatif !\\");\\n      return;\\n    }\\n    this.prixHT = prixHT;\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article[] panier = new Article[2];\\n    panier[0] = new Article(\\"Lait\\", 1.5, \\"123456\\");\\n    panier[1] = new Article(\\"Pomme\\", 0.8);\\n    System.out.println(panier[0].getPrixHT());\\n    System.out.println(panier[1].getCodeBarre());\\n    panier[0].setPrixHT(-10.0);\\n    System.out.println(panier[0].getPrixHT());\\n  }\\n}"}], "label": "2. Validated Solution (Secure Article + Overloading)", "activity_id": "act_2", "description": "Secure Article with private fields, guarded setter, this disambiguation and overloaded constructor.", "preset_type": "solution"}]	t	2026-11-01 23:16:22.551+00	[{"page": 1, "text": "TP 5 : Encapsulation, Autoréférence ( this ) et Surcharge\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Protéger l'état interne d'un objet en utilisant le modificateur de visibilité private .\\n Créer et utiliser des accesseurs ( Getters ) et des mutateurs ( Setters ) pour contrôler\\nl'accès et la modification des données.\\n Utiliser le mot-clé this pour lever les ambiguïtés entre variables locales et attributs,\\nou pour faire appel à un autre constructeur de la même classe.\\n Mettre en œuvre la surcharge (overloading) des méthodes et des constructeurs.\\nActivité N°1 (Indépendante) : Le contrôle d'accès du Four\\nDans cette activité, nous allons reprendre l'exemple du four vu en cours pour comprendre\\nl'importance de masquer la mécanique interne d'un objet à ses utilisateurs.\\n1. Reprenez (ou recréez) la classe Four du TP précédent.\\n2. Imaginez que notre four possède des composants internes : créez deux classes vides\\nResistance et Soufflerie .\\n3. Ajoutez ces composants comme attributs de la classe Four ( Resistance\\nresistance; , Soufflerie soufflerie; ).\\n4. Le danger : Si ces attributs sont publics (par défaut), n'importe qui peut écrire\\nmonFour.resistance = null; depuis l'extérieur, ce qui casserait la logique interne\\ndu four !\\n5. La solution (Encapsulation) :\\no Modifiez la visibilité de tous les attributs de la classe Four (puissance,\\ncapacite, resistance, soufflerie) en ajoutant le mot-clé private devant leur\\ndéclaration.\\no Générez les méthodes Getters (qui retournent une copie de la valeur) pour\\nque l'on puisse lire la puissance et la capacité depuis l'extérieur.\\no Créez un Setter pour la Soufflerie ( public void\\nsetSoufflerie(Soufflerie s) ) et ajoutez-y un contrôle (une condition if )\\npour vérifier que l'objet passé en paramètre n'est pas null (ou utilisez\\ninstanceof ) avant de modifier l'attribut.\\nActivité N°2 (Projet Fil Rouge) : Sécurisation de l'Article et Surcharge dans Yalla POS\\nNotre caisse enregistreuse possède une faille critique : les attributs de la classe Article sont\\naccessibles directement. Un caissier malveillant (ou maladroit) pourrait modifier le prix de\\nn'importe quel article dans le panier ! Nous allons corriger cela.\\nTravail demandé :\\n1. Encapsulation des données :\\no Ouvrez votre classe Article et passez les attributs designation , prixHT et\\ncodeBarre en private ."}, {"page": 2, "text": "TP 5 : Encapsulation, Autoréférence (this) et Surcharge Mohamed Belhassen\\no Générez les Getters pour ces trois attributs.\\no Générez le Setter pour le prixHT . À l'intérieur de ce setPrixHT(double\\nnouveauPrix) , ajoutez une règle métier stricte : si le nouveauPrix est\\nstrictement inférieur à 0, affichez un message d'erreur (\\"Erreur : Le prix ne\\npeut pas être négatif !\\") et ne modifiez pas la valeur de l'attribut.\\n2. Maîtrise du mot-clé this :\\no Dans vos Setters et dans votre constructeur, vérifiez que vous utilisez bien le\\nmot-clé this pour différencier l'attribut de la classe ( this.prixHT ) du\\nparamètre de la méthode ( prixHT ).\\n3. La Surcharge du Constructeur :\\no Tous les articles n'ont pas forcément un code-barres lors de leur création (par\\nexemple, un fruit pesé en vrac).\\no Surchargez le constructeur en créant un deuxième constructeur dans la classe\\nArticle qui ne prend que la designation et le prixHT en paramètres.\\no Dans ce nouveau constructeur, utilisez this(\\"designation\\", prixHT,\\n\\"000000\\"); pour faire appel au premier constructeur en lui passant un code-\\nbarres par défaut (\\"000000\\").\\n4. Mise à jour de la caisse :\\no Dans la classe YallaPOS , essayez de lire le prix d'un article en écrivant\\npanier[0].prixHT . Le compilateur doit vous indiquer une erreur (accès\\ninterdit) ! Remplacez cet appel par panier[0].getPrixHT() .\\no Testez le fonctionnement de votre caisse et essayez de modifier le prix d'un\\narticle via le Setter avec une valeur négative pour vérifier que votre sécurité\\nfonctionne.\\nBilan du TP 5 : Ce qu'il faut retenir\\nÀ la fin de ce TP, vous devez avoir validé les points suivants :\\n [ ] Visibilité : Vous savez pourquoi il faut déclarer les attributs en private pour\\nempêcher les manipulations frauduleuses de l'extérieur.\\n [ ] Getters/Setters : Vous savez donner un accès contrôlé en lecture ( Getter ) et en\\nécriture ( Setter , avec vérification) aux données de votre objet.\\n [ ] Autoréférence : Le mot-clé this n'a plus de secret pour vous, que ce soit pour\\ndésigner l'instance courante ou appeler un autre constructeur.\\n [ ] Yalla POS : Votre classe Article est désormais robuste, sécurisée, et propose\\nplusieurs façons d'être instanciée grâce à la surcharge.\\nLa suite : Notre système de caisse gère désormais parfaitement des articles standards.\\nCependant, un supermarché vend une multitude de produits très différents : des produits\\npérissables (qui ont une date d'expiration), des appareils électroniques (qui ont une durée\\nde garantie), etc. Va-t-on devoir créer une classe complètement différente pour chaque type\\nde produit et modifier tout le code de notre caisse ? Non ! Lors du prochain TP, nous\\naborderons l'un des piliers de la Programmation Orientée Objet : l'Héritage . Nous allons\\napprendre à créer des classes dérivées qui vont hériter automatiquement de toutes les\\ncaractéristiques de notre Article de base, tout en ajoutant leurs propres spécificités."}]	{"en": "TP 5 — Lab 5: Encapsulation, Self-Reference (this) and Overloading", "fr": "TP 5 : Encapsulation, Autoréférence ( this ) et Surcharge"}	{"en": "This lab teaches encapsulation with private visibility and guarded getters/setters, self-reference with this, and method/constructor overloading to secure Four and the Yalla POS Article.", "fr": "Ce TP enseigne l'encapsulation avec visibilité private et getters/setters contrôlés, l'autoreférence avec this et la surcharge des méthodes et constructeurs pour sécuriser le Four et l'Article de Yalla POS."}	2026-11-02 20:07:42.438083+00
87a47267-6870-4313-8f2c-6f94ef2cabe8	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	2	TP2	TP 2 — Lab 2: Control Structures and User Interaction	This lab teaches console interaction with Scanner, conditional branching with if and switch, and iterative control with while/do...while and break to build an interactive dispenser and the Yalla POS basket with discount and VAT.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp2.pdf	[{"id": "act_1", "order": 1, "title": "Activity No. 1 (Independent): The drinks dispenser (switch and do..while)", "milestones": [{"id": "m1_1", "order": 1, "title": "Scanner initialization and do...while menu", "title_i18n": {"en": "Scanner initialization and do...while menu", "fr": "Initialisation Scanner et menu en do...while"}, "validation_criteria": "Scanner clavier is initialized on System.in and menu is displayed at least once inside a do...while loop reading choix as int.", "validation_criteria_i18n": {"en": "Scanner clavier is initialized on System.in and menu is displayed at least once inside a do...while loop reading choix as int.", "fr": "Scanner clavier est initialisé sur System.in et le menu s'affiche au moins une fois dans une boucle do...while lisant choix en entier."}}, {"id": "m1_2", "order": 2, "title": "Switch handling of drink choices", "title_i18n": {"en": "Switch handling of drink choices", "fr": "Traitement des choix par switch"}, "validation_criteria": "switch on choix handles cases 1, 2, 3 with preparation messages and case 0, each terminated by break.", "validation_criteria_i18n": {"en": "switch on choix handles cases 1, 2, 3 with preparation messages and case 0, each terminated by break.", "fr": "Le switch sur choix traite les cas 1, 2, 3 avec messages de préparation et le cas 0, chacun terminé par break."}}, {"id": "m1_3", "order": 3, "title": "Default case and exit on 0", "title_i18n": {"en": "Default case and exit on 0", "fr": "Cas default et sortie sur 0"}, "validation_criteria": "default displays \\"Choix invalide !\\" and the while condition stops the loop only when choix equals 0.", "validation_criteria_i18n": {"en": "default displays \\"Choix invalide !\\" and the while condition stops the loop only when choix equals 0.", "fr": "Le default affiche \\"Choix invalide !\\" et la condition du while arrête la boucle uniquement lorsque choix vaut 0."}}], "title_i18n": {"en": "Activity No. 1 (Independent): The drinks dispenser (switch and do..while)", "fr": "Activité N°1 (Indépendante) : Le distributeur de boissons (switch et do..while)"}, "target_files": ["Distributeur.java"], "instructions_i18n": {"en": "Scenario: Build an interactive drinks dispenser that guarantees at least one menu display.\\n\\n**Implementation Steps:**\\n1. Create the class `Distributeur` and initialize keyboard input with `Scanner clavier = new Scanner(System.in);`.\\n2. Use a `do...while` loop to display the menu (1. Café 1.5 TND, 2. Thé 1.0 TND, 3. Jus 2.5 TND, 0. Quitter) and read the integer `choix` with `nextInt()`.\\n3. Use a `switch` on `choix` to display preparation messages (e.g. `\\"Préparation de votre Café...\\"`), handle `case 0` for quitting, and use `default` to display `\\"Choix invalide !\\"`.\\n4. Terminate the loop with the `while` condition `choix != 0` and control flow with `break` where needed.", "fr": "Scénario : Créer un distributeur de boissons interactif garantissant au moins un affichage du menu.\\n\\n**Étapes de réalisation :**\\n1. Créez la classe `Distributeur` et initialisez la lecture clavier avec `Scanner clavier = new Scanner(System.in);`.\\n2. Utilisez une boucle `do...while` pour afficher le menu (1. Café 1.5 TND, 2. Thé 1.0 TND, 3. Jus 2.5 TND, 0. Quitter) et lire le `choix` entier saisi avec `nextInt()`.\\n3. Utilisez une structure `switch` sur `choix` pour afficher un message de préparation selon la boisson (ex : `\\"Préparation de votre Café...\\"`), gérez le `case 0` pour quitter et le cas `default` pour afficher `\\"Choix invalide !\\"`.\\n4. Arrêtez la boucle avec la condition du `while` `choix != 0` et contrôlez le flux avec `break`."}, "instructions_markdown": "Scenario: Build an interactive drinks dispenser that guarantees at least one menu display.\\n\\n**Implementation Steps:**\\n1. Create the class `Distributeur` and initialize keyboard input with `Scanner clavier = new Scanner(System.in);`.\\n2. Use a `do...while` loop to display the menu (1. Café 1.5 TND, 2. Thé 1.0 TND, 3. Jus 2.5 TND, 0. Quitter) and read the integer `choix` with `nextInt()`.\\n3. Use a `switch` on `choix` to display preparation messages (e.g. `\\"Préparation de votre Café...\\"`), handle `case 0` for quitting, and use `default` to display `\\"Choix invalide !\\"`.\\n4. Terminate the loop with the `while` condition `choix != 0` and control flow with `break` where needed."}, {"id": "act_2", "order": 2, "title": "Activity No. 2 (Red Thread Project): The interactive Yalla POS shopping basket", "milestones": [{"id": "m2_1", "order": 1, "title": "Basket input loop with break", "title_i18n": {"en": "Basket input loop with break", "fr": "Boucle de saisie du panier avec break"}, "validation_criteria": "while loop accumulates prices into totalHT and uses break to exit when entered price is 0 or negative.", "validation_criteria_i18n": {"en": "while loop accumulates prices into totalHT and uses break to exit when entered price is 0 or negative.", "fr": "La boucle while accumule les prix dans totalHT et utilise break pour sortir quand le prix saisi est 0 ou négatif."}}, {"id": "m2_2", "order": 2, "title": "Conditional 10% promotion", "title_i18n": {"en": "Conditional 10% promotion", "fr": "Promotion conditionnelle de 10%"}, "validation_criteria": "if (totalHT > 200) applies 10% discount on totalHT and displays \\"*** Remise de 10% appliquée ! ***\\".", "validation_criteria_i18n": {"en": "if (totalHT > 200) applies 10% discount on totalHT and displays \\"*** Remise de 10% appliquée ! ***\\".", "fr": "Le if (totalHT > 200) applique une remise de 10% sur totalHT et affiche \\"*** Remise de 10% appliquée ! ***\\"."}}, {"id": "m2_3", "order": 3, "title": "Final ticket with TVA and TTC", "title_i18n": {"en": "Final ticket with TVA and TTC", "fr": "Ticket final avec TVA et TTC"}, "validation_criteria": "TVA at 19% on discounted totalHT and TTC total are computed and final recap is printed.", "validation_criteria_i18n": {"en": "TVA at 19% on discounted totalHT and TTC total are computed and final recap is printed.", "fr": "La TVA à 19% sur le totalHT remisé et le total TTC sont calculés et le récapitulatif final est affiché."}}], "title_i18n": {"en": "Activity No. 2 (Red Thread Project): The interactive Yalla POS shopping basket", "fr": "Activité N°2 (Projet Fil Rouge) : Le panier d'achat interactif de Yalla POS"}, "target_files": ["YallaPOS.java"], "instructions_i18n": {"en": "Scenario: Transform `YallaPOS` into a real cash register processing a basket of several items.\\n\\n**Implementation Steps:**\\n1. In class `YallaPOS`, declare accumulation variables `double totalHT = 0;` and a `Scanner` for reading prices.\\n2. Use a `while` (or `do...while`) input loop to ask for the HT price of an article; if price is `0` or negative use `break` to end basket entry, otherwise add price to `totalHT`.\\n3. After the loop, use an `if` to check if `totalHT` exceeds `200` TND, apply a 10% discount and display `\\"*** Remise de 10% appliquée ! ***\\"`.\\n4. Compute 19% `TVA`, compute TTC total and display the clear final payment summary.", "fr": "Scénario : Transformer `YallaPOS` en véritable caisse enregistreuse traitant un panier de plusieurs articles.\\n\\n**Étapes de réalisation :**\\n1. Dans la classe `YallaPOS`, déclarez les variables d'accumulation `double totalHT = 0;` ainsi qu'un objet `Scanner` pour lire les prix.\\n2. Utilisez une boucle `while` (ou `do...while`) pour demander indéfiniment le prix HT d'un article ; si le prix saisi est égal à `0` (ou négatif) utilisez l'instruction `break` pour sortir de la boucle, sinon ajoutez le prix à `totalHT`.\\n3. Une fois sorti de la boucle, vérifiez avec un `if` si `totalHT` dépasse `200` TND, appliquez une remise de 10% et affichez `\\"*** Remise de 10% appliquée ! ***\\"`.\\n4. Calculez la `TVA` à 19% sur le total HT remisé, calculez le total TTC et affichez le récapitulatif clair du paiement final."}, "instructions_markdown": "Scenario: Transform `YallaPOS` into a real cash register processing a basket of several items.\\n\\n**Implementation Steps:**\\n1. In class `YallaPOS`, declare accumulation variables `double totalHT = 0;` and a `Scanner` for reading prices.\\n2. Use a `while` (or `do...while`) input loop to ask for the HT price of an article; if price is `0` or negative use `break` to end basket entry, otherwise add price to `totalHT`.\\n3. After the loop, use an `if` to check if `totalHT` exceeds `200` TND, apply a 10% discount and display `\\"*** Remise de 10% appliquée ! ***\\"`.\\n4. Compute 19% `TVA`, compute TTC total and display the clear final payment summary."}]	{SCANNER_CONSOLE_INPUT,SWITCH_SELECTION,IF_ELSE_CONDITIONALS,WHILE_DO_WHILE_LOOPS,CONTROL_FLOW_BREAK}	[{"key": "act_1_buggy", "files": [{"name": "Distributeur.java", "content": "import java.util.Scanner;\\npublic class Distributeur {\\n  public static void main(String[] args) {\\n    Scanner clavier = new Scanner(System.in);\\n    int choix;\\n    do {\\n      System.out.println(\\"1. Cafe (1.5 TND)\\");\\n      System.out.println(\\"2. The (1.0 TND)\\");\\n      System.out.println(\\"3. Jus (2.5 TND)\\");\\n      System.out.println(\\"0. Quitter\\");\\n      System.out.print(\\"Votre choix : \\");\\n      choix = clavier.nextInt();\\n      switch (choix) {\\n        case 1:\\n          System.out.println(\\"Preparation de votre Cafe...\\");\\n        case 2:\\n          System.out.println(\\"Preparation de votre The...\\");\\n        case 3:\\n          System.out.println(\\"Preparation de votre Jus...\\");\\n        case 0:\\n          System.out.println(\\"Au revoir !\\");\\n      }\\n    } while (choix != 1);\\n  }\\n}"}], "label": "1. Buggy Dispenser (Fallthrough + Wrong Exit)", "activity_id": "act_1", "description": "Missing break causes fallthrough, no default case, and wrong while exit condition.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "Distributeur.java", "content": "import java.util.Scanner;\\npublic class Distributeur {\\n  public static void main(String[] args) {\\n    Scanner clavier = new Scanner(System.in);\\n    int choix;\\n    do {\\n      System.out.println(\\"1. Cafe (1.5 TND)\\");\\n      System.out.println(\\"2. The (1.0 TND)\\");\\n      System.out.println(\\"3. Jus (2.5 TND)\\");\\n      System.out.println(\\"0. Quitter\\");\\n      System.out.print(\\"Votre choix : \\");\\n      choix = clavier.nextInt();\\n      switch (choix) {\\n        case 1:\\n          System.out.println(\\"Preparation de votre Cafe...\\");\\n          break;\\n        case 2:\\n          System.out.println(\\"Preparation de votre The...\\");\\n          break;\\n        case 3:\\n          System.out.println(\\"Preparation de votre Jus...\\");\\n          break;\\n        case 0:\\n          System.out.println(\\"Au revoir !\\");\\n          break;\\n        default:\\n          System.out.println(\\"Choix invalide !\\");\\n          break;\\n      }\\n    } while (choix != 0);\\n    clavier.close();\\n  }\\n}"}], "label": "2. Validated Solution (Dispenser Menu)", "activity_id": "act_1", "description": "Correct do...while menu with switch, breaks, default and exit on 0.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void main(String[] args) {\\n    double totalHT = 0;\\n    Scanner clavier = new Scanner(System.in);\\n    while (true) {\\n      System.out.print(\\"Prix HT article (0 pour terminer) : \\");\\n      double prix = clavier.nextDouble();\\n      if (prix <= 0) {\\n        System.out.println(\\"Fin saisie\\");\\n      }\\n      totalHT = totalHT + prix;\\n    }\\n  }\\n}"}], "label": "1. Buggy Basket (No Break, No Discount)", "activity_id": "act_2", "description": "Loop never breaks, discount is flat value and TVA computed without /100.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void main(String[] args) {\\n    double totalHT = 0;\\n    Scanner clavier = new Scanner(System.in);\\n    while (true) {\\n      System.out.print(\\"Prix HT article (0 pour terminer) : \\");\\n      double prix = clavier.nextDouble();\\n      if (prix <= 0) {\\n        break;\\n      }\\n      totalHT = totalHT + prix;\\n    }\\n    if (totalHT > 200) {\\n      totalHT = totalHT * 0.9;\\n      System.out.println(\\"*** Remise de 10% appliquee ! ***\\");\\n    }\\n    double tva = totalHT * 0.19;\\n    double totalTTC = totalHT + tva;\\n    System.out.println(\\"Total HT : \\" + totalHT + \\" TND\\");\\n    System.out.println(\\"TVA (19%) : \\" + tva + \\" TND\\");\\n    System.out.println(\\"Total TTC : \\" + totalTTC + \\" TND\\");\\n    clavier.close();\\n  }\\n}"}], "label": "2. Validated Solution (Interactive Basket)", "activity_id": "act_2", "description": "Correct while+break basket, 10% discount over 200 TND, 19% TVA and TTC ticket.", "preset_type": "solution"}]	t	2026-11-01 23:14:56.472+00	[{"page": 1, "text": "TP 2 : Les structures de contrôle et interaction utilisateur\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Interagir avec l'utilisateur pour lire des données au clavier à l'aide de la classe\\nScanner .\\n Maîtriser et choisir les structures conditionnelles adéquates ( if...else , switch ).\\n Mettre en œuvre les structures itératives (boucles for , while , do...while ) pour\\nrépéter des traitements.\\n Contrôler le flux d'exécution d'une boucle (utilisation du mot-clé break ).\\nActivité N°1 (Indépendante) : Le distributeur de boissons (switch et do..while)\\nDans cette activité, nous allons manipuler la boucle do...while (qui garantit au moins une\\nexécution) combinée à un switch pour créer un menu interactif.\\n1. Créez une nouvelle classe Distributeur .\\n2. Importez et initialisez un objet Scanner pour lire les entrées du clavier : Scanner\\nclavier = new Scanner(System.in); .\\n3. Utilisez une boucle do...while pour afficher un menu à l'utilisateur jusqu'à ce qu'il\\nchoisisse de quitter :\\n1. Café (1.5 TND)\\n2. Thé (1.0 TND)\\n3. Jus (2.5 TND)\\n0. Quitter\\nVotre choix :\\n4. Lisez le choix (entier) saisi par l'utilisateur.\\n5. Utilisez une structure switch pour traiter le choix. Affichez un message de\\npréparation selon la boisson choisie (ex: \\"Préparation de votre Café...\\").\\n6. Gérez le cas par défaut ( default ) pour afficher \\"Choix invalide !\\" si l'utilisateur saisit\\nun nombre hors du menu.\\n7. La boucle doit s'arrêter (condition du while ) lorsque l'utilisateur saisit 0 .\\nActivité N°2 (Projet Fil Rouge) : Le panier d'achat interactif de Yalla POS\\nFini les variables \\"en dur\\" ! Nous allons transformer \\"Yalla POS Console\\" en une véritable\\ncaisse enregistreuse capable de traiter le panier d'un client contenant plusieurs articles.\\nTravail demandé : Dans votre classe YallaPOS , remplacez le code du TP précédent par la\\nlogique suivante :\\n1. Initialisation : Déclarez les variables nécessaires pour accumuler le montant total\\n( double totalHT = 0; ), ainsi qu'un objet Scanner pour lire les prix.\\n2. La boucle de saisie (Le Panier) :"}, {"page": 2, "text": "TP 2 : Les structures de contrôle et interaction utilisateur Mohamed Belhassen\\no Utilisez une boucle while (ou do...while ) pour demander indéfiniment au\\ncaissier de saisir le prix HT d'un article.\\no Si le caissier saisit un prix égal à 0 (ou négatif), utilisez l'instruction break pour\\nsortir de la boucle (cela signifie que la saisie du panier est terminée).\\no Sinon, ajoutez le prix saisi au totalHT .\\n3. L'application de la promotion (Les conditions) :\\no Une fois sorti de la boucle, vérifiez si le totalHT dépasse 200 TND (utilisez un\\nif ).\\no Si c'est le cas, appliquez une remise de 10% sur le montant HT et affichez un\\nmessage de félicitations au client : \\"*** Remise de 10% appliquée !\\n***\\" .\\n4. Le ticket final :\\no Calculez la TVA (ex: 19% sur le total HT remisé).\\no Calculez le total TTC.\\no Affichez le récapitulatif clair du paiement final à l'écran.\\nBilan du TP 2 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Interaction : Vous savez lire des données dynamiques depuis la console avec\\nScanner .\\n [ ] Choix de la boucle : Vous savez quand utiliser un do...while (comme pour un\\nmenu) et quand utiliser un while classique.\\n [ ] Branchements : Vous maîtrisez le switch pour des choix multiples et le if pour\\ndes conditions logiques (comme la remise).\\n [ ] Yalla POS : Votre caisse peut maintenant traiter une infinité d'articles à la suite et\\nappliquer des règles métier simples (remise).\\nLa suite : Pour le moment, notre système calcule très bien la somme totale, mais nous avons\\nun gros problème : une fois la boucle terminée, la caisse a \\"oublié\\" tous les prix individuels\\nsaisis ! Impossible d'imprimer un ticket détaillé listant chaque article. Lors du prochain TP,\\nnous allons utiliser les Tableaux (Arrays) et la classe String pour mémoriser les noms et les\\nprix de tous les articles du panier au fur et à mesure, ce qui nous permettra de générer un\\nvéritable ticket de caisse professionnel complet !"}]	{"en": "TP 2 — Lab 2: Control Structures and User Interaction", "fr": "TP 2 : Les structures de contrôle et interaction utilisateur"}	{"en": "This lab teaches console interaction with Scanner, conditional branching with if and switch, and iterative control with while/do...while and break to build an interactive dispenser and the Yalla POS basket with discount and VAT.", "fr": "Ce TP apprend l'interaction console avec Scanner, les branchements conditionnels avec if et switch, et le contrôle itératif avec while/do...while et break pour réaliser un distributeur interactif et le panier Yalla POS avec remise et TVA."}	2026-11-02 20:07:42.438083+00
346e59a2-f53c-4cef-a735-2db6e2047601	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	12	TP12	TP 12 — Lab 12: Custom Exceptions and Project Finalization	This lab teaches how to create custom checked exceptions with throw and throws and applies them to secure the final Yalla POS checkout against invalid payments.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp12.pdf	[{"id": "act_1", "order": 1, "title": "Activity 1 (Independent): Input control and custom-made exception", "milestones": [{"id": "m1_1", "order": 1, "title": "Creation of SaisieErroneeException inheriting from Exception", "title_i18n": {"en": "Creation of SaisieErroneeException inheriting from Exception", "fr": "Création de SaisieErroneeException héritant d'Exception"}, "validation_criteria": "Class `SaisieErroneeException` declares `extends Exception` and its constructor `SaisieErroneeException(String message)` calls `super(message)`.", "validation_criteria_i18n": {"en": "Class `SaisieErroneeException` declares `extends Exception` and its constructor `SaisieErroneeException(String message)` calls `super(message)`.", "fr": "La classe `SaisieErroneeException` déclare `extends Exception` et son constructeur `SaisieErroneeException(String message)` appelle `super(message)`."}}, {"id": "m1_2", "order": 2, "title": "Control method with throws and throw", "title_i18n": {"en": "Control method with throws and throw", "fr": "Méthode de contrôle avec throws et throw"}, "validation_criteria": "Method `controle(String chaine)` declares `throws SaisieErroneeException` and executes `throw new SaisieErroneeException(...)` when `chaine.equals(\\"\\")` is true.", "validation_criteria_i18n": {"en": "Method `controle(String chaine)` declares `throws SaisieErroneeException` and executes `throw new SaisieErroneeException(...)` when `chaine.equals(\\"\\")` is true.", "fr": "La méthode `controle(String chaine)` déclare `throws SaisieErroneeException` et exécute `throw new SaisieErroneeException(...)` quand `chaine.equals(\\"\\")` est vrai."}}, {"id": "m1_3", "order": 3, "title": "Final test with try/catch in main", "title_i18n": {"en": "Final test with try/catch in main", "fr": "Test final avec try/catch dans main"}, "validation_criteria": "`main` calls `controle(\\"\\")` inside `try`, catches `catch (SaisieErroneeException e)` and prints `e.getMessage()` via `System.out.println`.", "validation_criteria_i18n": {"en": "`main` calls `controle(\\"\\")` inside `try`, catches `catch (SaisieErroneeException e)` and prints `e.getMessage()` via `System.out.println`.", "fr": "`main` appelle `controle(\\"\\")` dans un `try`, capture `catch (SaisieErroneeException e)` et affiche `e.getMessage()` via `System.out.println`."}}], "title_i18n": {"en": "Activity 1 (Independent): Input control and custom-made exception", "fr": "Activité N°1 (Indépendante) : Contrôle de saisie et exception sur-mesure"}, "target_files": ["SaisieErroneeException.java", "TestSaisieErroneeException.java"], "instructions_i18n": {"en": "Reproduce the course example by creating a custom exception to reject an empty input.\\n\\n**Implementation Steps:**\\n1. Create the exception class:\\n   - Create `SaisieErroneeException` extending `Exception` via `extends Exception`.\\n   - Create a constructor `SaisieErroneeException(String message)` calling `super(message)`.\\n2. Create the control method:\\n   - In `TestSaisieErroneeException`, create `controle(String chaine)` with clause `throws SaisieErroneeException`.\\n   - If `chaine.equals(\\"\\")` is true, trigger `throw new SaisieErroneeException(\\"Saisie erronée : chaîne vide\\")`.\\n3. Final test:\\n   - In `main`, call `controle(\\"\\")` inside `try`.\\n   - Catch with `catch (SaisieErroneeException e)` and display `e.getMessage()` with `System.out.println(e.getMessage())`.", "fr": "Reproduisez l'exemple du cours en créant une exception sur-mesure pour rejeter une saisie vide.\\n\\n**Étapes de réalisation :**\\n1. Création de la classe d'exception :\\n   - Créez `SaisieErroneeException` héritant de `Exception` via `extends Exception`.\\n   - Créez un constructeur `SaisieErroneeException(String message)` appelant `super(message)`.\\n2. La méthode de contrôle (`throws` et `throw`) :\\n   - Dans `TestSaisieErroneeException`, créez `controle(String chaine)` avec la clause `throws SaisieErroneeException`.\\n   - Si `chaine.equals(\\"\\")` est vrai, déclenchez `throw new SaisieErroneeException(\\"Saisie erronée : chaîne vide\\")`.\\n3. Le test final :\\n   - Dans `main`, appelez `controle(\\"\\")` à l'intérieur d'un bloc `try`.\\n   - Capturez avec `catch (SaisieErroneeException e)` et affichez `e.getMessage()` avec `System.out.println(e.getMessage())`."}, "instructions_markdown": "Reproduce the course example by creating a custom exception to reject an empty input.\\n\\n**Implementation Steps:**\\n1. Create the exception class:\\n   - Create `SaisieErroneeException` extending `Exception` via `extends Exception`.\\n   - Create a constructor `SaisieErroneeException(String message)` calling `super(message)`.\\n2. Create the control method:\\n   - In `TestSaisieErroneeException`, create `controle(String chaine)` with clause `throws SaisieErroneeException`.\\n   - If `chaine.equals(\\"\\")` is true, trigger `throw new SaisieErroneeException(\\"Saisie erronée : chaîne vide\\")`.\\n3. Final test:\\n   - In `main`, call `controle(\\"\\")` inside `try`.\\n   - Catch with `catch (SaisieErroneeException e)` and display `e.getMessage()` with `System.out.println(e.getMessage())`."}, {"id": "act_2", "order": 2, "title": "Activity 2 (Ongoing Project): Securing payment in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Business exception PaiementInvalideException", "title_i18n": {"en": "Business exception PaiementInvalideException", "fr": "Exception métier PaiementInvalideException"}, "validation_criteria": "Class `PaiementInvalideException` declares `extends Exception` with a constructor `PaiementInvalideException(String message)` calling `super(message)`.", "validation_criteria_i18n": {"en": "Class `PaiementInvalideException` declares `extends Exception` with a constructor `PaiementInvalideException(String message)` calling `super(message)`.", "fr": "La classe `PaiementInvalideException` déclare `extends Exception` avec un constructeur `PaiementInvalideException(String message)` appelant `super(message)`."}}, {"id": "m2_2", "order": 2, "title": "validerPaiement method with business rule", "title_i18n": {"en": "validerPaiement method with business rule", "fr": "Méthode validerPaiement avec règle métier"}, "validation_criteria": "Method `validerPaiement(double montantDonne, double totalTTC)` declares `throws PaiementInvalideException`, throws `throw new PaiementInvalideException(...)` if `montantDonne < totalTTC`, otherwise prints change `(montantDonne - totalTTC)`.", "validation_criteria_i18n": {"en": "Method `validerPaiement(double montantDonne, double totalTTC)` declares `throws PaiementInvalideException`, throws `throw new PaiementInvalideException(...)` if `montantDonne < totalTTC`, otherwise prints change `(montantDonne - totalTTC)`.", "fr": "La méthode `validerPaiement(double montantDonne, double totalTTC)` déclare `throws PaiementInvalideException`, lance `throw new PaiementInvalideException(...)` si `montantDonne < totalTTC`, sinon affiche la monnaie `(montantDonne - totalTTC)`."}}, {"id": "m2_3", "order": 3, "title": "Robust collection with try/catch and retry loop", "title_i18n": {"en": "Robust collection with try/catch and retry loop", "fr": "Encaissement robuste avec try/catch et boucle de ressaisie"}, "validation_criteria": "`main` in `YallaPOS` wraps `validerPaiement(...)` in `try/catch (PaiementInvalideException e)`, displays `e.getMessage()` and loops until a valid amount is entered.", "validation_criteria_i18n": {"en": "`main` in `YallaPOS` wraps `validerPaiement(...)` in `try/catch (PaiementInvalideException e)`, displays `e.getMessage()` and loops until a valid amount is entered.", "fr": "`main` dans `YallaPOS` entoure `validerPaiement(...)` avec `try/catch (PaiementInvalideException e)`, affiche `e.getMessage()` et boucle jusqu'à la saisie d'un montant valide."}}], "title_i18n": {"en": "Activity 2 (Ongoing Project): Securing payment in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : Sécurisation du paiement dans Yalla POS"}, "target_files": ["PaiementInvalideException.java", "YallaPOS.java"], "instructions_i18n": {"en": "Secure the Yalla POS checkout with a strict business rule: the cashier cannot validate if the amount given is less than the total including tax.\\n\\n**Implementation Steps:**\\n1. The business exception:\\n   - Create `PaiementInvalideException` inheriting from `Exception` via `extends Exception`.\\n   - Add a constructor `PaiementInvalideException(String message)` forwarding to `super(message)`.\\n2. Integration in the cash register:\\n   - In `YallaPOS`, after printing the ticket and total `totalTTC`, ask for \\"Montant donné par le client\\".\\n   - Create `validerPaiement(double montantDonne, double totalTTC)` with `throws PaiementInvalideException`.\\n   - If `montantDonne < totalTTC`, trigger `throw new PaiementInvalideException(\\"Paiement refusé : Il manque \\" + (totalTTC - montantDonne) + \\" TND !\\")`, otherwise display success and change to return.\\n3. Handling the collection:\\n   - In `main`, wrap `validerPaiement(...)` in `try/catch`.\\n   - On `catch (PaiementInvalideException e)`, display the message and loop to force re-entry until the transaction succeeds.", "fr": "Sécurisez l'encaissement Yalla POS avec une règle métier stricte : le caissier ne peut pas valider si la somme versée est inférieure au total TTC.\\n\\n**Étapes de réalisation :**\\n1. L'Exception Métier :\\n   - Créez `PaiementInvalideException` héritant de `Exception` via `extends Exception`.\\n   - Ajoutez un constructeur `PaiementInvalideException(String message)` transmettant à `super(message)`.\\n2. L'intégration dans la Caisse :\\n   - Dans `YallaPOS`, après l'impression du ticket et le calcul du `totalTTC`, demandez le \\"Montant donné par le client\\".\\n   - Créez `validerPaiement(double montantDonne, double totalTTC)` avec `throws PaiementInvalideException`.\\n   - Si `montantDonne < totalTTC`, déclenchez `throw new PaiementInvalideException(\\"Paiement refusé : Il manque \\" + (totalTTC - montantDonne) + \\" TND !\\")`, sinon affichez le succès et la monnaie à rendre.\\n3. La gestion de l'encaissement :\\n   - Dans `main`, entourez `validerPaiement(...)` avec `try/catch`.\\n   - En cas de `catch (PaiementInvalideException e)`, affichez le message et utilisez une boucle pour forcer la ressaisie jusqu'au succès."}, "instructions_markdown": "Secure the Yalla POS checkout with a strict business rule: the cashier cannot validate if the amount given is less than the total including tax.\\n\\n**Implementation Steps:**\\n1. The business exception:\\n   - Create `PaiementInvalideException` inheriting from `Exception` via `extends Exception`.\\n   - Add a constructor `PaiementInvalideException(String message)` forwarding to `super(message)`.\\n2. Integration in the cash register:\\n   - In `YallaPOS`, after printing the ticket and total `totalTTC`, ask for \\"Montant donné par le client\\".\\n   - Create `validerPaiement(double montantDonne, double totalTTC)` with `throws PaiementInvalideException`.\\n   - If `montantDonne < totalTTC`, trigger `throw new PaiementInvalideException(\\"Paiement refusé : Il manque \\" + (totalTTC - montantDonne) + \\" TND !\\")`, otherwise display success and change to return.\\n3. Handling the collection:\\n   - In `main`, wrap `validerPaiement(...)` in `try/catch`.\\n   - On `catch (PaiementInvalideException e)`, display the message and loop to force re-entry until the transaction succeeds."}]	{THROWABLE_HIERARCHY,THROW_THROWS_CUSTOM,TRY_CATCH_FINALLY_ORDER,SUPER_ACCESS_CHAINING}	[{"key": "act_1_buggy", "files": [{"name": "SaisieErroneeException.java", "content": "public class SaisieErroneeException extends Exception {\\n  private String message;\\n  public SaisieErroneeException(String message) {\\n    this.message = message;\\n  }\\n}"}, {"name": "TestSaisieErroneeException.java", "content": "public class TestSaisieErroneeException {\\n  public static void controle(String chaine) {\\n    if (chaine == \\"\\") {\\n      System.out.println(\\"Saisie erronee\\");\\n    }\\n  }\\n  public static void main(String[] args) {\\n    controle(\\"\\");\\n    System.out.println(\\"Fin controle\\");\\n  }\\n}"}], "label": "1. Buggy Input Control (No super/throws)", "activity_id": "act_1", "description": "Forgets super(message), uses == instead of equals and misses throws/try-catch.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "SaisieErroneeException.java", "content": "public class SaisieErroneeException extends Exception {\\n  public SaisieErroneeException(String message) {\\n    super(message);\\n  }\\n}"}, {"name": "TestSaisieErroneeException.java", "content": "public class TestSaisieErroneeException {\\n  public static void controle(String chaine) throws SaisieErroneeException {\\n    if (chaine.equals(\\"\\")) {\\n      throw new SaisieErroneeException(\\"Saisie erronee : chaine vide\\");\\n    }\\n    System.out.println(\\"Saisie valide : \\" + chaine);\\n  }\\n  public static void main(String[] args) {\\n    try {\\n      controle(\\"\\");\\n    } catch (SaisieErroneeException e) {\\n      System.out.println(e.getMessage());\\n    }\\n  }\\n}"}], "label": "2. Validated Solution (Custom Input Exception)", "activity_id": "act_1", "description": "Complete custom checked exception with throws, throw and try-catch validation.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "PaiementInvalideException.java", "content": "public class PaiementInvalideException extends Exception {\\n  public PaiementInvalideException(String message) {\\n    super(message);\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void validerPaiement(double montantDonne, double totalTTC) {\\n    if (montantDonne < totalTTC) {\\n      System.out.println(\\"Paiement refuse\\");\\n    } else {\\n      System.out.println(\\"Paiement accepte, monnaie : \\" + (montantDonne - totalTTC) + \\" TND\\");\\n    }\\n  }\\n  public static void main(String[] args) {\\n    Scanner sc = new Scanner(System.in);\\n    double totalTTC = 119.0;\\n    System.out.print(\\"Montant donne par le client : \\");\\n    double montantDonne = sc.nextDouble();\\n    validerPaiement(montantDonne, totalTTC);\\n  }\\n}"}], "label": "1. Buggy Payment (No throw/throws)", "activity_id": "act_2", "description": "Business rule not enforced with throw; payment accepted even if insufficient.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "PaiementInvalideException.java", "content": "public class PaiementInvalideException extends Exception {\\n  public PaiementInvalideException(String message) {\\n    super(message);\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "import java.util.Scanner;\\npublic class YallaPOS {\\n  public static void validerPaiement(double montantDonne, double totalTTC) throws PaiementInvalideException {\\n    if (montantDonne < totalTTC) {\\n      throw new PaiementInvalideException(\\"Paiement refuse : Il manque \\" + (totalTTC - montantDonne) + \\" TND !\\");\\n    }\\n    System.out.println(\\"Paiement accepte, monnaie a rendre : \\" + (montantDonne - totalTTC) + \\" TND\\");\\n  }\\n  public static void main(String[] args) {\\n    Scanner sc = new Scanner(System.in);\\n    double totalTTC = 119.0;\\n    boolean paye = false;\\n    while (!paye) {\\n      try {\\n        System.out.print(\\"Montant donne par le client : \\");\\n        double montantDonne = sc.nextDouble();\\n        validerPaiement(montantDonne, totalTTC);\\n        paye = true;\\n      } catch (PaiementInvalideException e) {\\n        System.out.println(e.getMessage());\\n      }\\n    }\\n    sc.close();\\n  }\\n}"}], "label": "2. Validated Solution (Secure Yalla POS Payment)", "activity_id": "act_2", "description": "Strict business rule with throw, throws and retry loop until valid payment.", "preset_type": "solution"}]	t	2026-11-01 22:20:42.749+00	[{"page": 1, "text": "TP 12 : Exceptions personnalisées et Finalisation du Projet\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Créer ses propres classes d'exceptions personnalisées en héritant de la classe\\nException (pour les exceptions contrôlées).\\n Déclencher (lever) manuellement une exception à l'aide du mot-clé throw .\\n Propager une exception vers la méthode appelante en utilisant la clause throws dans\\nla déclaration (l'en-tête) de la méthode.\\nActivité N°1 (Indépendante) : Contrôle de saisie et exception sur-mesure\\nDans cette activité, nous allons reproduire l'exemple du cours en créant une exception qui\\nn'existe pas dans le langage Java de base, afin de rejeter une saisie vide.\\n1. Création de la classe d'exception :\\no Créez une nouvelle classe nommée SaisieErroneeException (par\\nconvention, il est préférable d'inclure le mot \\"Exception\\" à la fin du nom).\\no Faites en sorte qu'elle hérite de la classe parente : extends Exception .\\no Créez un constructeur prenant un String message en paramètre et appelez\\nle constructeur de la classe mère avec super(message); .\\n2. La méthode de contrôle ( throws et throw ) :\\no Créez une classe TestSaisieErroneeException avec une méthode statique\\ncontrole(String chaine) .\\no Dans l'en-tête de cette méthode, ajoutez la clause throws\\nSaisieErroneeException pour prévenir le compilateur que cette méthode\\npeut propager cette erreur.\\no Dans le corps de la méthode, vérifiez si la chaîne est vide\\n( chaine.equals(\\"\\") ). Si c'est le cas, déclenchez l'erreur en écrivant : throw\\nnew SaisieErroneeException(\\"Saisie erronée : chaîne vide\\"); .\\n3. Le test final :\\no Dans votre main , appelez controle(\\"\\") à l'intérieur d'un bloc try .\\no Capturez l'exception avec un bloc catch (SaisieErroneeException e) et\\naffichez le message d'erreur avec System.out.println(e.getMessage());\\npour valider le fonctionnement.\\nActivité N°2 (Projet Fil Rouge) : Sécurisation du paiement dans Yalla POS\\nNotre caisse Yalla POS génère un ticket parfait, mais au moment de payer, rien ne vérifie si le\\nclient donne assez d'argent ! Nous allons créer une \\"règle métier\\" stricte : le caissier ne peut\\npas valider une transaction si la somme versée est inférieure au total TTC.\\nTravail demandé :\\n1. L'Exception Métier :\\no Créez une classe PaiementInvalideException qui hérite de Exception ."}, {"page": 2, "text": "TP 12 : Exceptions personnalisées et Finalisation du Projet Mohamed Belhassen\\no Ajoutez un constructeur permettant de transmettre un message d'erreur\\npersonnalisé à la classe mère.\\n2. L'intégration dans la Caisse :\\no Dans YallaPOS , après l'impression du ticket et le calcul du Total TTC, ajoutez\\nune logique pour demander au caissier de saisir le \\"Montant donné par le\\nclient\\".\\no Créez une méthode (en dehors du main, par exemple public static void\\nvaliderPaiement(double montantDonne, double totalTTC) throws\\nPaiementInvalideException ).\\no Dans cette méthode, si montantDonne < totalTTC , déclenchez l'alerte :\\nthrow new PaiementInvalideException(\\"Paiement refusé : Il\\nmanque \\" + (totalTTC - montantDonne) + \\" TND !\\"); .\\no Sinon, affichez un message de succès calculant la monnaie à rendre.\\n3. La gestion de l'encaissement :\\no Dans votre main , entourez l'appel à validerPaiement(...) avec un\\ntry/catch .\\no Si le paiement échoue, capturez PaiementInvalideException , affichez le\\nmessage rouge, et utilisez une boucle pour forcer le caissier à ressaisir un\\nmontant valide jusqu'à ce que la transaction réussisse.\\nBilan du TP 12 : Ce qu'il faut retenir\\nÀ la fin de ce TP, vous devez avoir validé les points suivants :\\n [ ] Exceptions Personnalisées : Vous savez créer des erreurs sur-mesure ( extends\\nException ) pour représenter des violations de règles métier propres à votre\\napplication.\\n [ ] L'instruction throw : Vous savez instancier et \\"lancer\\" activement une exception\\npour stopper le code dès qu'une condition anormale est détectée.\\n [ ] La clause throws : Vous savez déclarer la possibilité d'une erreur dans l'en-tête\\nd'une méthode, forçant ainsi le développeur qui l'utilise à la gérer (exception\\ncontrôlée).\\n [ ] Yalla POS (Version Finale) : Votre système de caisse est désormais complet,\\ninteractif, structuré en objets (héritage, interfaces), et totalement robuste face aux\\nerreurs de saisie et de logique commerciale.\\nConclusion du Semestre :\\nFélicitations ! En 12 TPs, vous êtes passés de la simple déclaration de variables à la conception d'un\\nvéritable système de point de vente modulaire et sécurisé. L'application Yalla POS Console regroupe\\ndésormais l'intégralité des concepts fondamentaux de la Programmation Orientée Objet (Classes,\\nEncapsulation, Héritage, Polymorphisme, Interfaces et Exceptions). Vous avez désormais toutes les\\nclés en main pour passer à l'étape suivante de votre formation de développeur : la création\\nd'interfaces graphiques interactives (applications de bureau ou mobiles) et la persistance de vos\\ninformations grâce aux bases de données !"}]	{"en": "TP 12 — Lab 12: Custom Exceptions and Project Finalization", "fr": "TP 12 : Exceptions personnalisées et Finalisation du Projet"}	{"en": "This lab teaches how to create custom checked exceptions with throw and throws and applies them to secure the final Yalla POS checkout against invalid payments.", "fr": "Ce TP apprend à créer des exceptions contrôlées sur-mesure avec throw et throws et les applique pour sécuriser l'encaissement final de Yalla POS contre les paiements invalides."}	2026-11-02 20:07:42.438083+00
891df143-8566-4eb0-a4d7-2135c7294442	aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa	6	TP6	TP 6 — Lab 6: Class Members (static) and Constants (final)	This lab teaches the difference between instance and class members with static and immutable constants with final, centralizing VAT rules and global article statistics in Yalla POS.	https://peddvhsykuglvicfaezr.supabase.co/storage/v1/object/public/course-pdfs/java_oop/labs/tp6.pdf	[{"id": "act_1", "order": 1, "title": "Activity 1 (Independent): Mathematical toolbox and Instance counter", "milestones": [{"id": "m1_1", "order": 1, "title": "Static instance counter in ClasseChien", "title_i18n": {"en": "Static instance counter in ClasseChien", "fr": "Compteur d'instances statique dans ClasseChien"}, "validation_criteria": "ClasseChien declares static int count = 0, increments it in the constructor, and ClasseChien.count equals 3 after creating v1, v2, v3.", "validation_criteria_i18n": {"en": "ClasseChien declares static int count = 0, increments it in the constructor, and ClasseChien.count equals 3 after creating v1, v2, v3.", "fr": "ClasseChien déclare static int count = 0, l'incrémente dans le constructeur, et ClasseChien.count vaut 3 après création de v1, v2, v3."}}, {"id": "m1_2", "order": 2, "title": "Shared constant and static utility methods in MathTool", "title_i18n": {"en": "Shared constant and static utility methods in MathTool", "fr": "Constante partagée et méthodes utilitaires statiques dans MathTool"}, "validation_criteria": "MathTool declares final static double PI = 3.14 and defines public static double perimetre(double r) and public static double square(double x) with correct formulas.", "validation_criteria_i18n": {"en": "MathTool declares final static double PI = 3.14 and defines public static double perimetre(double r) and public static double square(double x) with correct formulas.", "fr": "MathTool déclare final static double PI = 3.14 et définit public static double perimetre(double r) et public static double square(double x) avec les formules correctes."}}, {"id": "m1_3", "order": 3, "title": "Static invocation without new", "title_i18n": {"en": "Static invocation without new", "fr": "Appel statique sans instanciation"}, "validation_criteria": "main calls MathTool.perimetre(5) via the class name without using new MathTool.", "validation_criteria_i18n": {"en": "main calls MathTool.perimetre(5) via the class name without using new MathTool.", "fr": "Le main appelle MathTool.perimetre(5) via le nom de la classe sans utiliser new MathTool."}}], "title_i18n": {"en": "Activity 1 (Independent): Mathematical toolbox and Instance counter", "fr": "Activité N°1 (Indépendante) : Boîte à outils mathématique et Compteur d'instances"}, "target_files": ["ClasseChien.java", "MathTool.java", "Main.java"], "instructions_i18n": {"en": "Objective: practice `static` class members to count created instances and provide math utilities callable without instantiation.\\n\\n**Implementation Steps:**\\n1. Instance counter with `ClasseChien`:\\n   - Create class `ClasseChien` with a class attribute `static int count = 0;`.\\n   - In the constructor, increment the counter with `count++;`.\\n   - In `main`, instantiate three successive objects `v1`, `v2`, `v3` and display `ClasseChien.count` to verify it equals 3.\\n2. Static utility with `MathTool`:\\n   - Create class `MathTool` with a shared constant `final static double PI = 3.14;`.\\n   - Add two static methods `public static double perimetre(double r)` returning `2 * PI * r` and `public static double square(double x)` returning `x * x`.\\n   - In `main`, call directly `MathTool.perimetre(5)` without ever using `new` to instantiate `MathTool`.", "fr": "Objectif : manipuler les membres `static` pour compter les objets créés et créer des méthodes utilitaires appelables sans instanciation.\\n\\n**Étapes de réalisation :**\\n1. Le compteur d'instances avec `ClasseChien` :\\n   - Créez une classe `ClasseChien` avec un attribut de classe `static int count = 0;`.\\n   - Dans le constructeur, incrémentez ce compteur (`count++;`).\\n   - Dans la classe principale (contenant le `main`), instanciez trois objets successifs `v1`, `v2`, `v3` et affichez `ClasseChien.count` pour vérifier qu'elle vaut bien 3.\\n2. L'utilitaire statique avec `MathTool` :\\n   - Créez une classe `MathTool`.\\n   - Déclarez-y une constante partagée `final static double PI = 3.14;`.\\n   - Ajoutez deux méthodes statiques `public static double perimetre(double r)` qui retourne `2 * PI * r` et `public static double square(double x)` qui retourne `x * x`.\\n   - Dans votre `main`, appelez directement `MathTool.perimetre(5)` sans jamais utiliser le mot-clé `new` pour instancier `MathTool`."}, "instructions_markdown": "Objective: practice `static` class members to count created instances and provide math utilities callable without instantiation.\\n\\n**Implementation Steps:**\\n1. Instance counter with `ClasseChien`:\\n   - Create class `ClasseChien` with a class attribute `static int count = 0;`.\\n   - In the constructor, increment the counter with `count++;`.\\n   - In `main`, instantiate three successive objects `v1`, `v2`, `v3` and display `ClasseChien.count` to verify it equals 3.\\n2. Static utility with `MathTool`:\\n   - Create class `MathTool` with a shared constant `final static double PI = 3.14;`.\\n   - Add two static methods `public static double perimetre(double r)` returning `2 * PI * r` and `public static double square(double x)` returning `x * x`.\\n   - In `main`, call directly `MathTool.perimetre(5)` without ever using `new` to instantiate `MathTool`."}, {"id": "act_2", "order": 2, "title": "Activity 2 (Red Thread Project): Centralizing business rules in Yalla POS", "milestones": [{"id": "m2_1", "order": 1, "title": "Global VAT constant TAUX_TVA", "title_i18n": {"en": "Global VAT constant TAUX_TVA", "fr": "Constante globale TVA TAUX_TVA"}, "validation_criteria": "Article declares public static final double TAUX_TVA = 0.19 and YallaPOS uses Article.TAUX_TVA for tax calculation instead of a hard-coded local.", "validation_criteria_i18n": {"en": "Article declares public static final double TAUX_TVA = 0.19 and YallaPOS uses Article.TAUX_TVA for tax calculation instead of a hard-coded local.", "fr": "Article déclare public static final double TAUX_TVA = 0.19 et YallaPOS utilise Article.TAUX_TVA pour le calcul des taxes au lieu d'une variable locale en dur."}}, {"id": "m2_2", "order": 2, "title": "Global statistics counter with static getter", "title_i18n": {"en": "Global statistics counter with static getter", "fr": "Compteur statistique global avec accesseur statique"}, "validation_criteria": "Article declares private static int nombreArticlesCrees = 0, increments it in every constructor, and exposes public static int getNombreArticlesCrees().", "validation_criteria_i18n": {"en": "Article declares private static int nombreArticlesCrees = 0, increments it in every constructor, and exposes public static int getNombreArticlesCrees().", "fr": "Article déclare private static int nombreArticlesCrees = 0, l'incrémente dans tous les constructeurs, et expose public static int getNombreArticlesCrees()."}}, {"id": "m2_3", "order": 3, "title": "Receipt update with system statistics", "title_i18n": {"en": "Receipt update with system statistics", "fr": "Mise à jour du ticket avec statistiques système"}, "validation_criteria": "YallaPOS prints the final statistics line with Article.getNombreArticlesCrees() at the end of the receipt.", "validation_criteria_i18n": {"en": "YallaPOS prints the final statistics line with Article.getNombreArticlesCrees() at the end of the receipt.", "fr": "YallaPOS affiche la ligne finale de statistiques avec Article.getNombreArticlesCrees() à la fin du ticket de caisse."}}], "title_i18n": {"en": "Activity 2 (Red Thread Project): Centralizing business rules in Yalla POS", "fr": "Activité N°2 (Projet Fil Rouge) : Centralisation des règles métier dans Yalla POS"}, "target_files": ["Article.java", "YallaPOS.java"], "instructions_i18n": {"en": "Objective: professionalize Yalla POS by centralizing immutable business rules and global statistics with `static` and `final`.\\n\\n**Implementation Steps:**\\n1. Global constant (VAT):\\n   - In class `Article`, add a public static constant attribute `public static final double TAUX_TVA = 0.19;`.\\n   - Modify tax calculation in `YallaPOS` to use directly `Article.TAUX_TVA` instead of a hard-coded local variable.\\n2. Article counter (statistics):\\n   - In class `Article`, add `private static int nombreArticlesCrees = 0;`.\\n   - Inside all constructors of `Article`, increment this attribute by 1.\\n   - Create a static method `public static int getNombreArticlesCrees()` to allow reading the counter from outside.\\n3. Cash register update:\\n   - At the very end of the receipt printing in `YallaPOS`, add the manager statistics line using the static method call `Article.getNombreArticlesCrees()` to display the number of articles created in memory.", "fr": "Objectif : professionnaliser Yalla POS en centralisant les règles métier immuables et les statistiques globales avec `static` et `final`.\\n\\n**Étapes de réalisation :**\\n1. La Constante Globale (TVA) :\\n   - Dans la classe `Article`, ajoutez un attribut public, statique et constant : `public static final double TAUX_TVA = 0.19;`.\\n   - Modifiez le code de calcul des taxes dans `YallaPOS` pour qu'il utilise directement `Article.TAUX_TVA` au lieu d'une variable locale \\"en dur\\".\\n2. Le Compteur d'Articles (Statistiques) :\\n   - Dans la classe `Article`, ajoutez un attribut `private static int nombreArticlesCrees = 0;`.\\n   - À l'intérieur de tous les constructeurs de `Article`, incrémentez cet attribut de 1.\\n   - Créez une méthode statique `public static int getNombreArticlesCrees()` pour permettre la lecture de ce compteur depuis l'extérieur.\\n3. Mise à jour de la caisse :\\n   - À la toute fin de l'impression du ticket de caisse dans `YallaPOS`, ajoutez une ligne de statistiques `*** Statistiques du système : [X] articles créés en mémoire aujourd'hui ***` en remplaçant `[X]` par l'appel à `Article.getNombreArticlesCrees()`."}, "instructions_markdown": "Objective: professionalize Yalla POS by centralizing immutable business rules and global statistics with `static` and `final`.\\n\\n**Implementation Steps:**\\n1. Global constant (VAT):\\n   - In class `Article`, add a public static constant attribute `public static final double TAUX_TVA = 0.19;`.\\n   - Modify tax calculation in `YallaPOS` to use directly `Article.TAUX_TVA` instead of a hard-coded local variable.\\n2. Article counter (statistics):\\n   - In class `Article`, add `private static int nombreArticlesCrees = 0;`.\\n   - Inside all constructors of `Article`, increment this attribute by 1.\\n   - Create a static method `public static int getNombreArticlesCrees()` to allow reading the counter from outside.\\n3. Cash register update:\\n   - At the very end of the receipt printing in `YallaPOS`, add the manager statistics line using the static method call `Article.getNombreArticlesCrees()` to display the number of articles created in memory."}]	{STATIC_FINAL_MEMBERS,CONSTRUCTORS_THIS,CLASS_OBJECT_REFERENCES}	[{"key": "act_1_buggy", "files": [{"name": "ClasseChien.java", "content": "public class ClasseChien {\\n  int count = 0;\\n  public ClasseChien() {\\n    count++;\\n  }\\n  public int getCount() {\\n    return count;\\n  }\\n}"}, {"name": "MathTool.java", "content": "public class MathTool {\\n  double PI = 3.14;\\n  public double perimetre(double r) {\\n    return 2 * PI * r;\\n  }\\n  public double square(double x) {\\n    return x * x;\\n  }\\n}"}, {"name": "Main.java", "content": "public class Main {\\n  public static void main(String[] args) {\\n    ClasseChien v1 = new ClasseChien();\\n    ClasseChien v2 = new ClasseChien();\\n    ClasseChien v3 = new ClasseChien();\\n    System.out.println(v3.getCount());\\n    MathTool m = new MathTool();\\n    System.out.println(m.perimetre(5));\\n    System.out.println(m.square(4));\\n  }\\n}"}], "label": "1. Buggy Counter and Utility (Missing static)", "activity_id": "act_1", "description": "Counter is instance field and utility methods require new, so count never reaches 3.", "preset_type": "buggy"}, {"key": "act_1_solution", "files": [{"name": "ClasseChien.java", "content": "public class ClasseChien {\\n  static int count = 0;\\n  public ClasseChien() {\\n    count++;\\n  }\\n}"}, {"name": "MathTool.java", "content": "public class MathTool {\\n  final static double PI = 3.14;\\n  public static double perimetre(double r) {\\n    return 2 * PI * r;\\n  }\\n  public static double square(double x) {\\n    return x * x;\\n  }\\n}"}, {"name": "Main.java", "content": "public class Main {\\n  public static void main(String[] args) {\\n    ClasseChien v1 = new ClasseChien();\\n    ClasseChien v2 = new ClasseChien();\\n    ClasseChien v3 = new ClasseChien();\\n    System.out.println(ClasseChien.count);\\n    System.out.println(MathTool.perimetre(5));\\n    System.out.println(MathTool.square(4));\\n  }\\n}"}], "label": "2. Validated Solution (Static Counter and MathTool)", "activity_id": "act_1", "description": "Correct static counter and static utility with shared PI constant called without new.", "preset_type": "solution"}, {"key": "act_2_buggy", "files": [{"name": "Article.java", "content": "public class Article {\\n  public double TAUX_TVA = 0.19;\\n  int nombreArticlesCrees = 0;\\n  private String nom;\\n  private double prixHT;\\n  public Article(String nom, double prixHT) {\\n    this.nom = nom;\\n    this.prixHT = prixHT;\\n    nombreArticlesCrees++;\\n  }\\n  public Article() {\\n    nombreArticlesCrees++;\\n  }\\n  public int getNombreArticlesCrees() {\\n    return nombreArticlesCrees;\\n  }\\n  public double prixTTC() {\\n    return prixHT * (1 + TAUX_TVA);\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    double tvaLocale = 0.19;\\n    Article a1 = new Article(\\"Cafe\\", 10.0);\\n    Article a2 = new Article(\\"The\\", 5.0);\\n    double total = a1.prixTTC() + a2.prixTTC();\\n    System.out.println(\\"Total TTC: \\" + total + \\" TVA locale: \\" + tvaLocale);\\n    System.out.println(\\"*** Statistiques du systeme : \\" + a1.getNombreArticlesCrees() + \\" articles crees en memoire aujourd'hui ***\\");\\n  }\\n}"}], "label": "1. Buggy Yalla POS (Local VAT, Instance Counter)", "activity_id": "act_2", "description": "VAT is hard-coded local and article count is per-instance, so global statistics are wrong.", "preset_type": "buggy"}, {"key": "act_2_solution", "files": [{"name": "Article.java", "content": "public class Article {\\n  public static final double TAUX_TVA = 0.19;\\n  private static int nombreArticlesCrees = 0;\\n  private String nom;\\n  private double prixHT;\\n  public Article(String nom, double prixHT) {\\n    this.nom = nom;\\n    this.prixHT = prixHT;\\n    nombreArticlesCrees++;\\n  }\\n  public Article() {\\n    nombreArticlesCrees++;\\n  }\\n  public static int getNombreArticlesCrees() {\\n    return nombreArticlesCrees;\\n  }\\n  public double prixTTC() {\\n    return prixHT * (1 + TAUX_TVA);\\n  }\\n}"}, {"name": "YallaPOS.java", "content": "public class YallaPOS {\\n  public static void main(String[] args) {\\n    Article a1 = new Article(\\"Cafe\\", 10.0);\\n    Article a2 = new Article(\\"The\\", 5.0);\\n    double total = a1.prixTTC() + a2.prixTTC();\\n    System.out.println(\\"TVA utilisee: \\" + Article.TAUX_TVA);\\n    System.out.println(\\"Total TTC: \\" + total);\\n    System.out.println(\\"*** Statistiques du systeme : \\" + Article.getNombreArticlesCrees() + \\" articles crees en memoire aujourd'hui ***\\");\\n  }\\n}"}], "label": "2. Validated Solution (Centralized VAT and Statistics)", "activity_id": "act_2", "description": "Centralized immutable VAT and global static counter read via static getter in receipt.", "preset_type": "solution"}]	t	2026-11-01 23:16:43.39+00	[{"page": 1, "text": "TP 6 : Membres de classe ( static ) et Constantes ( final )\\nObjectifs pédagogiques : À la fin de ce TP, l'étudiant sera capable de :\\n Comprendre la différence entre une variable d'instance (propre à chaque objet) et\\nune variable de classe (partagée par tous les objets) via le mot-clé static .\\n Créer et utiliser des méthodes statiques, qui peuvent être appelées sans instancier\\nd'objet.\\n Définir des constantes immuables à l'aide du mot-clé final .\\nNote : Avant de plonger dans l'héritage abordé à la fin du TP précédent, nous devons finaliser\\nnotre maîtrise des classes en explorant les éléments partagés !\\nActivité N°1 (Indépendante) : Boîte à outils mathématique et Compteur d'instances\\nDans cette activité, nous allons manipuler les membres statiques pour créer des méthodes\\nutilitaires et compter le nombre d'objets créés en mémoire.\\n1. Le compteur d'instances :\\no Créez une classe ClasseChien avec un attribut de classe static int count\\n= 0; .\\no Dans le constructeur de la classe, incrémentez ce compteur ( count++; ).\\no Dans votre classe principale (contenant le main ), instanciez trois objets\\nClasseChien successifs ( v1 , v2 , v3 ). Affichez la valeur de\\nClasseChien.count pour vérifier qu'elle vaut bien 3.\\n2. L'utilitaire statique :\\no Créez une classe MathTool .\\no Déclarez-y une constante partagée avec les mots-clés final static double\\nPI = 3.14; .\\no Ajoutez deux méthodes statiques : public static double\\nperimetre(double r) qui retourne 2 ∗ PI ∗ r2 * PI * r2 ∗ PI ∗ r, et public\\nstatic double square(double x) qui retourne x ∗ xx * xx ∗ x.\\no Dans votre main , appelez directement MathTool.perimetre(5) sans jamais\\nutiliser le mot-clé new pour instancier MathTool .\\nActivité N°2 (Projet Fil Rouge) : Centralisation des règles métier dans Yalla POS\\nJusqu'à présent, le taux de TVA était défini comme une simple variable locale dans la caisse,\\net nous ne gardions aucune trace globale du volume d'articles manipulés par le système.\\nNous allons utiliser static et final pour professionnaliser cela.\\nTravail demandé :\\n1. La Constante Globale (TVA) :"}, {"page": 2, "text": "TP 6 : Membres de classe (static) et Constantes (final) Mohamed Belhassen\\no Dans la classe Article , le taux de TVA (19%) est une règle fiscale qui\\ns'applique à tous les articles standard et qui ne doit jamais être modifiée par\\nerreur.\\no Ajoutez un attribut public, statique et constant : public static final\\ndouble TAUX_TVA = 0.19; .\\no Modifiez le code de calcul des taxes dans votre classe YallaPOS pour qu'il\\nutilise directement Article.TAUX_TVA au lieu d'une variable locale \\"en dur\\".\\n2. Le Compteur d'Articles (Statistiques) :\\no Dans la classe Article , ajoutez un attribut private static int\\nnombreArticlesCrees = 0; .\\no À l'intérieur de tous les constructeurs de la classe Article , incrémentez cet\\nattribut de 1.\\no Créez une méthode statique public static int\\ngetNombreArticlesCrees() pour permettre la lecture de ce compteur\\ndepuis l'extérieur.\\n3. Mise à jour de la caisse :\\no À la toute fin de l'impression de votre ticket de caisse dans YallaPOS , ajoutez\\nune ligne de statistiques pour le gérant : *** Statistiques du système :\\n[X] articles créés en mémoire aujourd'hui *** (en remplaçant [X]\\npar l'appel à votre méthode statique).\\nBilan du TP 6 : Ce qu'il faut retenir À la fin de ce TP, vous devez avoir validé les points\\nsuivants :\\n [ ] Attributs static : Vous avez compris qu'une variable statique existe en un seul\\nexemplaire partagé par toutes les instances de la classe.\\n [ ] Méthodes static : Vous savez déclarer des méthodes utilitaires accessibles\\ndirectement via le nom de la classe (ex: Article.getNombreArticlesCrees() ).\\n [ ] Constantes final : Vous savez protéger une valeur pour la rendre immuable une\\nfois initialisée.\\n [ ] Yalla POS : Votre système centralise désormais ses règles immuables (TVA) et peut\\nsuivre l'activité globale du logiciel indépendamment des objets individuels.\\nLa suite : Maintenant que nous maîtrisons parfaitement l'intérieur d'une classe (attributs,\\nméthodes, constructeurs, visibilité, membres statiques), nous pouvons enfin tenir la\\npromesse du TP précédent ! Lors du prochain TP, nous allons faire évoluer notre catalogue\\nYalla POS en découvrant l'Héritage (mot-clé extends ). Nous créerons de nouvelles classes\\ncomme ArticlePerissable (avec une date de péremption) et ArticleElectronique (avec\\nune garantie) qui hériteront automatiquement de toutes les caractéristiques de notre\\nArticle de base, tout en se spécialisant."}]	{"en": "TP 6 — Lab 6: Class Members (static) and Constants (final)", "fr": "TP 6 : Membres de classe ( static ) et Constantes ( final )"}	{"en": "This lab teaches the difference between instance and class members with static and immutable constants with final, centralizing VAT rules and global article statistics in Yalla POS.", "fr": "Ce TP enseigne la différence entre variables d'instance et variables de classe avec static et les constantes immuables avec final, en centralisant la TVA et les statistiques globales dans Yalla POS."}	2026-11-02 20:07:42.438083+00
\.


